            /// <summary>
            /// 注册第 Index（1–12）个快捷键并记下来。与 WinForms 的 HotKeySetting.bHotKeyN_Click 一致：按下那一刻就注册，不等保存。
            /// 需要主窗口句柄（InitHotKeys 设的 MainHandle），外壳在进代理模式时调过。
            /// </summary>
            public static bool RegisterHotkey_Shell(int Index, string Text)
            {
                try
                {
                    if (Index < 1 || Index > 12) { return false; }

                    Text = (Text ?? string.Empty).Trim();
                    if (!RegisterHotkey_FromText(9000 + Index, Text)) { return false; }

                    switch (Index)
                    {
                        case 1: HotKey1 = Text; break;
                        case 2: HotKey2 = Text; break;
                        case 3: HotKey3 = Text; break;
                        case 4: HotKey4 = Text; break;
                        case 5: HotKey5 = Text; break;
                        case 6: HotKey6 = Text; break;
                        case 7: HotKey7 = Text; break;
                        case 8: HotKey8 = Text; break;
                        case 9: HotKey9 = Text; break;
                        case 10: HotKey10 = Text; break;
                        case 11: HotKey11 = Text; break;
                        case 12: HotKey12 = Text; break;
                    }

                    SaveSystemConfig_ToDB();
                    return true;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(RegisterHotkey_Shell), ex);
                    return false;
                }
            }

            public static void SaveHotkeyType_Shell(int Type)
            {
                HotKeyType = Type == 1 ? 1 : 0;
                SaveSystemConfig_ToDB();
                UI.Toast(UiIcon.Success, UI.T("HotKeyForm.Save.Success", "快捷键保存成功"));
            }

            public static RemoteSettingRow GetRemoteSetting()
            {
                var r = new RemoteSettingRow();

                try
                {
                    var ips = new List<string>();
                    foreach (IPAddress ip in GetLocalIPAddress() ?? new IPAddress[0]) { ips.Add(ip.ToString()); }
                    if (ips.Count == 0) { ips.Add("127.0.0.1"); }

                    /*
                        ⚠️ 显示<b>实际保存的</b>地址（2026-09-11 改）。原来它不在本机网卡列表里时（换了网络 / DHCP 重新分配）
                        悄悄显示第一个网卡的 IP —— 而服务仍按旧地址去绑，于是起不来，设置页上看着却一切正常。
                        现在把它原样放在列表最前面、标出 IPMissing，由设置页提示用户换一个。
                    */
                    if (!string.IsNullOrEmpty(Remote_IP) && !ips.Contains(Remote_IP))
                    {
                        ips.Insert(0, Remote_IP);
                        r.IPMissing = true;
                    }

                    r.IPs = ips.ToArray();
                    r.IP = string.IsNullOrEmpty(Remote_IP) ? ips[0] : Remote_IP;
                    r.IsRemote = IsRemote;
                    r.Port = Remote_Port;
                    r.UserName = Remote_UserName ?? string.Empty;
                    r.PassWord = Remote_PassWord ?? string.Empty;
                    r.Running = WebServer != null;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(GetRemoteSetting), ex);
                }

                return r;
            }

            /// <summary>照 WinForms 的 RemoteMGTSetting.bSave_Click：校验 → 写字段 → 起 / 停 → 落库。返回空串 = 成功。</summary>
            public static string SaveRemoteSetting(bool IsRemoteNew, string IP, int Port, string UserName, string PassWord)
            {
                try
                {
                    UserName = (UserName ?? string.Empty).Trim();
                    PassWord = (PassWord ?? string.Empty).Trim();

                    if (IsRemoteNew)
                    {
                        if (string.IsNullOrEmpty(UserName)) { return UI.T("RemoteMGTSetting.UserName.Empty", "管理员账号为空"); }
                        if (string.IsNullOrEmpty(PassWord)) { return UI.T("RemoteMGTSetting.PassWord.Empty", "账号密码为空"); }
                    }

                    IsRemote = IsRemoteNew;
                    Remote_IP = (IP ?? string.Empty).Trim();
                    Remote_Port = (ushort)Math.Max(1, Math.Min(65535, Port));
                    Remote_UserName = UserName;
                    Remote_PassWord = PassWord;

                    string error = string.Empty;

                    if (IsRemote) { error = StartRemoteMGT(); }
                    else { StopRemoteMGT(); }

                    //起不来也照样保存（用户下一步多半就是改端口）；原因交回设置弹窗显示，弹窗不关
                    SaveSystemConfig_ToDB();
                    return error;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(SaveRemoteSetting), ex);
                    return ex.Message;
                }
            }

            /// <summary>
            /// 统计数据页的七个计数（照 WinForms 的 StatisticalData.bgwStatistical_DoWork）。
            ///
            /// ⚠️ <b>分母按模式取</b>。WinForms 那个控件两种模式共用，而分母写死是代理的四个计数器
            /// —— 所以在注入模式下六条进度条的百分比<b>恒为 0</b>（那是个老毛病，不是这里新引入的）。
            /// 注入模式该拿 <c>PacketConfig.Packet.TotalPackets</c>：滤镜执行次数是两种模式共用的，
            /// 拿它去除一个恒为 0 的分母毫无意义。
            /// </summary>
            public static FilterStatsRow GetFilterStats()
            {
                bool inject = SystemConfig.SelectMode == SystemConfig.SystemMode.Inject;

                return new FilterStatsRow
                {
                    ProxyTotal = inject
                        ? PacketConfig.Packet.TotalPackets
                        : ProxyConfig.Proxy.TCP_Req_CNT + ProxyConfig.Proxy.TCP_Resp_CNT + ProxyConfig.Proxy.UDP_Req_CNT + ProxyConfig.Proxy.UDP_Resp_CNT,
                    Hit = inject ? PacketConfig.Packet.FilterPacket_CNT : ProxyConfig.Proxy.FilterProxy_CNT,
                    Execute = FilterConfig.Filter.FilterExecute_CNT,
                    Replace = FilterConfig.Filter.FilterReplace_CNT,
                    Change = FilterConfig.Filter.FilterChange_CNT,
                    Intercept = FilterConfig.Filter.FilterIntercept_CNT,
                    Display = FilterConfig.Filter.FilterDisplay_CNT,
                    NoDisplay = FilterConfig.Filter.FilterNoDisplay_CNT,
                };
            }

            /// <summary>
            /// 把<b>滤镜</b>的统计计数归零：六个全局计数 + 每条滤镜的执行次数。
            ///
            /// 注入模式下这几个的真源在目标进程里，所以外壳要经 <c>ShellLink.ResetStats</c>
            /// 把这件事发下去；目标那边的控制线程调的就是本方法。
            /// </summary>
            public static void ResetFilterStats()
            {
                FilterConfig.Filter.FilterExecute_CNT = 0;
                FilterConfig.Filter.FilterReplace_CNT = 0;
                FilterConfig.Filter.FilterChange_CNT = 0;
                FilterConfig.Filter.FilterIntercept_CNT = 0;
                FilterConfig.Filter.FilterDisplay_CNT = 0;
                FilterConfig.Filter.FilterNoDisplay_CNT = 0;

                FilterConfig.List.InitFilterList_Count();
            }

            /// <summary>
            /// 把某一种模式的<b>封包计数</b>归零，逐条对应 WinForms 的
            /// <c>ProxyList.CleanUp_ProxyListInfo</c> / <c>PacketList.CleanUp_PacketListInfo</c>。
            ///
            /// ⚠️ 外壳的「清空」原来<b>只清列表、不清计数</b> —— 与 WinForms 不一致，
            /// 表现是「列表空了，可统计格里的代理总数 / 流量 / 滤镜执行还举着清空前的数」，
            /// 而且统计数据页那六条进度条<b>再也没有办法归零</b>（外壳没有别的入口）。
            /// </summary>
            public static void ResetPacketCounters(bool inject)
            {
                if (inject)
                {
                    PacketConfig.Packet.TotalPackets = 0;
                    PacketConfig.Packet.Total_SendBytes = 0;
                    PacketConfig.Packet.Total_RecvBytes = 0;
                    PacketConfig.Packet.FilterPacket_CNT = 0;
                    PacketConfig.Packet.Send_CNT = 0;
                    PacketConfig.Packet.Recv_CNT = 0;
                    PacketConfig.Packet.SendTo_CNT = 0;
                    PacketConfig.Packet.RecvFrom_CNT = 0;
                    PacketConfig.Packet.WSASend_CNT = 0;
                    PacketConfig.Packet.WSARecv_CNT = 0;
                    PacketConfig.Packet.WSASendTo_CNT = 0;
                    PacketConfig.Packet.WSARecvFrom_CNT = 0;
                }
                else
                {
                    ProxyConfig.Proxy.ProxyTotal_CNT = 0;
                    ProxyConfig.Proxy.TCP_Req_CNT = 0;
                    ProxyConfig.Proxy.TCP_Resp_CNT = 0;
                    ProxyConfig.Proxy.UDP_Req_CNT = 0;
                    ProxyConfig.Proxy.UDP_Resp_CNT = 0;
                    ProxyConfig.Proxy.FilterProxy_CNT = 0;
                    ProxyConfig.Proxy.Total_Request = 0;
                    ProxyConfig.Proxy.Total_Response = 0;
                }
            }

