            public static bool IsValidIPv4(string ipString)
            {
                if (string.IsNullOrWhiteSpace(ipString))
                    return false;

                string pattern = @"^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$";
                return Regex.IsMatch(ipString, pattern);
            }

