            public static void LoadSystemConfig_FromDB()
            {
                try
                {
                    Operate.DataBase.InitConStr();

                    string Lang = "zh-CN";

                    DataTable dtSystemConfig = DataBase.SelectTable_SystemConfig();
                    if (dtSystemConfig.Rows.Count > 0)
                    {
                        UI.Prefs.IsAnimation = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsAnimation"]);
                        UI.Prefs.IsShadowEnabled = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsShadowEnabled"]);
                        UI.Prefs.IsShowInWindow = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsShowInWindow"]);
                        UI.Prefs.IsScrollBarHide = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsScrollBarHide"]);
                        UI.Prefs.IsTextRenderingHighQuality = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsTextRenderingHighQuality"]);
                        UI.Prefs.IsDark = Convert.ToBoolean(dtSystemConfig.Rows[0]["IsDark"]);
                        /*
                            这一列是后加的。EnsureColumn 会给老库补上，但备份导入的
                            那条路可能塞进来一张没有这列的表，所以这里再兜一次 ——
                            读不到就是「不跟随系统」，与列的默认值一致。
                        */
                        if (dtSystemConfig.Columns.Contains("ThemeFollowSystem"))
                        {
                            UI.Prefs.FollowSystemTheme = Convert.ToBoolean(dtSystemConfig.Rows[0]["ThemeFollowSystem"]);
                        }
                        
                        Lang = dtSystemConfig.Rows[0]["DefaultLanguage"].ToString();
                        SystemConfig.LastInjection = dtSystemConfig.Rows[0]["LastInjection"].ToString();

                        //上次注入那条记录的另外四列是后加的：老库经 EnsureColumn 补过，
                        //备份导入那条路仍可能塞进来一张没有它们的表，所以逐列兜一次
                        if (dtSystemConfig.Columns.Contains("LastInjectMethod"))
                        {
                            SystemConfig.LastInjectMethod = Convert.ToInt32(dtSystemConfig.Rows[0]["LastInjectMethod"]);
                        }

                        if (dtSystemConfig.Columns.Contains("LastInjectPath"))
                        {
                            SystemConfig.LastInjectPath = dtSystemConfig.Rows[0]["LastInjectPath"].ToString();
                        }

                        if (dtSystemConfig.Columns.Contains("LastInjectArgs"))
                        {
                            SystemConfig.LastInjectArgs = dtSystemConfig.Rows[0]["LastInjectArgs"].ToString();
                        }

                        if (dtSystemConfig.Columns.Contains("LastInjectTime"))
                        {
                            SystemConfig.LastInjectTime = dtSystemConfig.Rows[0]["LastInjectTime"].ToString();
                        }
                        SystemConfig.IsRemote = Convert.ToBoolean(dtSystemConfig.Rows[0]["Remote_IsEnable"]);
                        SystemConfig.Remote_UserName = dtSystemConfig.Rows[0]["Remote_UserName"].ToString();
