            #region//导出系统备份到文件（对话框）

            /// <summary>
            /// 备份要带哪几样。
            ///
            /// ⚠️ <b>刻意做成具名属性，不再是一串位置 bool。</b>
            /// 原来是 11 个 bool 顺着排，调用点靠位置对齐 —— 加一项要同时改
            /// 「Operate 的签名 / Dialog 的签名 / 桥里那一串 f("…") / Vue 的 GROUPS」
            /// 四处，<b>顺序错位了编译器一声不吭</b>。换成属性之后位置不再有意义，
            /// 加一项也只是多一个赋值。
            ///
            /// 新增一项要过四处：这个类、导出里的一段、导入里的一段、桥 + 前端各一行。
            /// </summary>
            public class BackupParts
            {
                public bool SystemConfig { get; set; }
                public bool ProxySet { get; set; }
                public bool ProxyAccount { get; set; }
                public bool WhiteList { get; set; }
                public bool BlackList { get; set; }
                public bool ProxyMapping { get; set; }
                public bool InjectSet { get; set; }
                public bool FilterList { get; set; }
                public bool SendList { get; set; }
                public bool RobotList { get; set; }
                public bool WareHouse { get; set; }
                public bool AutoStores { get; set; }
                public bool WpcServer { get; set; }
                public bool WpcNotice { get; set; }

                /// <summary>一个都没勾。导出前拦一下，别产出一个只有根节点的空备份。</summary>
                public bool IsEmpty
                {
                    get
                    {
                        return !SystemConfig && !ProxySet && !ProxyAccount && !WhiteList && !BlackList
                            && !ProxyMapping && !InjectSet && !FilterList && !SendList && !RobotList
                            && !WareHouse && !AutoStores && !WpcServer && !WpcNotice;
                    }
                }
            }

            /// <summary>
            /// <b>WinForms 那条线用的兼容重载</b>（`Controls/BackUpSetting.cs`）。
            ///
            /// ⚠️ <b>新代码不要用它。</b>它按位置收那 11 个 bool，正是要被淘汰的写法；
            /// 留着只是因为「原有的 WinForms 项目不动」——那边的界面上也没有
            /// 仓库 / 自动入库 / WPC 那四个新分组，所以这个重载永远只勾得到前十项。
            /// 哪天 WinForms 那条线要删或要跟上，连这个重载一起处理。
            /// </summary>
            public static Task ExportSystemBackUp_Dialog(
                string FileName,
                bool bSystemConfig,
                bool bProxySet,
                bool bProxyAccount,
                bool bWhiteList,
                bool bBlackList,
                bool bProxyMapping,
                bool bInjectionSet,
                bool bFilterList,
                bool bSendList,
                bool bRobotList)
            {
                return ExportSystemBackUp_Dialog(FileName, new BackupParts
                {
                    SystemConfig = bSystemConfig,
                    ProxySet = bProxySet,
                    ProxyAccount = bProxyAccount,
                    WhiteList = bWhiteList,
                    BlackList = bBlackList,
                    ProxyMapping = bProxyMapping,
                    InjectSet = bInjectionSet,
                    FilterList = bFilterList,
                    SendList = bSendList,
                    RobotList = bRobotList,
                });
            }

            public static async Task ExportSystemBackUp_Dialog(string FileName, BackupParts Parts)
            {
                try
                {
                    /*
                        一个都没勾就别往下走。前端那颗按钮有 disabled，但这一层原来没拦 ——
                        真走到底会产出一个只有根节点的 .sb，导入时静默什么都不做。
                    */
                    if (Parts == null || Parts.IsEmpty)
                    {
                        UI.Toast(UiIcon.Warn, UI.T("BackUpSettingsForm.NothingSelected", "请先勾选要备份的内容"));
                        return;
                    }

                    FilePick sfdSaveFile = new FilePick();
                    sfdSaveFile.Filter = "WPE x64（*.sb）|*.sb";

                    if (!string.IsNullOrEmpty(FileName))
                    {
                        sfdSaveFile.FileName = FileName;
                    }

                    string sPickedPath = await UI.PickSave(sfdSaveFile);
                    if (!string.IsNullOrEmpty(sPickedPath))
                    {
                        string FilePath = sPickedPath;
                        if (!string.IsNullOrEmpty(FilePath))
                        {
                            var EncryptPassword = await SystemConfig.GetEncryptExportAsync(UI.T("BackUpSettingsForm.Export", "导出系统备份"));

                            bool bOK = SystemConfig.ExportSystemBackUp(
                                FilePath,
                                Parts,
                                EncryptPassword.DoEncrypt,
                                EncryptPassword.Password);

                            if (bOK)
                            {
                                string Title = UI.T("BackUpSettingsForm.Export.Success", "导出系统备份成功");
                                UI.Notify(UiIcon.Success, Title, FilePath);
                                Operate.DoLog(nameof(ExportSystemBackUp_Dialog), Title + ": " + FilePath);
                            }
                            else
                            {
                                string Title = UI.T("BackUpSettingsForm.Export.Fail", "导出系统备份失败");
                                string Content = UI.T("CheckSystemLog", "请检查系统日志");
                                UI.Notify(UiIcon.Error, Title, Content);
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(ExportSystemBackUp_Dialog), ex);
                }
            }

            private static bool ExportSystemBackUp(
                string FilePath,
                BackupParts Parts,
                bool DoEncrypt,
                string Password)
            {
                try
                {
                    XDocument xdoc = new XDocument
                    {
                        Declaration = new XDeclaration("1.0", "utf-8", "yes")
                    };

                    XElement xeBackUp = new XElement("WPE64_BackUp");

                    /*
                        ⚠️ <b>「这一节没写进去」有两种原因，必须分开对待。</b>

                        ① <b>列表本来就是空的</b> —— 下面各列表节前面那句 `Count > 0`。
                           空列表写个空壳没意义，跳过是对的，也是既定语义：导入端是
                           「节在就先清空再装、节不在就一个字都不动」，所以<b>源端为空不会</b>
                           把目标机上的同名列表清掉（弹窗底下那句提示已按这个口径改过）。
                        ② <b>`Get*_XML` 返回了 null</b> —— 那十五个方法一律是
                           `try { 拼 } catch { 记日志 } return null`，<b>返回 null 只可能是抛异常了</b>。

                        原来两种情况共用同一条静默路径（`if (xe != null) { Add }`），于是第 ② 种
                        表现成「导出报成功，可备份里少了一整节」，用户毫无察觉 —— 真撞到过：
                        `ProxyConfig.Proxy` 的静态构造按<b>工作目录</b>找 `IPLocation/qqwry.dat`，
                        找不到就把 `GetProxyMode_XML` 整个带崩，代理设置那一节静静地没了。
                        三个配置节（SystemConfig / ProxyMode / InjectMode）尤其危险：
                        它们<b>没有</b>第 ① 层守卫，null 是它们唯一的缺席理由。

                        现在把失败的节名收起来，<b>在写文件之前</b>统一判失败 ——
                        放在 `Save` 之前，磁盘上就不会留下半份备份，也就不用再去删
                        （与下面「要求加密却没密码」那条不同：那条是写完了才发现，只能删）。
                        节名取的是<b>XML 元素名</b>，日志里看到哪个，就直接去 .sb 里找哪个。
                    */
                    List<string> broken = new List<string>();

                    Action<string, XElement> add = (Name, xe) =>
                    {
                        if (xe == null) { broken.Add(Name); return; }

                        xeBackUp.Add(xe);
                    };

                    //系统设置
                    if (Parts.SystemConfig)
                    {
                        add("SystemConfig", SystemConfig.GetSystemConfig_XML());
                    }

                    //代理设置
                    if (Parts.ProxySet)
                    {
                        add("ProxyMode", SystemConfig.GetProxyMode_XML());
                    }

                    //代理账号
                    if (Parts.ProxyAccount && ProxyConfig.Account.lstAccountInfo.Count > 0)
                    {
                        add("ProxyAccountList", ProxyConfig.Account.GetAccountList_XML(ProxyConfig.Account.lstAccountInfo.ToList()));
                    }

                    //白名单
                    if (Parts.WhiteList && ProxyConfig.Proxy.lstWhiteList.Count > 0)
                    {
                        add("WhiteList", ProxyConfig.Proxy.GetWhiteList_XML(ProxyConfig.Proxy.lstWhiteList));
                    }

                    //黑名单
                    if (Parts.BlackList && ProxyConfig.Proxy.lstBlackList.Count > 0)
                    {
                        add("BlackList", ProxyConfig.Proxy.GetBlackList_XML(ProxyConfig.Proxy.lstBlackList));
                    }

                    /*
                        代理映射 —— <b>本地与远程两份都要导</b>。

                        ⚠️ 这里原来只导了本地：`GetMapRemote_XML` 一直存在、导入那边也一直在读
                        `MapRemote` 这一节，只有导出漏了它。界面上那个勾选框写的是「代理映射」，
                        用户勾了它，<b>远程映射被静默丢掉</b> —— 换台机器才发现少了一半。
                    */
                    if (Parts.ProxyMapping)
                    {
                        //本地映射
                        if (ProxyConfig.Mapping.lstMapLocal.Count > 0)
                        {
                            add("MapLocal", ProxyConfig.Mapping.GetMapLocal_XML(ProxyConfig.Mapping.lstMapLocal));
                        }

                        //远程映射
                        if (ProxyConfig.Mapping.lstMapRemote.Count > 0)
                        {
                            add("MapRemote", ProxyConfig.Mapping.GetMapRemote_XML(ProxyConfig.Mapping.lstMapRemote));
                        }
                    }

                    //注入设置
                    if (Parts.InjectSet)
                    {
                        add("InjectMode", SystemConfig.GetInjectMode_XML());
                    }

                    //滤镜列表
                    if (Parts.FilterList && FilterConfig.List.lstFilterInfo.Count > 0)
                    {
                        add("FilterList", FilterConfig.List.GetFilterList_XML(FilterConfig.List.lstFilterInfo.ToList()));
                    }

                    //发送列表
                    if (Parts.SendList && SendConfig.List.lstSendInfo.Count > 0)
                    {
                        add("SendList", SendConfig.List.GetSendList_XML(SendConfig.List.lstSendInfo.ToList()));
                    }

                    //机器人列表
                    if (Parts.RobotList && RobotConfig.List.lstRobotInfo.Count > 0)
                    {
                        add("RobotList", RobotConfig.List.GetRobotList_XML(RobotConfig.List.lstRobotInfo.ToList()));
                    }

                    /*
                        ⚠️ <b>仓库可能很大。</b>仓储封包是 base64 的原始字节，自动入库开着抓一阵
                        就能到几万条 —— 50000 条 × 512 字节实测已经是十几 MB 的 XML。
                        所以它是<b>单独一个勾选项</b>，默认不勾；用户要带就带，别混在「列表清单」里
                        让人不知不觉导出一个几百 MB 的文件。
                    */
                    if (Parts.WareHouse && WareHouseConfig.List.lstWareHouseInfo.Count > 0)
                    {
                        add("WareHouseList", WareHouseConfig.List.GetWareHouseList_XML(WareHouseConfig.List.lstWareHouseInfo.ToList()));
                    }

                    //自动入库规则（包头 → 仓库），与仓库分开勾：规则很小，仓库很大
                    if (Parts.AutoStores && WareHouseConfig.List.lstAutoStoresInfo.Count > 0)
                    {
                        add("AutoStores", WareHouseConfig.List.GetAutoStores_XML(WareHouseConfig.List.lstAutoStoresInfo));
                    }

                    /*
                        WPC 节点与公告 —— 这两份是<b>对外发布给客户端</b>的东西
                        （/ProxyCap/GetServerList 与 /GetNoticeList 下发的就是它们），
                        重配代价最大，却一直不在备份里。
                    */
                    if (Parts.WpcServer && WPCConfig.ServerList.lstServerInfo.Count > 0)
                    {
                        add("ServerList", WPCConfig.ServerList.GetServerList_XML(WPCConfig.ServerList.lstServerInfo));
                    }

                    if (Parts.WpcNotice && WPCConfig.NoticeList.lstNoticeInfo.Count > 0)
                    {
                        add("NoticeList", WPCConfig.NoticeList.GetNoticeList_XML(WPCConfig.NoticeList.lstNoticeInfo));
                    }

                    /*
                        有分节生成失败就别写文件了 —— 一份「缺了整节却看着正常」的备份
                        比没有备份更糟：用户拿它去恢复，那一节的设置一声不响地保持旧值。
                        调用方（ExportSystemBackUp_Dialog）收到 false 会弹「导出失败 · 请检查系统日志」，
                        上面那条日志里写着是哪一节。
                    */
                    if (broken.Count > 0)
                    {
                        Operate.DoLog(nameof(ExportSystemBackUp), string.Format(
                            UI.T("BackUpSettingsForm.Export.SectionFailed",
                                 "以下分节生成失败（原因见上面的异常日志），已放弃导出：{0}"),
                            string.Join("、", broken)));

                        return false;
                    }

                    xdoc.Add(xeBackUp);
                    xdoc.Save(FilePath);

                    /*
                        ⚠️ <b>说要加密就必须真加密，没密码要当失败处理。</b>

                        原来是「DoEncrypt 为真、密码为空 → 什么都不做」，于是磁盘上留下的是
                        <b>明文</b>，而界面照样报「导出成功」。目前走不到这条路
                        （GetEncryptExportAsync 密码为空时返回的是 DoEncrypt = false），
                        但那是靠调用方兜着的 —— 多一个调用方就会漏，
                        而漏掉的后果是用户以为加密了的那份里躺着代理账号与远程管理的口令。

                        失败时把半成品删掉，别在磁盘上留一份明文备份。
                    */
                    if (DoEncrypt)
                    {
                        if (string.IsNullOrEmpty(Password))
                        {
                            Operate.DoLog(nameof(ExportSystemBackUp),
                                UI.T("BackUpSettingsForm.Encrypt.NoPassword", "要求加密但没有密码，已放弃导出"));

                            try { if (File.Exists(FilePath)) { File.Delete(FilePath); } }
                            catch (Exception exDel) { Operate.DoLog(nameof(ExportSystemBackUp) + ".Delete", exDel); }

                            return false;
                        }

                        SystemConfig.EncryptXMLFile(FilePath, Password);
                    }

                    return true;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(ExportSystemBackUp), ex);
                }

                return false;
            }

            #endregion

            #region//从文件导入系统备份（对话框）

            public static async Task ImportSystemBackUp_Dialog()
            {
                try
                {
                    FilePick ofdLoadFile = new FilePick();
                    ofdLoadFile.Filter = "WPE x64（*.sb）|*.sb";

                    string sPickedPath = await UI.PickOpen(ofdLoadFile);
                    if (!string.IsNullOrEmpty(sPickedPath))
                    {
                        string FilePath = sPickedPath;
                        if (!string.IsNullOrEmpty(FilePath))
                        {
                            if (await ImportSystemBackUp(FilePath, true))
                            {
                                string Title = UI.T("BackUpSettingsForm.Import.Success", "导入系统备份成功");
                                UI.Notify(UiIcon.Success, Title, FilePath);
                                Operate.DoLog(nameof(ImportSystemBackUp_Dialog), Title + ": " + FilePath);
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(ImportSystemBackUp_Dialog), ex);
                }
            }

            private static async Task<bool> ImportSystemBackUp(string FilePath, bool LoadFromUser)
            {
                try
                {
                    if (File.Exists(FilePath))
                    {
                        XDocument xdoc = null;

                        bool bEncrypt = IsEncryptXMLFile(FilePath);
                        if (bEncrypt)
                        {
                            if (LoadFromUser)
                            {
                                xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("BackUpSettingsForm.Import", "导入系统备份"), FilePath);
                            }
                        }
                        else
                        {
                            xdoc = XDocument.Load(FilePath);
                        }

                        if (xdoc == null)
                        {
                            string sError = UI.T("Password.Incorrect", "密码错误");
                            if (LoadFromUser)
                            {
                                UI.Toast(UiIcon.Error, sError);
                            }
                            else
                            {
                                Operate.DoLog(nameof(ImportSystemBackUp), sError);
                            }

                            return false;
                        }

                        ImportSystemBackUp_FromXDocument(xdoc);
                        return true;
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(ImportSystemBackUp), ex);
                }

                return false;
            }

            private static void ImportSystemBackUp_FromXDocument(XDocument xdoc)
            {
                #region//有效性检测

                string RootName = xdoc.Root.Name.LocalName;
                if (!RootName.Equals("WPE64_BackUp"))
                {
                    UI.Toast(UiIcon.Error, UI.T("SystemBackUp.Error", "备份文件错误"));

                    return;
                }

                #endregion

                #region//系统设置

                try
                {
                    XElement xeSystemConfig = xdoc.Root.Element("SystemConfig");
                    if (xeSystemConfig != null)
                    {
                        SetSystemConfig_FromXML(xeSystemConfig);                        
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import SystemConfig", ex);
                }

                #endregion

                #region//代理模式配置

                try
                {
                    XElement xeProxyMode = xdoc.Root.Element("ProxyMode");
                    if (xeProxyMode != null)
                    {
                        SetProxyMode_FromXML(xeProxyMode);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import ProxyMode", ex);
                }

                #endregion

                #region//注入模式配置

                try
                {
                    XElement xeInjectMode = xdoc.Root.Element("InjectMode");
                    if (xeInjectMode != null)
                    {
                        SetInjectMode_FromXML(xeInjectMode);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import InjectMode", ex);
                }

                #endregion

                #region//代理账号

                try
                {
                    XElement xeProxyAccountList = xdoc.Root.Element("ProxyAccountList");
                    if (xeProxyAccountList != null)
                    {
                        XDocument ProxyAccountList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        ProxyAccountList.Add(xeProxyAccountList);

                        ProxyConfig.Account.ClearAccountInfo();
                        ProxyConfig.Account.LoadAccountList_FromXDocument(ProxyAccountList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import ProxyAccountList", ex);
                }

                #endregion

                #region//白名单

                try
                {
                    XElement xeWhiteList = xdoc.Root.Element("WhiteList");
                    if (xeWhiteList != null)
                    {
                        XDocument WhiteList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        WhiteList.Add(xeWhiteList);

                        ProxyConfig.Proxy.CleanUpWhiteList();
                        ProxyConfig.Proxy.LoadWhiteList_FromXDocument(WhiteList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import WhiteList", ex);
                }

                #endregion

                #region//黑名单

                try
                {
                    XElement xeBlackList = xdoc.Root.Element("BlackList");
                    if (xeBlackList != null)
                    {
                        XDocument BlackList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        BlackList.Add(xeBlackList);

                        ProxyConfig.Proxy.CleanUpBlackList();
                        ProxyConfig.Proxy.LoadBlackList_FromXDocument(BlackList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import BlackList", ex);
                }

                #endregion

                #region//代理映射

                try
                {
                    //本地代理映射
                    XElement xeMapLocal = xdoc.Root.Element("MapLocal");
                    if (xeMapLocal != null)
                    {
                        XDocument MapLocal = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        MapLocal.Add(xeMapLocal);

                        //⚠️ 先清空再装 —— 见下面「导入是替换不是追加」那段
                        ProxyConfig.Mapping.MapLocalClear();

                        ProxyConfig.Mapping.LoadMapLocal_FromXDocument(MapLocal);
                    }

                    //远程代理映射
                    XElement xeMapRemote = xdoc.Root.Element("MapRemote");
                    if (xeMapRemote != null)
                    {
                        XDocument MapRemote = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        MapRemote.Add(xeMapRemote);
                        ProxyConfig.Mapping.MapRemoteClear();

                        ProxyConfig.Mapping.LoadMapRemote_FromXDocument(MapRemote);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import ProxyAccountList", ex);
                }

                #endregion

                #region//滤镜列表

                try
                {
                    XElement xeFilterList = xdoc.Root.Element("FilterList");
                    if (xeFilterList != null)
                    {
                        XDocument xdFilterList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdFilterList.Add(xeFilterList);

                        /*
                            ⚠️ <b>导入是「整份替换」，不是追加。</b>

                            账号 / 白名单 / 黑名单一直是先 Clear 再 Load，而映射 / 滤镜 / 发送 /
                            机器人这四份原来<b>直接 Load</b>（那几个 Load*_FromXDocument 内部也不清表，
                            全是 foreach + Add）。同一份备份导两次，滤镜列表就有两份 ——
                            而界面上的提示语写的正是「导入会整份替换当前配置与各份列表」，
                            文案与行为相反。

                            滤镜 / 发送 / 机器人的<b>顺序就是数据</b>（DoWork 按列表下标走），
                            追加进去还会打乱执行顺序。
                        */
                        FilterConfig.List.FilterListClear();

                        FilterConfig.List.FilterListClear();
                        FilterConfig.List.LoadFilterList_FromXDocument(xdFilterList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import FilterList", ex);
                }

                #endregion

                #region//发送列表

                try
                {
                    XElement xeSendList = xdoc.Root.Element("SendList");
                    if (xeSendList != null)
                    {
                        XDocument xdSendList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdSendList.Add(xeSendList);
                        SendConfig.List.SendListClear();

                        SendConfig.List.SendListClear();
                        SendConfig.List.LoadSendList_FromXDocument(xdSendList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import SendList", ex);
                }

                #endregion

                #region//机器人列表

                try
                {
                    XElement xeRobotList = xdoc.Root.Element("RobotList");
                    if (xeRobotList != null)
                    {
                        XDocument xdRobotList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdRobotList.Add(xeRobotList);
                        RobotConfig.List.RobotListClear();

                        RobotConfig.List.RobotListClear();
                        RobotConfig.List.LoadRobotList_FromXDocument(xdRobotList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import RobotList", ex);
                }

                #endregion

                #region//仓库

                try
                {
                    XElement xeWareHouse = xdoc.Root.Element("WareHouseList");   //⚠️ 根名是 WareHouseList，不是 WareHouse —— 跑测抓到过一次
                    if (xeWareHouse != null)
                    {
                        XDocument xdWareHouse = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdWareHouse.Add(xeWareHouse);

                        WareHouseConfig.List.WareHouseListClear();
                        WareHouseConfig.List.LoadWareHouseList_FromXDocument(xdWareHouse);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import WareHouse", ex);
                }

                #endregion

                #region//自动入库

                try
                {
                    XElement xeAutoStores = xdoc.Root.Element("AutoStores");
                    if (xeAutoStores != null)
                    {
                        XDocument xdAutoStores = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdAutoStores.Add(xeAutoStores);

                        WareHouseConfig.List.AutoStoresClear();
                        WareHouseConfig.List.LoadAutoStores_FromXDocument(xdAutoStores);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import AutoStores", ex);
                }

                #endregion

                #region//WPC 节点

                try
                {
                    XElement xeServerList = xdoc.Root.Element("ServerList");
                    if (xeServerList != null)
                    {
                        XDocument xdServerList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdServerList.Add(xeServerList);

                        WPCConfig.ServerList.ServerListClear();
                        WPCConfig.ServerList.LoadServerList_FromXDocument(xdServerList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import ServerList", ex);
                }

                #endregion

                #region//WPC 公告

                try
                {
                    XElement xeNoticeList = xdoc.Root.Element("NoticeList");
                    if (xeNoticeList != null)
                    {
                        XDocument xdNoticeList = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };
                        xdNoticeList.Add(xeNoticeList);

                        WPCConfig.NoticeList.NoticeListClear();
                        WPCConfig.NoticeList.LoadNoticeList_FromXDocument(xdNoticeList);
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog("Import NoticeList", ex);
                }

                #endregion
            }

            #endregion
        }

        #endregion

        #region//进程配置

        public static class ProcessConfig
        {
            #region//获取进程列表

            public static List<ProcessInfo> GetProcessList()
            {
                List<ProcessInfo> piReturn = new List<ProcessInfo>();

                try
                {
                    Process[] procesArr = Process.GetProcesses();
                    int pCNT = procesArr.Length;

                    foreach (Process p in procesArr)
                    {
                        //图标不在这里生成：Operate 只出数据，图标由外壳按路径去取（getProcessIcons）
                        string ProcessPath = GetProcessPath(p);

                        string ModuleName = string.Empty;

                        try
                        {
                            ModuleName = p.MainModule?.ModuleName ?? string.Empty;
                        }
                        catch
                        { 
                            //
                        }                        

                        ProcessInfo processInfo = new ProcessInfo(null, p.ProcessName, p.Id, ModuleName, ProcessPath);
                        piReturn.Add(processInfo);
                    }

                    piReturn.Sort((x, y) => x.ProcessName.CompareTo(y.ProcessName));
                }
                catch (Exception ex)
                {
                    DoLog(nameof(GetProcessList), ex);
                }

                return piReturn;
            }

            #endregion

            #region//进程列表（出 DTO，给外壳的注入屏用）

            /// <summary>
            /// 进程列表的 DTO 版。
            ///
            /// 【为什么不复用 ProxyConfig.Proxy.GetProcessRows】那一个是<b>进程设置</b>那屏专用的：
            /// 它会把结果存进 lastProcessList（「双击添加到名称」要按 Pid 回查），
            /// 并且 IsCheck 取自 lstSelectProcessName —— 那是「强制转代理」的勾选状态，
            /// 与注入模式选目标毫无关系。借用它会让两屏互相污染。
            /// </summary>
            public static ProcessRow[] GetProcessRows()
            {
                List<ProcessInfo> list = GetProcessList() ?? new List<ProcessInfo>();

                var rows = new List<ProcessRow>(list.Count);

                for (int i = 0; i < list.Count; i++)
                {
                    ProcessInfo pi = list[i];
                    if (pi == null) { continue; }

                    /*
                        ⚠️ <b>不出自己那一行。</b>

                        注入自己 = 把 13 个 WinSock 钩子装进外壳进程本身：WebView2 与远程管理
                        都在这个进程里收发，钩子一装就是自己钩自己；而 IPC 那三条管道的另一端
                        也在同一个进程里，握手根本走不通。用户点了只会得到一个卡死的窗口。

                        与「进程设置」那一屏同一条口径（ProxyConfig.Proxy.GetProcessRows 早就
                        不出自己了，见 IsSelfProcess）—— 那边挡的是「勾了自己会成环」，
                        这边挡的是「注入自己会把自己钩死」，两处都由业务层兜住，不靠界面自觉。
                    */
                    if (ProxyConfig.Proxy.IsSelfProcess(pi.ProcessID, pi.ModuleName)) { continue; }

                    rows.Add(ProcessRow.From_(pi));
                }

                return rows.ToArray();
            }

            #endregion

            #region//获取进程的路径

            public static string GetProcessPath(Process process)
            {
                try
                {
                    return process.MainModule.FileName;
                }
                catch
                {
                    return string.Empty;
                }
            }

            #endregion

            #region//获取注入的进程的名称

            public static string GetInjectProcessName()
            {
                string sReturn = string.Empty;

                try
                {
                    Process pProcess = Process.GetCurrentProcess();
                    PacketConfig.Packet.InjectProcess = string.Format("{0} [{1}]", pProcess.ProcessName, pProcess.Id);
                    sReturn = PacketConfig.Packet.InjectProcess;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(GetInjectProcessName), ex);
                }

                return sReturn;
            }

            #endregion

            #region//获取注入的模块名称        

            public static string GetInjectModuleName()
            {
                string sReturn = string.Empty;

                try
                {
                    Process pProcess = Process.GetCurrentProcess();

                    if (pProcess.MainWindowHandle != IntPtr.Zero)
                    {
                        if (string.IsNullOrEmpty(pProcess.MainWindowTitle))
                        {
                            sReturn = string.Format(UI.T("ProcessInfo", "{0} 句柄: {1}"), pProcess.MainModule.ModuleName, pProcess.MainWindowHandle.ToString());
                        }
                        else
                        {
                            sReturn = string.Format(UI.T("ProcessInfo", "{0} 句柄: {1}"), pProcess.MainWindowTitle, pProcess.MainWindowHandle.ToString());
                        }
                    }
                    else
                    {
                        if (string.IsNullOrEmpty(pProcess.MainWindowTitle))
                        {
                            sReturn = pProcess.MainModule.ModuleName;
                        }
                        else
                        {
                            sReturn = pProcess.MainWindowTitle;
                        }
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(GetInjectModuleName), ex);
                }

                return sReturn;
            }

            #endregion

            #region//获取注入的进程的 Winsock 版本信息

            public static string GetInjectWinsockInfo()
            {
                string sReturn = "WinSock";

                try
                {
                    Operate.PacketConfig.Packet.Support_WS1 = false;
                    Operate.PacketConfig.Packet.Support_WS2 = false;

                    foreach (ProcessModule module in Process.GetCurrentProcess().Modules)
                    {
                        string sModuleName = module.ModuleName;

                        if (sModuleName.Equals(WSock32.ModuleName, StringComparison.CurrentCultureIgnoreCase))
                        {
                            Operate.PacketConfig.Packet.Support_WS1 = true;
                        }

                        if (sModuleName.Equals(WS2_32.ModuleName, StringComparison.CurrentCultureIgnoreCase))
                        {
                            Operate.PacketConfig.Packet.Support_WS2 = true;
                        }

                        if (sModuleName.Equals(Mswsock.ModuleName, StringComparison.CurrentCultureIgnoreCase))
                        {
                            Operate.PacketConfig.Packet.Support_MsWS = true;
                        }
                    }

                    if (Operate.PacketConfig.Packet.Support_WS1)
                    {
                        sReturn += " 1.1";
                    }

                    if (Operate.PacketConfig.Packet.Support_WS2)
                    {
                        sReturn += " 2.0";
                    }

                    if (Operate.PacketConfig.Packet.Support_MsWS)
                    {
                        sReturn += " Microsoft";
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(GetInjectWinsockInfo), ex);
                }

                return sReturn;
            }

            #endregion
        }

        #endregion

        #region//代理配置

        public static class ProxyConfig
        {
            #region//代理

            public static class Proxy
            {
                public static ProxyAppServer ProxyServer = null;
                public static SunnyNetlibray.SunnyNet syNet = new SunnyNetlibray.SunnyNet();
                public static SunnyNetlibray.CertManager syCert = new SunnyNetlibray.CertManager();
                public static SunnyNetCallback syCallBack = new SunnyNetCallback();
                public static bool IsLoadDriver = false;
                public static int DriverType = 1;
                public static IPConnectionFilter ipFilter = new IPConnectionFilter();
                public static List<int> lstSelectProcessID = new List<int>();
                public static BindingList<ProcessInfo> lstSelectProcessName = new BindingList<ProcessInfo>();
                public static long ProxyTotal_CNT, TCP_Req_CNT, UDP_Req_CNT, TCP_Resp_CNT, UDP_Resp_CNT, HTTP_Req_CNT, HTTP_Resp_CNT;
                public static int ProxySpeed_Uplink, ProxySpeed_Downlink;
                public static int FilterProxy_CNT = 0;
                public static IPAddress[] ProxyServerIP = null;
                public static IPAddress ProxyTCP_IP = null, ProxyUDP_IP = null;
                public static bool ProxyIP_Auto = true;
                public static bool Enable_SystemProxy = false;
                public static bool Enable_SOCKS5 = true, Enable_Auth = true;
                public static bool Enable_HTTP = true, MustTCP_AppointPort = false, MustTCP_Auth = false;
                public static bool MustTCP = true;
                public static string MustTCP_IP = "127.0.0.1";
                public static ushort MustTCP_Port = 1080;
                public static string MustTCP_UserName = string.Empty, MustTCP_PassWord = string.Empty;

                /*
                    「指定端口」的文本与它解析出来的集合。

                    做成属性，是为了让<b>每一条</b>写入路径（保存 / 读库 / 备份导入 / WinForms 那份控件的赋值）
                    都过同一个 setter：解析只在写入时做一次，连接线程上的 IsMustTCP_ByPort 只剩一次 HashSet 查找。
                    原先是每条连接 Split(',') 一遍，而且不 Trim —— "80, 443" 里的 " 443" 永远匹配不上。
                    解析规则见 ParseAppointPorts。
                */
                private static string mustTCP_AppointPortContent = string.Empty;
                private static HashSet<int> mustTCP_AppointPorts = new HashSet<int>();

                public static string MustTCP_AppointPortContent
                {
                    get { return mustTCP_AppointPortContent; }
                    set
                    {
                        mustTCP_AppointPortContent = value ?? string.Empty;
                        mustTCP_AppointPorts = ParseAppointPorts(mustTCP_AppointPortContent, out _);
                    }
                }

                /// <summary>
                /// 解析端口列表：逗号 / 分号 / 空白分隔（中文标点也认），只收 1~65535 的整数。
                /// 认不出来的片段进 Invalid —— 保存时要报给用户，读库时直接丢掉。
                /// </summary>
                public static HashSet<int> ParseAppointPorts(string Text, out List<string> Invalid)
                {
                    var set = new HashSet<int>();
                    Invalid = new List<string>();

                    if (string.IsNullOrWhiteSpace(Text))
                    {
                        return set;
                    }

                    foreach (string raw in Text.Split(new[] { ',', '，', ';', '；', ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        string s = raw.Trim();
                        if (s.Length == 0) { continue; }

                        if (int.TryParse(s, out int p) && p >= 1 && p <= 65535)
                        {
                            set.Add(p);
                        }
                        else
                        {
                            Invalid.Add(s);
                        }
                    }

                    return set;
                }

                /// <summary>把端口列表写回成规范文本（升序、逗号分隔，如 "80,443"）。保存时用它替换用户输入。</summary>
                public static string NormalizeAppointPorts(string Text, out List<string> Invalid)
                {
                    var list = new List<int>(ParseAppointPorts(Text, out Invalid));
                    list.Sort();
                    return string.Join(",", list);
                }

                public static bool Enable_ExternalProxy = false, Enable_ExternalProxy_AppointPort = false, Enable_ExternalProxy_Auth = false;
                public static string ExternalProxy_IP = "127.0.0.1";
                public static ushort ExternalProxy_Port = 8889;
                public static string ExternalProxy_AppointPort = "80,8080,443,8443", ExternalProxy_UserName, ExternalProxy_PassWord;

                #region//设置页入口（WPEHybrid 用：进程设置 / 外部代理）

                /*
                    这两段原本长在 Controls/ProcessSetting 与 Controls/EXTProxySetting 里（校验、装驱动、把进程塞给 SunnyNet），
                    外壳复用不到。搬进来之后 WinForms 那两个控件照旧，只是同一段逻辑有了第二份 —— 与其它设置页同一口径。
                */

                /// <summary>上一次 GetProcessRows 拿到的进程快照，「双击添加到名称」按 Pid 从这里找（ProcessInfo 带图标字段，不出给外壳）。</summary>
                private static List<ProcessInfo> lastProcessList = new List<ProcessInfo>();

                public static ProcessSettingRow GetProcessSetting()
                {
                    return new ProcessSettingRow
                    {
                        DriverType = DriverType,
                        IsLoadDriver = IsLoadDriver,
                        MustTCP = MustTCP,
                        IP = MustTCP_IP ?? string.Empty,
                        Port = MustTCP_Port,
                        AppointPort = MustTCP_AppointPort,
                        AppointPortContent = MustTCP_AppointPortContent ?? string.Empty,
                        Auth = MustTCP_Auth,
                        UserName = MustTCP_UserName ?? string.Empty,
                        PassWord = MustTCP_PassWord ?? string.Empty,
                        CheckedPids = lstSelectProcessID.ToArray(),

                        //链路体检用的只读环境状态，见 ProcessSettingRow 上那段说明
                        EnableHttp = Enable_HTTP,
                        HttpPort = HTTP_Port,
                        EnableSocks5 = Enable_SOCKS5,
                        Socks5Port = SOCKS5_Port,
                        EnableAuth = Enable_Auth,
                        Running = IsRunning,
                        IsAdmin = SystemConfig.IsAdministrator(),
                    };
                }

                /// <summary>当前进程表（按名字排序），IsCheck 按 lstSelectProcessID 勾好。图标不在这里，外壳按路径自己取。</summary>
                public static ProcessRow[] GetProcessRows()
                {
                    try
                    {
                        lastProcessList = ProcessConfig.GetProcessList() ?? new List<ProcessInfo>();
                        var rows = new List<ProcessRow>();
                        int self = SelfProcessId;

                        foreach (ProcessInfo pi in lastProcessList)
                        {
                            //自己不进表：勾了自己，驱动会把 WPE 往目标发的连接也抓回来，成环
                            if (pi.ProcessID == self) { continue; }

                            pi.IsCheck = lstSelectProcessID.Contains(pi.ProcessID);
                            rows.Add(ProcessRow.From_(pi));
                        }

                        return rows.OrderBy(r => r.ProcessName, StringComparer.OrdinalIgnoreCase).ThenBy(r => r.ProcessID).ToArray();
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetProcessRows), ex);
                        return new ProcessRow[0];
                    }
                }

                /// <summary>「按进程名称拦截」加一条（WinForms 是双击左表）。同名已在就不重复加。</summary>
                public static bool AddSelectProcessName_ByPid(int Pid)
                {
                    ProcessInfo pi = lastProcessList.FirstOrDefault(x => x.ProcessID == Pid);
                    if (pi == null || string.IsNullOrEmpty(pi.ModuleName)) { return false; }
                    if (IsSelfProcess(Pid, pi.ModuleName)) { return false; }

                    foreach (ProcessInfo x in lstSelectProcessName)
                    {
                        if (string.Equals(x.ModuleName, pi.ModuleName, StringComparison.OrdinalIgnoreCase)) { return true; }
                    }

                    lstSelectProcessName.Add(pi);
                    return true;
                }

                #region//按名称拦截的进程表：落库与读回

                /*
                    这份名单原先只活在内存里，WPE 一重启就没了 —— 而它恰恰是「按名称」的那一份，
                    存在的意义就是不随进程重启而失效。序列化成一行一条 "模块名|路径"（路径只给界面取图标用，可以为空）。
                    Pid 那份刻意不存：进程编号本来就是一次性的。
                */
                public static string SerializeSelectProcessNames()
                {
                    var sb = new StringBuilder();

                    foreach (ProcessInfo pi in lstSelectProcessName)
                    {
                        if (string.IsNullOrEmpty(pi.ModuleName)) { continue; }
                        if (sb.Length > 0) { sb.Append('\n'); }
                        sb.Append(pi.ModuleName.Replace('|', '_').Replace('\n', ' ')).Append('|').Append((pi.ProcessPath ?? string.Empty).Replace('\n', ' '));
                    }

                    return sb.ToString();
                }

                /// <summary>读回名单：先清再装，同名（不分大小写）只留一条，自身进程不收。</summary>
                public static void LoadSelectProcessNames(string Text)
                {
                    lstSelectProcessName.Clear();
                    if (string.IsNullOrWhiteSpace(Text)) { return; }

                    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                    foreach (string line in Text.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        string l = line.Trim('\r', ' ', '\t');
                        if (l.Length == 0) { continue; }

                        int bar = l.IndexOf('|');
                        string name = (bar < 0 ? l : l.Substring(0, bar)).Trim();
                        string path = bar < 0 ? string.Empty : l.Substring(bar + 1).Trim();

                        if (name.Length == 0 || !seen.Add(name) || IsSelfProcess(0, name)) { continue; }

                        lstSelectProcessName.Add(new ProcessInfo(null, Path.GetFileNameWithoutExtension(name), 0, name, path));
                    }
                }

                #endregion

                public static bool RemoveSelectProcessName(string ModuleName)
                {
                    for (int i = 0; i < lstSelectProcessName.Count; i++)
                    {
                        if (string.Equals(lstSelectProcessName[i].ModuleName, ModuleName, StringComparison.OrdinalIgnoreCase))
                        {
                            lstSelectProcessName.RemoveAt(i);
                            return true;
                        }
                    }
                    return false;
                }

                /// <summary>卸载驱动（带确认框：会立即重启电脑）。返回 true = 用户确认并已执行。</summary>
                public static async Task<bool> UninstallDriver_Dialog()
                {
                    if (!await UI.Confirm(UI.T("UninstallDriver", "卸载驱动"), UI.T("UninstallDriver.Alert", "卸载驱动会立即重启电脑，若非必要请勿卸载!")))
                    {
                        return false;
                    }

                    try { syNet.UnDriver(); return true; }
                    catch (Exception ex) { Operate.DoLog(nameof(UninstallDriver_Dialog), ex); return false; }
                }

                #region//自身进程

                private static int selfProcessId = -1;
                private static string selfModuleName = null;

                /// <summary>本进程的 Pid（外壳或主程序自己）。勾了自己，驱动会把 WPE 往目标发的连接也抓回来，成环。</summary>
                public static int SelfProcessId
                {
                    get
                    {
                        if (selfProcessId < 0)
                        {
                            using (Process p = Process.GetCurrentProcess())
                            {
                                selfProcessId = p.Id;
                                try { selfModuleName = p.MainModule?.ModuleName; } catch { selfModuleName = null; }
                            }
                        }
                        return selfProcessId;
                    }
                }

                public static bool IsSelfProcess(int Pid, string ModuleName)
                {
                    if (Pid == SelfProcessId) { return true; }
                    return !string.IsNullOrEmpty(ModuleName) && string.Equals(ModuleName, selfModuleName, StringComparison.OrdinalIgnoreCase);
                }

                #endregion

                /// <summary>
                /// 转代理地址指的是不是本机 —— 只有本机才谈得上「与自家 SOCKS5 / HTTP 端口撞上」那两条检查。
                /// 刻意不调 GetLocalIPAddress（几十毫秒），只认回环、localhost 与进代理模式时填好的 ProxyServerIP。
                /// </summary>
                public static bool IsLocalProxyAddress(string IP)
                {
                    if (string.IsNullOrWhiteSpace(IP)) { return false; }
                    IP = IP.Trim();

                    if (string.Equals(IP, "localhost", StringComparison.OrdinalIgnoreCase)) { return true; }

                    if (IPAddress.TryParse(IP, out IPAddress a))
                    {
                        if (IPAddress.IsLoopback(a) || a.Equals(IPAddress.Any)) { return true; }

                        IPAddress[] mine = ProxyServerIP;
                        if (mine != null)
                        {
                            foreach (IPAddress m in mine) { if (m.Equals(a)) { return true; } }
                        }
                    }

                    return false;
                }

                /// <summary>
                /// 保存前的校验 —— 纯函数、不碰驱动、不联网，跑测直接调它。返回空串 = 通过。
                /// 通过时 NormalizedPorts 是规范化后的端口列表（"80,443"），保存要用它替换用户输入。
                ///
                /// 这里拦的都是「保存之后被拦截的进程会直接断网、而界面上看不出为什么」的情形：
                ///   · HTTP 代理没开 —— 驱动把流量送进 SunnyNet，而 SunnyNet 是随 HTTP 代理起的；
                ///   · 转代理端口是 SunnyNet 自己的端口 —— 成环；
                ///   · 转到本机 SOCKS5，而它开着身份认证、这边却没勾「需要认证」—— 握手当场被拒。
                /// 最后那一条正是默认配置（EnableAuth 默认 1、MustTCP_Auth 默认 0）会撞上的。
                /// </summary>
                public static string ValidateProcessSetting(bool MustTCPNew, string IP, int Port, bool AppointPort, string AppointPortContent, bool Auth, string UserName, string PassWord, out string NormalizedPorts)
                {
                    NormalizedPorts = (AppointPortContent ?? string.Empty).Trim();
                    IP = (IP ?? string.Empty).Trim();
                    UserName = (UserName ?? string.Empty).Trim();
                    PassWord = (PassWord ?? string.Empty).Trim();

                    if (!Enable_HTTP)
                    {
                        return UI.T("ProcessSetting.NeedHttpProxy", "拦截进程的数据要经过 HTTP 代理，请先在「代理设置」里启用 HTTP 代理");
                    }

                    if (AppointPort)
                    {
                        NormalizedPorts = NormalizeAppointPorts(AppointPortContent, out List<string> bad);

                        if (bad.Count > 0)
                        {
                            return string.Format(UI.T("ProcessSetting.Port.Invalid", "指定端口里有认不出来的内容：{0}（只能是 1~65535 的数字，用逗号分隔）"), string.Join(" ", bad));
                        }

                        if (NormalizedPorts.Length == 0)
                        {
                            return UI.T("ProcessSetting.Port.Empty", "勾了「指定端口」就要填至少一个端口");
                        }
                    }

                    if (!MustTCPNew)
                    {
                        return string.Empty;
                    }

                    if (IP.Length == 0)
                    {
                        return UI.T("ProcessSetting.IP.Empty", "转代理地址为空");
                    }

                    //IsValidDomain 要求至少一个点，"localhost" 会被它拒掉 —— 它是转到本机最常见的写法，单独放行
                    AddressType at = GetAddressType_ByString(IP);
                    if (at != AddressType.IPv4 && at != AddressType.Domain && !string.Equals(IP, "localhost", StringComparison.OrdinalIgnoreCase))
                    {
                        return UI.T("ProcessSetting.IP.Error", "转代理地址错误（要 IPv4 地址或域名）");
                    }

                    if (Port < 1 || Port > 65535)
                    {
                        return UI.T("ProcessSetting.Port.Error", "转代理端口要在 1~65535 之间");
                    }

                    if (Auth && (UserName.Length == 0 || PassWord.Length == 0))
                    {
                        return UI.T("ProcessSetting.Auth.Empty", "勾了「需要认证」就要填账号和密码");
                    }

                    if (IsLocalProxyAddress(IP))
                    {
                        if (Port == HTTP_Port)
                        {
                            return string.Format(UI.T("ProcessSetting.Port.Loop", "转代理端口不能是 HTTP 代理自己的端口 {0}：那会把流量转回 SunnyNet 自己，成环"), HTTP_Port);
                        }

                        if (Port == SOCKS5_Port)
                        {
                            if (!Enable_SOCKS5)
                            {
                                return UI.T("ProcessSetting.Socks5.Off", "本机 SOCKS5 代理没有启用，转过去也没有人接");
                            }

                            if (Enable_Auth && !Auth)
                            {
                                return UI.T("ProcessSetting.Auth.Required", "本机 SOCKS5 代理开着身份认证，转代理必须勾选「需要认证」并填一个代理账号，否则被拦截的进程会直接断网");
                            }
                        }
                    }

                    return string.Empty;
                }

                /// <summary>
                /// 保存进程设置，逐步照 WinForms 的 ProcessSetting.bSave_Click，前面多了两道：
                /// 校验（ValidateProcessSetting）→ 真连一次转代理服务器 → 写字段 → 没装驱动就按选的类型装 →
                /// 把勾选的 Pid 与名称表交给 SunnyNet → 落库。返回空串 = 成功。
                ///
                /// 装驱动那一段（首次要复制 sys 文件、起服务，几秒钟）走 UI.Busy 丢到后台，UI 线程不卡；
                /// SunnyNet 的调用本来就是跨到 Go 侧的，UI.Toast 也自己 marshal，后台跑是安全的。
                /// </summary>
                public static async Task<string> SaveProcessSetting(int DriverTypeNew, bool MustTCPNew, string IP, int Port, bool AppointPort, string AppointPortContent, bool Auth, string UserName, string PassWord, IList<int> CheckedPids)
                {
                    try
                    {
                        string err = ValidateProcessSetting(MustTCPNew, IP, Port, AppointPort, AppointPortContent, Auth, UserName, PassWord, out string ports);
                        if (!string.IsNullOrEmpty(err))
                        {
                            return err;
                        }

                        IP = (IP ?? string.Empty).Trim();
                        UserName = (UserName ?? string.Empty).Trim();
                        PassWord = (PassWord ?? string.Empty).Trim();

                        /*
                            真连一次：地址、端口、凭据三样对不对，只有握手才知道；原先只有用户主动点「检测代理」才会发现。
                            本机 SOCKS5 还没起的时候跳过 —— 那时连不上不说明配置错，而认证那一条上面的静态检查已经拦了。
                        */
                        if (MustTCPNew && (IsRunning || !IsLocalProxyAddress(IP) || Port != SOCKS5_Port))
                        {
                            string t = await TestSocksProxy(Auth, IP, Port, UserName, PassWord);
                            if (!string.IsNullOrEmpty(t))
                            {
                                return string.Format(UI.T("ProcessSetting.Detect.Before", "转代理服务器连不上，没有保存：{0}"), t);
                            }
                        }

                        MustTCP = MustTCPNew;
                        MustTCP_IP = IP;
                        MustTCP_Port = (ushort)Math.Max(1, Math.Min(65535, Port));
                        MustTCP_AppointPort = AppointPort;
                        MustTCP_AppointPortContent = ports;
                        MustTCP_Auth = Auth;
                        MustTCP_UserName = UserName;
                        MustTCP_PassWord = PassWord;

                        lstSelectProcessID.Clear();
                        foreach (int pid in CheckedPids ?? new List<int>())
                        {
                            //自己不收：驱动会把 WPE 往目标发的连接也抓回来，成环（界面上已经不出这一行，这里是业务层的兜底）
                            if (pid == SelfProcessId) { continue; }
                            if (!lstSelectProcessID.Contains(pid)) { lstSelectProcessID.Add(pid); }
                        }

                        string applyErr = await UI.Busy(UI.T("Loading", "正在加载..."), () => ApplyProcessSetting(DriverTypeNew));
                        if (!string.IsNullOrEmpty(applyErr))
                        {
                            return applyErr;
                        }

                        //换了转代理设置：已有的 UDP 关联收掉，下一个数据报按新设置重连
                        CloseAllUDPProxy();

                        UI.Toast(UiIcon.Success, UI.T("ProcessSetting.Save.Success", "进程设置保存成功"));
                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveProcessSetting), ex);
                        return ex.Message;
                    }
                }

                /// <summary>装驱动 + 把进程交给驱动 + 落库。跑在 UI.Busy 的后台线程上，不碰界面。</summary>
                private static string ApplyProcessSetting(int DriverTypeNew)
                {
                    if (!IsLoadDriver)
                    {
                        DriverType = DriverTypeNew >= 0 && DriverTypeNew <= 2 ? DriverTypeNew : 1;
                        IsLoadDriver = syNet.LoadDriver(DriverType);
                    }

                    if (!IsLoadDriver)
                    {
                        return UI.T("ProcessSetting.LoadDriver.Error", "加载驱动失败, 请检查是否管理员权限运行");
                    }

                    ApplyProcessesToDriver();
                    SystemConfig.SaveProxyMode_ToDB();
                    return string.Empty;
                }

                /// <summary>
                /// 把勾选的 Pid 与名称表交给驱动（先清再加）。
                /// 保存时调；StartProxy 成功后也调一次 —— StopProxy 会把它们摘掉（见 ReleaseDriverProcesses），
                /// 再启动时要装回去，否则「停了再开」之后进程不再被拦截。
                /// </summary>
                public static void ApplyProcessesToDriver()
                {
                    if (!IsLoadDriver)
                    {
                        return;
                    }

                    try
                    {
                        syNet.RemoveAllProcesses();

                        foreach (int pid in lstSelectProcessID)
                        {
                            syNet.AddProcessPid(pid);
                        }

                        foreach (ProcessInfo pi in lstSelectProcessName)
                        {
                            if (!string.IsNullOrEmpty(pi.ModuleName)) { syNet.AddProcessName(pi.ModuleName); }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ApplyProcessesToDriver), ex);
                    }
                }

                /// <summary>
                /// 停止代理 / 退出时把进程从驱动上摘掉。驱动本身留着（卸载会重启电脑），
                /// 只是不再把这些进程的连接转到一个已经关掉的端口上 —— 否则 WPE 停了，目标进程也跟着断网。
                /// 名单留在内存里，再启动时 ApplyProcessesToDriver 装回去。
                /// </summary>
                public static void ReleaseDriverProcesses()
                {
                    if (!IsLoadDriver)
                    {
                        return;
                    }

                    try
                    {
                        syNet.RemoveAllProcesses();
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ReleaseDriverProcesses), ex);
                    }
                }

                public static ExtProxySettingRow GetExtProxySetting()
                {
                    return new ExtProxySettingRow
                    {
                        Enable = Enable_ExternalProxy,
                        IP = ExternalProxy_IP ?? string.Empty,
                        Port = ExternalProxy_Port,
                        AppointPort = Enable_ExternalProxy_AppointPort,
                        AppointPortContent = ExternalProxy_AppointPort ?? string.Empty,
                        Auth = Enable_ExternalProxy_Auth,
                        UserName = ExternalProxy_UserName ?? string.Empty,
                        PassWord = ExternalProxy_PassWord ?? string.Empty,
                    };
                }

                /// <summary>校验照 WinForms 的 EXTProxySetting.CheckExternalProxySet，只在启用时查。返回空串 = 成功。</summary>
                public static string ValidateExtProxy(bool Enable, string IP, bool AppointPort, string AppointPortContent, bool Auth, string UserName, string PassWord)
                {
                    if (!Enable) { return string.Empty; }

                    IP = (IP ?? string.Empty).Trim();
                    if (string.IsNullOrEmpty(IP)) { return UI.T("EXTProxySettingsForm.ProxyIP.Empty", "外部代理地址为空"); }

                    AddressType at = GetAddressType_ByString(IP);
                    if (at != AddressType.IPv4 && at != AddressType.Domain) { return UI.T("EXTProxySettingsForm.ProxyIP.Error", "外部代理地址错误"); }

                    if (AppointPort && string.IsNullOrEmpty((AppointPortContent ?? string.Empty).Trim())) { return UI.T("EXTProxySettingsForm.SpecifyPort.Empty", "指定端口为空"); }

                    if (Auth)
                    {
                        if (string.IsNullOrEmpty((UserName ?? string.Empty).Trim())) { return UI.T("ExternalProxySettingsForm.UserName.Empty", "认证账号为空"); }
                        if (string.IsNullOrEmpty((PassWord ?? string.Empty).Trim())) { return UI.T("ExternalProxySettingsForm.PassWord.Empty", "认证密码为空"); }
                    }

                    return string.Empty;
                }

                public static string SaveExtProxySetting(bool Enable, string IP, int Port, bool AppointPort, string AppointPortContent, bool Auth, string UserName, string PassWord)
                {
                    try
                    {
                        string err = ValidateExtProxy(Enable, IP, AppointPort, AppointPortContent, Auth, UserName, PassWord);
                        if (!string.IsNullOrEmpty(err)) { return err; }

                        Enable_ExternalProxy = Enable;
                        ExternalProxy_IP = (IP ?? string.Empty).Trim();
                        ExternalProxy_Port = (ushort)Math.Max(1, Math.Min(65535, Port));
                        Enable_ExternalProxy_AppointPort = AppointPort;
                        ExternalProxy_AppointPort = (AppointPortContent ?? string.Empty).Trim();
                        Enable_ExternalProxy_Auth = Auth;
                        ExternalProxy_UserName = (UserName ?? string.Empty).Trim();
                        ExternalProxy_PassWord = (PassWord ?? string.Empty).Trim();

                        SystemConfig.SaveProxyMode_ToDB();
                        UI.Toast(UiIcon.Success, UI.T("ExternalProxySettingsForm.Success", "外部代理设置保存成功"));
                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveExtProxySetting), ex);
                        return ex.Message;
                    }
                }

                /// <summary>连一下 SOCKS 代理看通不通（进程设置与外部代理的「检测代理」共用）。返回空串 = 连通，否则是错误文案。</summary>
                public static async Task<string> TestSocksProxy(bool Auth, string IP, int Port, string UserName, string PassWord)
                {
                    try
                    {
                        using (var socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp))
                        {
                            var r = await EstablishSocksProxyServer(socket, Auth, (IP ?? string.Empty).Trim(), (ushort)Math.Max(1, Math.Min(65535, Port)),
                                (UserName ?? string.Empty).Trim(), (PassWord ?? string.Empty).Trim(), null);

                            if (r.Success) { return string.Empty; }
                            return string.IsNullOrEmpty(r.Error) ? UI.T("ProcessSetting.Detect.Fail", "代理服务器连接失败") : r.Error;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(TestSocksProxy), ex);
                        return ex.Message;
                    }
                }

