                #region//解析 Http 头数据

                public static Dictionary<string, string> ParseHttpHeaders(string request)
                {
                    Dictionary<string, string> headers = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

                    try
                    {
                        using (StringReader reader = new StringReader(request))
                        {
                            string line;
                            while ((line = reader.ReadLine()) != null && !string.IsNullOrWhiteSpace(line))
                            {
                                if (line.Contains(":"))
                                {
                                    var parts = line.Split(new[] { ':' }, 2);
                                    if (parts.Length == 2)
                                    {
                                        headers[parts[0].Trim()] = parts[1].Trim();
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(ParseHttpHeaders), ex);
                    }

                    return headers;
                }

                #endregion                

                #region//发送404响应

                public static byte[] Get404Response()
                {
                    string response =
                        "HTTP/1.1 404 Not Found\r\n" +
                        "Content-Type: text/html\r\n" +
                        "Content-Length: 0\r\n" +
                        "Connection: close\r\n\r\n";

                    return Encoding.UTF8.GetBytes(response);
                }

                #endregion

                #region//设置 UDP 使用代理

                /*
                    UDP 那一路的中继客户端（ClassObject/MustTcpUdpRelay.cs）：目标进程的一个 UDP 套接字对应一条 SOCKS5 UDP 关联，
                    应答由关联自己交还给那个套接字。旧写法是每个数据报新开一条关联、发完就把 TCP 与 UdpClient 一起关掉，
                    应答永远回不来 —— 详见那个文件头上的说明。

                    懒建：第一个被截下来的 UDP 数据报到达时才建。代理地址与凭据每次建关联时现取，
                    所以改了「强制转代理」的设置不必重建中继器；SaveProcessSetting 会 CloseAllUDPProxy 让已有关联按新设置重连。
                */
                private static MustTcpUdpRelay udpRelay = null;
                private static readonly object udpRelayLock = new object();

                public static MustTcpUdpRelay UdpRelay
                {
                    get
                    {
                        MustTcpUdpRelay r = udpRelay;
                        if (r != null) { return r; }

                        lock (udpRelayLock)
                        {
                            if (udpRelay == null)
                            {
                                udpRelay = new MustTcpUdpRelay(
                                    () => new MustTcpUdpRelay.Target
                                    {
                                        Auth = MustTCP_Auth,
                                        IP = MustTCP_IP,
                                        Port = MustTCP_Port,
                                        UserName = MustTCP_UserName,
                                        PassWord = MustTCP_PassWord,
                                    },
                                    (theology, data) => SunnyNetlibray.Tools.UDPTools.SendMessage(SunnyNetlibray.Tools.UDPTools.SendToClient, theology, data),
                                    (where, text) => SystemConfig.LogThrottled(where, text))
                                {
                                    IdleTimeout = UDPTimeout,
                                };
                            }

                            return udpRelay;
                        }
                    }
                }

                /// <summary>被驱动截下来的一个 UDP 数据报：交给中继送出去。调用方已经把事件的 Body 置空，SunnyNet 不会再直发。</summary>
                public static void SetUDPProxy(UDPEvent Conn, byte[] bSendData)
                {
                    try
                    {
                        IPEndPoint targetEndPoint = ParseIPEndPoint(Conn.RemoteAddr());
                        if (targetEndPoint == null || bSendData == null || bSendData.Length == 0)
                        {
                            return;
                        }

                        _ = UdpRelay.SendAsync(Conn.TheologyID(), targetEndPoint, bSendData);
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(SetUDPProxy), ex);
                    }
                }

                /// <summary>目标进程关了这个 UDP 套接字（UDP_Closed 事件），把它那条关联收掉。</summary>
                public static void CloseUDPProxy(long TheologyID)
                {
                    udpRelay?.Close(TheologyID);
                }

                /// <summary>停止代理 / 换了转代理设置：全部收掉，下一个数据报会按当前设置重建。</summary>
                public static void CloseAllUDPProxy()
                {
                    udpRelay?.CloseAll();
                }

                #endregion

                #region//解析 UDP 中继的 IP 地址

                public static IPEndPoint ParseIPEndPoint(string RemoteAddr)
                {
                    try
                    {
                        if (string.IsNullOrWhiteSpace(RemoteAddr))
                        {
                            return null;
                        }

                        if (RemoteAddr.StartsWith("[") && RemoteAddr.Contains("]:"))
                        {
                            int bracketEnd = RemoteAddr.IndexOf(']');
                            if (bracketEnd > 1)
                            {
                                string ipString = RemoteAddr.Substring(1, bracketEnd - 1);
                                string portString = RemoteAddr.Substring(bracketEnd + 2);

                                if (IPAddress.TryParse(ipString, out IPAddress ipAddress) && int.TryParse(portString, out int port) && port >= 0 && port <= 65535)
                                {
                                    return new IPEndPoint(ipAddress, port);
                                }
                            }
                        }
                        else
                        {
                            int lastColon = RemoteAddr.LastIndexOf(':');
                            if (lastColon > 0)
                            {
                                string ipString = RemoteAddr.Substring(0, lastColon);
                                string portString = RemoteAddr.Substring(lastColon + 1);

                                if (IPAddress.TryParse(ipString, out IPAddress ipAddress) &&
                                    int.TryParse(portString, out int port) && port >= 0 && port <= 65535)
                                {
                                    return new IPEndPoint(ipAddress, port);
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ParseIPEndPoint), ex);
                    }

                    return null;
                }

                #endregion

                #region//建立与代理服务器的链接

                public static async Task<(bool Success, string Error, byte[] Response)> EstablishSocksProxyServer(
                    Socket proxySocket,
                    bool ProxyServerAuth,
                    string ProxyServerIP,
                    ushort ProxyServerPort,
                    string Auth_Username,
                    string Auth_Password,
                    byte[] bCommand)
                {
                    string sError = string.Empty;

                    try
                    {
                        IPEndPoint proxyEndPoint = await ProxyConfig.Proxy.GetIPEndPoint_ByAddressString(ProxyServerIP, ProxyServerPort);
                        if (proxyEndPoint == null)
                        {
                            sError = UI.T("EXTProxySettingsForm.Setting.Error", "代理服务器设置错误");
                            return (false, sError, null);
                        }

                        if (proxySocket == null)
                        {
                            proxySocket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
                        }

                        // 设置连接超时
                        var connectTask = proxySocket.ConnectAsync(proxyEndPoint);
                        var timeoutTask = Task.Delay(TimeSpan.FromSeconds(5));

                        if (await Task.WhenAny(connectTask, timeoutTask) == timeoutTask)
                        {
                            sError = UI.T("EXTProxySettingsForm.Connect.TimeOut", "代理服务器连接超时");
                            return (false, sError, null);
                        }

                        //Socks5 握手
                        byte[] handshakeRequest = new byte[] { 0x05, 0x02, 0x00, 0x02 };
                        await proxySocket.SendAsync(new ArraySegment<byte>(handshakeRequest), SocketFlags.None);

                        byte[] handshakeResponse = new byte[2];
                        var receiveTask = proxySocket.ReceiveAsync(new ArraySegment<byte>(handshakeResponse), SocketFlags.None);
                        var receiveTimeoutTask = Task.Delay(TimeSpan.FromSeconds(5));

                        if (await Task.WhenAny(receiveTask, receiveTimeoutTask) == receiveTimeoutTask)
                        {
                            sError = UI.T("EXTProxySettingsForm.UnSupport", "代理服务器不支持的 Socks 协议");
                            return (false, sError, null);
                        }

                        int received = await receiveTask;
                        if (received < 2 || handshakeResponse[0] != 0x05)
                        {
                            sError = UI.T("EXTProxySettingsForm.UnSupport", "代理服务器不支持的 Socks 协议");
                            return (false, sError, null);
                        }

                        //身份认证
                        switch (handshakeResponse[1])
                        {
                            case 0x00:
                                //无需身份认证
                                break;

                            case 0x02:
                                //需要账号密码认证
                                if (!ProxyServerAuth)
                                {
                                    sError = UI.T("EXTProxySettingsForm.NeedAuth", "代理服务器要求认证");
                                    return (false, sError, null);
                                }

                                byte[] AuthRequest = Operate.ProxyConfig.Proxy.CreateSOCKS5AuthPacket(Auth_Username, Auth_Password);
                                if (AuthRequest == null)
                                {
                                    sError = UI.T("EXTProxySettingsForm.AuthFail", "代理服务器认证失败");
                                    return (false, sError, null);
                                }
                                await proxySocket.SendAsync(new ArraySegment<byte>(AuthRequest), SocketFlags.None);

                                byte[] AuthResponse = new byte[2];
                                int AuthResponseReceived = await proxySocket.ReceiveAsync(new ArraySegment<byte>(AuthResponse), SocketFlags.None);

                                if (AuthResponseReceived < 2 || AuthResponse[1] != 0x00)
                                {
                                    sError = UI.T("EXTProxySettingsForm.AuthFail", "代理服务器认证失败");
                                    return (false, sError, null);
                                }

                                break;

                            case 0xFF:
                            default:
                                sError = UI.T("EXTProxySettingsForm.AuthUnSupport", "不支持的认证方式");
                                return (false, sError, null);
                        }

                        //命令过程
                        if (bCommand == null || bCommand.Length == 0)
                        {
                            return (true, string.Empty, null);
                        }

                        await proxySocket.SendAsync(new ArraySegment<byte>(bCommand), SocketFlags.None);

                        byte[] commandResponse = new byte[256];
                        int commandResponseReceived = await proxySocket.ReceiveAsync(new ArraySegment<byte>(commandResponse), SocketFlags.None);

                        if (commandResponseReceived < 10 || commandResponse[1] != 0x00)
                        {
                            sError = UI.T("EXTProxySettingsForm.Connect.Fail", "连接目标服务器失败");
                            return (false, sError, null);
                        }

                        return (true, string.Empty, commandResponse);
                    }
                    catch
                    {
                        sError = UI.T("EXTProxySettingsForm.Connect.Refuses", "代理服务器拒绝连接");
                        return (false, sError, null);
                    }
                }

                #endregion

                #region//解析代理服务器的响应

                public static IPEndPoint ParseEstablishResponse(byte[] response)
                {
                    try
                    {
                        byte addressType = response[3];
                        IPAddress bindAddress;
                        ushort bindPort;

                        if (addressType == 0x01) // IPv4
                        {
                            bindAddress = new IPAddress(new ArraySegment<byte>(response, 4, 4).ToArray());
                            bindPort = (ushort)((response[8] << 8) | response[9]);
                        }
                        else if (addressType == 0x03) // Domain name
                        {
                            byte domainLength = response[4];
                            string domain = Encoding.ASCII.GetString(response, 5, domainLength);

                            bindAddress = IPAddress.Parse("127.0.0.1");
                            bindPort = (ushort)((response[5 + domainLength] << 8) | response[6 + domainLength]);
                        }
                        else if (addressType == 0x04) // IPv6
                        {
                            bindAddress = new IPAddress(new ArraySegment<byte>(response, 4, 16).ToArray());
                            bindPort = (ushort)((response[20] << 8) | response[21]);
                        }
                        else
                        {
                            return null;
                        }

                        return new IPEndPoint(bindAddress, bindPort);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ParseEstablishResponse), ex);
                        return null;
                    }
                }

                #endregion

                #region//创建 UDP 中继请求

                public static byte[] CreatSocks5UdpRequest(byte[] originalData, IPEndPoint targetEndPoint)
                {
                    try
                    {
                        using (MemoryStream ms = new MemoryStream())
                        {
                            // SOCKS5 UDP 请求头
                            ms.Write(new byte[] { 0x00, 0x00, 0x00 }, 0, 3); // RSV, FRAG

                            // 地址类型
                            if (targetEndPoint.AddressFamily == AddressFamily.InterNetwork)
                            {
                                ms.WriteByte(0x01); // IPv4
                                byte[] ipBytes = targetEndPoint.Address.GetAddressBytes();
                                ms.Write(ipBytes, 0, ipBytes.Length);
                            }
                            else if (targetEndPoint.AddressFamily == AddressFamily.InterNetworkV6)
                            {
                                ms.WriteByte(0x04); // IPv6
                                byte[] ipBytes = targetEndPoint.Address.GetAddressBytes();
                                ms.Write(ipBytes, 0, ipBytes.Length);
                            }
                            else
                            {
                                return null;
                            }

                            // 目标端口 (network byte order)
                            byte[] portBytes = BitConverter.GetBytes((ushort)targetEndPoint.Port);
                            if (BitConverter.IsLittleEndian)
                            {
                                Array.Reverse(portBytes);
                            }
                            ms.Write(portBytes, 0, 2);
                            ms.Write(originalData, 0, originalData.Length);

                            return ms.ToArray();
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CreatSocks5UdpRequest), ex);
                        return null;
                    }
                }

                #endregion

                #region//解析 UDP 中继响应

                public static (byte[] data, IPEndPoint endPoint) ParseSocks5UdpResponse(byte[] response, int length)
                {
                    if (length < 10)
                    {
                        return (null, null);
                    }

                    try
                    {
                        int offset = 3;
                        byte addressType = response[offset++];

                        IPAddress targetIp;
                        ushort targetPort;

                        if (addressType == 0x01) // IPv4
                        {
                            if (offset + 6 > length) return (null, null);
                            targetIp = new IPAddress(new ArraySegment<byte>(response, offset, 4).ToArray());
                            offset += 4;
                        }
                        else if (addressType == 0x04) // IPv6
                        {
                            if (offset + 18 > length) return (null, null);
                            targetIp = new IPAddress(new ArraySegment<byte>(response, offset, 16).ToArray());
                            offset += 16;
                        }
                        else
                        {
                            return (null, null);
                        }

                        // 读取端口
                        targetPort = (ushort)((response[offset] << 8) | response[offset + 1]);
                        offset += 2;

                        // 数据部分
                        byte[] data = new byte[length - offset];
                        Array.Copy(response, offset, data, 0, data.Length);

                        IPEndPoint endPoint = new IPEndPoint(targetIp, targetPort);

                        return (data, endPoint);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ParseSocks5UdpResponse), ex);
                        return (null, null);
                    }
                }

                #endregion

                #region//获取 SOCKS5 认证格式的封包

                public static byte[] CreateSOCKS5AuthPacket(string username, string password)
                {
                    // 验证输入参数
                    if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password) || username.Length > 255 || password.Length > 255)
                    {
                        return null;
                    }

                    // 计算所需缓冲区大小
                    // 1 (VER) + 1 (ULEN) + username + 1 (PLEN) + password
                    int packetSize = 1 + 1 + username.Length + 1 + password.Length;

                    // 创建字节数组
                    byte[] packet = new byte[packetSize];
                    int offset = 0;

                    // 版本号 (0x01)
                    packet[offset++] = 0x01;

                    // 用户名长度 (1字节)
                    packet[offset++] = (byte)username.Length;

                    // 用户名 (UTF8编码)
                    byte[] usernameBytes = Encoding.UTF8.GetBytes(username);
                    Buffer.BlockCopy(usernameBytes, 0, packet, offset, usernameBytes.Length);
                    offset += usernameBytes.Length;

                    // 密码长度 (1字节)
                    packet[offset++] = (byte)password.Length;

                    // 密码 (UTF8编码)
                    byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
                    Buffer.BlockCopy(passwordBytes, 0, packet, offset, passwordBytes.Length);

                    return packet;
                }

                #endregion                

                #region// 获取 Content-Type 类型

                public static string GetContentType(string fileExtension)
                {
                    try
                    {
                        switch (fileExtension.ToLower())
                        {
                            case ".html":
                            case ".htm":
                                return "text/html";

                            case ".js":
                                return "application/javascript";

                            case ".css":
                                return "text/css";

                            case ".png":
                                return "image/png";

                            case ".jpg":
                            case ".jpeg":
                                return "image/jpeg";

                            case ".gif":
                                return "image/gif";

                            case ".svg":
                                return "image/svg+xml";

                            case ".json":
                                return "application/json";

                            default:
                                return "application/octet-stream";
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(GetContentType), ex);
                    }

                    return "application/octet-stream";
                }

                #endregion                

                #region//获取IP地址信息                

                public static async Task<IPEndPoint> GetIPEndPoint_ByAddressString(string AddressString, ushort Port)
                {
                    try
                    {
                        IPAddress ipAddress = await ProxyConfig.Proxy.ResolveAddress(AddressString);
                        return new IPEndPoint(ipAddress, Port);
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(GetIPEndPoint_ByAddressString), ex);
                    }

                    return null;
                }

                public static async Task<(IPEndPoint EndPoint, string AddressString)> GetIPEndPoint_ByAddressType(Operate.ProxyConfig.Proxy.AddressType addressType, byte[] bData)
                {
                    string addressString = string.Empty;
                    IPEndPoint endPoint = null;

                    try
                    {
                        IPAddress ip = IPAddress.Any;
                        ushort port = 0;
                        int portPosition = 0;

                        switch (addressType)
                        {
                            case Operate.ProxyConfig.Proxy.AddressType.IPv4:
                                ip = new IPAddress(bData.AsSpan(0, 4).ToArray());
                                portPosition = 4;
                                addressString = ip.ToString();
                                break;

                            case Operate.ProxyConfig.Proxy.AddressType.IPv6:
                                ip = new IPAddress(bData.AsSpan(0, 16).ToArray());
                                portPosition = 16;
                                addressString = ip.ToString();
                                break;

                            case Operate.ProxyConfig.Proxy.AddressType.Domain:
                                byte length = bData[0];
                                var domainBytes = bData.AsSpan(1, length).ToArray();
                                addressString = Operate.SystemConfig.BytesToString(
                                    Operate.PacketConfig.Packet.EncodingFormat.UTF8,
                                    domainBytes);
                                ip = await ProxyConfig.Proxy.ResolveAddress(addressString);
                                portPosition = 1 + length;
                                break;
                        }

                        if (ip != null)
                        {
                            port = Operate.SystemConfig.ByteArrayToInt16BigEndian(bData.AsSpan(portPosition, 2).ToArray());
                            endPoint = new IPEndPoint(ip, port);
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(GetIPEndPoint_ByAddressType), ex);
                    }

                    return (endPoint, addressString);
                }

                private static async Task<IPAddress> ResolveAddress(string addressString)
                {
                    try
                    {
                        var addressType = Operate.ProxyConfig.Proxy.GetAddressType_ByString(addressString);

                        switch (addressType)
                        {
                            case Operate.ProxyConfig.Proxy.AddressType.IPv4:
                            case Operate.ProxyConfig.Proxy.AddressType.IPv6:
                                return IPAddress.Parse(addressString);

                            case Operate.ProxyConfig.Proxy.AddressType.Domain:

                                if (Operate.ProxyConfig.Proxy.DnsCache.TryGetValue(addressString, out var cachedIp))
                                {
                                    return cachedIp;
                                }

                                try
                                {
                                    var entry = await Dns.GetHostEntryAsync(addressString).ConfigureAwait(false);
                                    var ipv4 = entry.AddressList.FirstOrDefault(ip => ip.AddressFamily == AddressFamily.InterNetwork);
                                    var result = ipv4 ?? entry.AddressList.FirstOrDefault(ip => ip.AddressFamily == AddressFamily.InterNetworkV6)
                                                 ?? entry.AddressList.First();

                                    Operate.ProxyConfig.Proxy.DnsCache.AddOrUpdate(
                                        key: addressString,
                                        addValue: result,
                                        updateValueFactory: (key, oldValue) => result);

                                    return result;
                                }
                                catch
                                {
                                    return null;
                                }
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(ResolveAddress), ex);
                    }

                    return null;
                }

                #endregion

                #region//获取 UDP 数据包

                public static Span<byte> GetUDPData_ByAddressType(Operate.ProxyConfig.Proxy.AddressType addressType, Span<byte> bData)
                {
                    try
                    {
                        switch (addressType)
                        {
                            case Operate.ProxyConfig.Proxy.AddressType.IPv4:
                                return bData.Length >= 10 ? bData.Slice(10) : Span<byte>.Empty;

                            case Operate.ProxyConfig.Proxy.AddressType.Domain:

                                if (bData.Length < 5)
                                {
                                    return Span<byte>.Empty;
                                }

                                byte domainLength = bData[4];
                                int domainStart = 5 + domainLength + 2;
                                return bData.Length >= domainStart ? bData.Slice(domainStart) : Span<byte>.Empty;

                            case Operate.ProxyConfig.Proxy.AddressType.IPv6:
                                return bData.Length >= 22 ? bData.Slice(22) : Span<byte>.Empty;

                            default:
                                return Span<byte>.Empty;
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(GetUDPData_ByAddressType), ex);
                        return Span<byte>.Empty;
                    }
                }

                #endregion                

                #region//获取端口对应的域名类型

                public static Operate.ProxyConfig.Proxy.DomainType GetDomainType_ByPort(int Port)
                {
                    try
                    {
                        if (Operate.ProxyConfig.Proxy.Enable_ExternalProxy)
                        {
                            if (Operate.ProxyConfig.Proxy.Enable_ExternalProxy_AppointPort && !string.IsNullOrEmpty(Operate.ProxyConfig.Proxy.ExternalProxy_AppointPort))
                            {
                                HashSet<string> ExternalProxyPorts = new HashSet<string>(Operate.ProxyConfig.Proxy.ExternalProxy_AppointPort.Split(','));

                                if (ExternalProxyPorts.Contains(Port.ToString()))
                                {
                                    return Operate.ProxyConfig.Proxy.DomainType.External;
                                }
                            }
                            else
                            {
                                return Operate.ProxyConfig.Proxy.DomainType.External;
                            }
                        }

                        if (Port == 80 || Port == 8080)
                        {
                            return Operate.ProxyConfig.Proxy.DomainType.HTTP;
                        }
                        else if (Port == 443 || Port == 8443)
                        {
                            return Operate.ProxyConfig.Proxy.DomainType.HTTPS;
                        }
                    }
                    catch (Exception ex)
                    {
                        DoLog(nameof(GetDomainType_ByPort), ex);
                    }

                    return Operate.ProxyConfig.Proxy.DomainType.Socket;
                }

