                #region//导出证书到文件（对话框）

                public static async Task SaveCertToFile_Dialog(int CerType, string FileName)
                {
                    try
                    {
                        FilePick sfdSaveFile = new FilePick();
                        sfdSaveFile.FileName = FileName;

                        switch (CerType)
                        {
                            case 0:
                            case 1:
                                sfdSaveFile.Filter = UI.T("CerFile", "CER 文件") + "（*.cer）|*.cer";
                                break;

                            case 2:
                            case 3:
                                sfdSaveFile.Filter = UI.T("CrtFile", "CRT 文件") + "（*.crt）|*.crt";
                                break;

                            case 4:
                                sfdSaveFile.Filter = UI.T("PemFile", "PEM 文件") + "（*.pem）|*.pem";
                                break;

                            case 5:
                                sfdSaveFile.Filter = UI.T("AndroidFile", "安卓证书 文件") + "（*.0）|*.0";
                                break;
                        }

                        string sPickedPath = await UI.PickSave(sfdSaveFile);
                        if (!string.IsNullOrEmpty(sPickedPath))
                        {
                            string FilePath = sPickedPath;
                            if (!string.IsNullOrEmpty(FilePath))
                            {
                                bool bExport = false;

                                switch (CerType)
                                {
                                    case 0:
                                        bExport = ProxyConfig.Proxy.ExportPemToCerFile(Properties.Resources.Cert_Ca, FilePath, false);
                                        break;

                                    case 1:
                                        bExport = ProxyConfig.Proxy.ExportPemToCerFile(Properties.Resources.Cert_Ca, FilePath, true);
                                        break;

                                    case 2:
                                        bExport = ProxyConfig.Proxy.ExportPemToCrtFile(Properties.Resources.Cert_Ca, FilePath, false);
                                        break;

                                    case 3:
                                        bExport = ProxyConfig.Proxy.ExportPemToCrtFile(Properties.Resources.Cert_Ca, FilePath, true);
                                        break;

                                    case 4:
                                        bExport = ProxyConfig.Proxy.ExportPemToPemFile(Properties.Resources.Cert_Ca, FilePath);
                                        break;

                                    case 5:
                                        bExport = ProxyConfig.Proxy.ExportPemToAndroidFile(Properties.Resources.Cert_Ca, FilePath);
                                        break;
                                }

                                if (bExport)
                                {
                                    string Title = UI.T("ExportCertFile.Success", "导出证书成功");
                                    UI.Notify(UiIcon.Success, Title, FilePath);
                                    Operate.DoLog(nameof(SaveCertToFile_Dialog), Title + ": " + FilePath);
                                }
                                else
                                {
                                    string Title = UI.T("ExportCertFile.Error", "导出证书失败");
                                    string Content = UI.T("CheckSystemLog", "请检查系统日志");
                                    UI.Notify(UiIcon.Error, Title, Content);
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveCertToFile_Dialog), ex);
                    }
                }

                #endregion

                #region//导出 Cer 证书

                public static bool ExportPemToCerFile(string pemContent, string outputFilePath, bool useBase64Encoding)
                {
                    try
                    {
                        if (useBase64Encoding)
                        {
                            File.WriteAllText(outputFilePath, pemContent);
                        }
                        else
                        {
                            string base64Data = ProxyConfig.Proxy.CleanPemContent(pemContent);
                            byte[] certData = Convert.FromBase64String(base64Data);

                            File.WriteAllBytes(outputFilePath, certData);
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ExportPemToCerFile), ex);
                        return false;
                    }
                }

                private static string CleanPemContent(string pemContent)
                {
                    return pemContent
                        .Replace("-----BEGIN CERTIFICATE-----", "")
                        .Replace("-----END CERTIFICATE-----", "")
                        .Replace("-----BEGIN RSA PRIVATE KEY-----", "")
                        .Replace("-----END RSA PRIVATE KEY-----", "")
                        .Replace("-----BEGIN PRIVATE KEY-----", "")
                        .Replace("-----END PRIVATE KEY-----", "")
                        .Replace("\n", "")
                        .Replace("\r", "")
                        .Trim();
                }

                #endregion

                #region//导出 Crt 证书

                public static bool ExportPemToCrtFile(string pemContent, string outputFilePath, bool useBase64Encoding)
                {
                    try
                    {
                        if (useBase64Encoding)
                        {
                            File.WriteAllText(outputFilePath, pemContent);
                        }
                        else
                        {
                            string base64Data = ProxyConfig.Proxy.CleanPemContent(pemContent);
                            byte[] certData = Convert.FromBase64String(base64Data);

                            File.WriteAllBytes(outputFilePath, certData);
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ExportPemToCrtFile), ex);
                        return false;
                    }
                }

