                #region//检测用户名和密码是否正确（区分大小写）

                public static (bool ok, Guid accountId) CheckUserNameAndPassWord(string userName, string passWord)
                {
                    try
                    {
                        string pwEncrypt = SystemConfig.PassWord_Encrypt(passWord);

                        foreach (var acc in ProxyConfig.Account.lstAccountInfo)
                        {
                            if (!acc.IsEnable) continue;
                            if (!acc.UserName.Equals(userName)) continue;
                            if (!acc.Password.Equals(pwEncrypt)) continue;

                            if (acc.IsExpiry && acc.ExpiryTime <= DateTime.Now)
                                return (false, Guid.Empty);

                            return (true, acc.AID);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckUserNameAndPassWord), ex);
                    }

                    return (false, Guid.Empty);
                }

                #endregion

                #region//检测是否已超过限制链接数

                public static bool CheckLimitLinks(Guid AID, string IPAddress)
                {
                    try
                    {
                        if (AID == Guid.Empty || string.IsNullOrEmpty(IPAddress))
                            return false;

                        AccountInfo paiAccount = ProxyConfig.Account.GetProxyAccount_ByAccountID(AID);
                        if (paiAccount == null || !paiAccount.IsLimitLinks)
                            return false;

                        int limitLinks = paiAccount.LimitLinks;
                        int currentLinks = Operate.ProxyConfig.Account.GetLinksNumber_ByAccountID(AID, IPAddress);

                        return currentLinks >= limitLinks;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckLimitLinks), ex);
                        return false;
                    }
                }

                #endregion

                #region//检测是否已超过限制设备数

                public static bool CheckLimitDevices(Guid AID, string ClientIP)
                {
                    try
                    {
                        if (AID == Guid.Empty || string.IsNullOrEmpty(ClientIP))
                            return false;

                        AccountInfo ai = ProxyConfig.Account.GetProxyAccount_ByAccountID(AID);                   
                        if (ai == null || !ai.IsLimitDevices)
                            return false;

                        int currentDevices = ProxyConfig.Account.GetDevicesNumber_ByAccountID(AID);
                        int limitDevices = ai.LimitDevices;

                        if (currentDevices < limitDevices)
                            return false;

                        if (currentDevices > limitDevices)
                            return true;

                        AuthInfo existingAuth = ProxyConfig.Account.FindAuthInfo(AID, ClientIP);
                        return existingAuth == null;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckLimitDevices), ex);
                        return false;
                    }
                }

                #endregion

