                /// <summary>遮罩上的那句话。两条导入路径共用，省得两处文案走岔。</summary>
                private static string ImportBusyText()
                {
                    return UI.T("ImportAccount.Busy", "正在导入账号…");
                }

                private static async Task<bool> LoadAccountList(string FilePath, bool LoadFromUser)
                {
                    try
                    {
                        if (File.Exists(FilePath))
                        {
                            string fileExtension = Path.GetExtension(FilePath);
                            if (!string.IsNullOrEmpty(fileExtension))
                            {
                                if (fileExtension.Equals(".ini"))
                                {
                                    await UI.Busy(ImportBusyText(), () =>
                                    {
                                        LoadAccountList_FromInIFile(FilePath);
                                        return true;
                                    });

                                    return true;
                                }
                                else
                                {
                                    #region//LoadProxyAccountList_FromXDocument

                                    XDocument xdoc = null;

                                    bool bEncrypt = SystemConfig.IsEncryptXMLFile(FilePath);
                                    if (bEncrypt)
                                    {
                                        if (LoadFromUser)
                                        {
                                            xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("ImportProxyAccountList", "导入代理账号列表"), FilePath);
                                        }
                                    }
                                    else
                                    {
                                        xdoc = XDocument.Load(FilePath);
                                    }

                                    if (xdoc == null)
                                    {
                                        string sError = UI.T("Password.Incorrect", "导入失败: 密码错误");
                                        if (LoadFromUser)
                                        {
                                            UI.Toast(UiIcon.Error, sError);
                                        }
                                        else
                                        {
                                            Operate.DoLog(nameof(LoadAccountList), sError);
                                        }

                                        return false;
                                    }

                                    /*
                                        B6 当年为了让密码框能弹出来，把整段从 Spin 的后台线程挪回了 UI 线程，
                                        代价是丢掉「正在导入…」遮罩。导几千个账号时界面就那么空着，
                                        看着像没导进去。

                                        现在按当初记下的办法拆开：<b>密码框在上面已经 await 完了</b>
                                        （它必须在 UI 线程），这里只剩纯解析 + 落库，可以安心丢后台。

                                        【为什么后台改 lstAccountInfo 是安全的】核过一遍：
                                        没有任何控件直接绑它 —— WinForms 侧的表格绑的是 GetPageData()
                                        现造的分页副本，导完再 RefreshAccountList() 重绑；
                                        唯一的 ListChanged 订阅者是 FeedPump，它只在锁里打个脏标记。
                                        再加一个绑它的控件之前，先回来看这一段。
                                    */
                                    await UI.Busy(ImportBusyText(), () =>
                                    {
                                        LoadAccountList_FromXDocument(xdoc);
                                        return true;
                                    });

                                    #endregion

                                    return true;
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadAccountList), ex);
                    }

                    return false;
                }

                public static void LoadAccountList_FromXDocument(XDocument xdoc)
                {
                    //四个结局各自记数，收尾汇总一条 —— 逐条明细回答不了「到底成了几条」
                    int Added = 0;
                    int Skipped = 0;
                    int Invalid = 0;
                    int Failed = 0;

                    //先全部加进内存，最后整批落一次库。理由见下面 AddProxyAccount 那处注释
                    var pending = new List<AccountInfo>();

                    try
                    {
                        foreach (XElement xeProxyAccount in xdoc.Root.Elements())
                        {
                            bool IsEnable = false;
                            if (xeProxyAccount.Element("IsEnable") != null)
                            {
                                IsEnable = bool.Parse(xeProxyAccount.Element("IsEnable").Value);
                            }

                            Guid AID = Guid.Empty;
                            if (xeProxyAccount.Element("ID") == null || !Guid.TryParse(xeProxyAccount.Element("ID").Value, out AID) || ProxyConfig.Account.GetProxyAccount_ByAccountID(AID) != null)
                            {
                                AID = Guid.NewGuid();
                            }

                            string UserName = string.Empty;
                            if (xeProxyAccount.Element("UserName") != null)
                            {
                                UserName = xeProxyAccount.Element("UserName").Value;
                            }

                            string PassWord = string.Empty;
                            if (xeProxyAccount.Element("PassWord") != null)
                            {
                                PassWord = xeProxyAccount.Element("PassWord").Value;
                            }

                            bool IsLimitLinks = false;
                            if (xeProxyAccount.Element("IsLimitLinks") != null)
                            {
                                IsLimitLinks = bool.Parse(xeProxyAccount.Element("IsLimitLinks").Value);
                            }

                            int LimitLinks = 1;
                            if (xeProxyAccount.Element("LimitLinks") != null)
                            {
                                LimitLinks = int.Parse(xeProxyAccount.Element("LimitLinks").Value);
                            }

                            bool IsLimitDevices = true;
                            if (xeProxyAccount.Element("IsLimitDevices") != null)
                            {
                                IsLimitDevices = bool.Parse(xeProxyAccount.Element("IsLimitDevices").Value);
                            }

                            int LimitDevices = 1;
                            if (xeProxyAccount.Element("LimitDevices") != null)
                            {
                                LimitDevices = int.Parse(xeProxyAccount.Element("LimitDevices").Value);
                            }

                            bool IsExpiry = false;
                            if (xeProxyAccount.Element("IsExpiry") != null)
                            {
                                IsExpiry = bool.Parse(xeProxyAccount.Element("IsExpiry").Value);
                            }

                            DateTime ExpiryTime = DateTime.Now;
                            if (xeProxyAccount.Element("ExpiryTime") != null)
                            {
                                ExpiryTime = DateTime.Parse(xeProxyAccount.Element("ExpiryTime").Value);
                            }

                            DateTime CreateTime = DateTime.Now;
                            if (xeProxyAccount.Element("CreateTime") != null)
                            {
                                CreateTime = DateTime.Parse(xeProxyAccount.Element("CreateTime").Value);
                            }

                            BindingList<AccountIPInfo> AIPInfo = new BindingList<AccountIPInfo>();

                            if (xeProxyAccount.Element("AccountIPInfo") != null)
                            {
                                foreach (XElement xeIPInfo in xeProxyAccount.Element("AccountIPInfo").Elements())
                                {
                                    DateTime LoginTime = DateTime.MinValue;
                                    if (xeIPInfo.Element("LoginTime") != null)
                                    {
                                        LoginTime = DateTime.Parse(xeIPInfo.Element("LoginTime").Value);
                                    }

                                    string LoginIP = string.Empty;
                                    if (xeIPInfo.Element("LoginIP") != null)
                                    {
                                        LoginIP = xeIPInfo.Element("LoginIP").Value;
                                    }

                                    ProxyConfig.Account.AddAccountIPInfo(AIPInfo, LoginTime, LoginIP);
                                }
                            }

                            /*
                                <b>SaveToDB 传 false</b>：这里只往内存列表里加，落库留到最后整批做。

                                原来是一条一次落库，而每次提交都要 sync 一遍日志文件 ——
                                实测 1000 条要 3528ms（3.53ms/条），整批一个事务只要 96ms，
                                相差 36 倍。导一千多个账号时那几秒就是这么来的。
                            */
                            bool bOK = ProxyConfig.Account.AddProxyAccount(
                                false,
                                AID,
                                IsEnable,
                                UserName,
                                PassWord,
                                AIPInfo,
                                IsLimitLinks,
                                LimitLinks,
                                IsLimitDevices,
                                LimitDevices,
                                IsExpiry,
                                ExpiryTime,
                                CreateTime);

                            if (bOK)
                            {
                                //加进内存了才排队落库 —— 重名被挡下的那些不该进这一批
                                pending.Add(ProxyConfig.Account.lstAccountInfo[ProxyConfig.Account.lstAccountInfo.Count - 1]);
                            }

                            if (bOK)
                            {
                                Added++;
                            }
                            else
                            {
                                /*
                                    AddProxyAccount 只回一个 bool，三条失败路径长得一模一样：
                                    数据不全 / 用户名已存在 / 中途抛异常。
                                    光记「导入账号失败！用户名：xxx」等于什么都没说 ——
                                    把同一份文件导两次，会刷出上千行看不出原因的日志。
                                    所以在这里把原因分出来。

                                    【为什么这个判断可靠】只有 bOK 为 false 才走到这里，
                                    也就是说这一条<b>不是</b>我们刚加进去的；
                                    此刻还查得到同名账号，那它就是本来就在表里的。
                                */
                                string Reason;

                                if (AID == Guid.Empty || string.IsNullOrEmpty(UserName) || string.IsNullOrEmpty(PassWord))
                                {
                                    Reason = UI.T("ImportAccount.Invalid", "账号数据不完整（缺编号 / 用户名 / 密码）");
                                    Invalid++;
                                }
                                else if (ProxyConfig.Account.CheckProxyAccount_Exist(UserName))
                                {
                                    Reason = UI.T("ImportAccount.Exist", "用户名已存在，已跳过");
                                    Skipped++;
                                }
                                else
                                {
                                    Reason = UI.T("ImportAccount.Failed", "写入失败，原因见上一条日志");
                                    Failed++;
                                }

                                string FailLog = string.Format(
                                    UI.T("ImportAccount.Error", "导入账号失败！用户名：{0}（{1}）"), UserName, Reason);

                                Operate.DoLog(nameof(LoadAccountList_FromXDocument), FailLog);
                            }
                        }

                        /*
                            整批落一次库。

                            放在循环<b>外面</b>是这次优化的全部：一个连接、一个事务、
                            命令只 prepare 一次。中途出错整批回滚 —— 对导入来说这是对的，
                            「导了一半」比「没导」难收拾得多，重导一次就行。
                        */
                        int SavedToDB = DataBase.InsertTable_ProxyAccountBatch(pending);

                        if (SavedToDB != pending.Count)
                        {
                            /*
                                内存里加了、库里没进去 —— 两边不一致，必须说出来。
                                最常见的原因是整批回滚（上面那个 catch 里已经记了异常）。
                                不静默：下次启动这些账号就没了，而用户以为导入成功了。
                            */
                            Operate.DoLog(nameof(LoadAccountList_FromXDocument), string.Format(
                                UI.T("ImportAccount.DbMismatch",
                                    "警告：{0} 条已加入列表，但只有 {1} 条写进了数据库，重启后会丢失"),
                                pending.Count, SavedToDB));
                        }

                        /*
                            收尾给一条汇总。

                            上面那些是逐条的明细，一次导入几百条时全是同样的字，
                            翻到底也说不清「到底成了几条」。这一条才是用户真正要看的结论。
                        */
                        string Summary = string.Format(
                            UI.T("ImportAccount.Summary", "导入账号完成：新增 {0} 条，已存在跳过 {1} 条，数据不完整 {2} 条，写入失败 {3} 条"),
                            Added, Skipped, Invalid, Failed);

                        Operate.DoLog(nameof(LoadAccountList_FromXDocument), Summary);

                        //一条都没进来时提一句，否则界面上「导入成功」而列表纹丝不动，看着像坏了
                        if (Added == 0 && Skipped > 0)
                        {
                            UI.Toast(UiIcon.Warn, string.Format(
                                UI.T("ImportAccount.AllExist", "这些账号都已存在，没有新增（共 {0} 条）"), Skipped));
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadAccountList_FromXDocument), ex);
                    }
                }

                private static void LoadAccountList_FromInIFile(string filePath)
                {
                    try
                    {
                        string[] lines = File.ReadAllLines(filePath);

                        AccountInfo pai = null;
                        foreach (string line in lines)
                        {
                            string trimmedLine = line.Trim();
                            if (trimmedLine.StartsWith("[User"))
                            {
                                if (pai != null)
                                {
                                    ProxyConfig.Account.AddAccount_FromIniFile(pai);
                                }

                                pai = new AccountInfo();
                            }
                            else if (trimmedLine.Contains("="))
                            {
                                string[] parts = trimmedLine.Split(new char[] { '=' }, 2);
                                string key = parts[0].Trim();
                                string value = parts[1].Trim();

                                switch (key)
                                {
                                    case "Enable":
                                        pai.IsEnable = Convert.ToBoolean(int.Parse(value));
                                        break;

                                    case "UserName":
                                        pai.UserName = value;
                                        break;

                                    case "Password":
                                        pai.Password = value;
                                        break;

                                    case "MaxConn":
                                        if (value.Equals("-1"))
                                        {
                                            pai.IsLimitLinks = false;
                                            pai.LimitLinks = 1;
                                        }
                                        else
                                        {
                                            pai.IsLimitLinks = true;
                                            pai.LimitLinks = int.Parse(value);
                                        }
                                        break;

                                    case "AutoDisable":
                                        pai.IsExpiry = Convert.ToBoolean(int.Parse(value));
                                        break;

                                    case "DisableDateTime":
                                        pai.ExpiryTime = DateTime.Parse(value);
                                        break;
                                }
                            }
                        }

                        if (pai != null)
                        {
                            ProxyConfig.Account.AddAccount_FromIniFile(pai);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadAccountList_FromInIFile), ex);
                    }
                }

                private static void AddAccount_FromIniFile(AccountInfo ai)
                {
                    try
                    {
                        if (ai != null)
                        {
                            if (ai.AID == null || ai.AID == Guid.Empty)
                            {
                                ai.AID = Guid.NewGuid();
                            }

                            if (ai.ExpiryTime == DateTime.MinValue)
                            {
                                ai.ExpiryTime = DateTime.Now;
                            }

                            if (ai.CreateTime == DateTime.MinValue)
                            {
                                ai.CreateTime = DateTime.Now;
                            }
                            
                            ai.IsLimitDevices = true;
                            ai.LimitDevices = 1;

                            bool bOK = ProxyConfig.Account.AddProxyAccount(
                                true,
                                ai.AID,
                                ai.IsEnable,
                                ai.UserName,
                                ai.Password,
                                new BindingList<AccountIPInfo>(),
                                ai.IsLimitLinks,
                                ai.LimitLinks,
                                ai.IsLimitDevices,
                                ai.LimitDevices,
                                ai.IsExpiry,
                                ai.ExpiryTime,
                                ai.CreateTime);

                            if (!bOK)
                            {
                                string FailLog = string.Format(UI.T("ImportAccount.Error", "导入账号失败！用户名：{0}"), ai.UserName);
                                Operate.DoLog(nameof(AddAccount_FromIniFile), FailLog);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddAccount_FromIniFile), ex);
                    }
                }

                #endregion
            }

            #endregion

            #region//代理映射

            public static class Mapping
            {
                public static bool IsShow_MapLocal = false, IsShow_MapRemote = false;
                public static bool Enable_MapLocal = false, Enable_MapRemote = false;
                public static BindingList<MapLocal> lstMapLocal = new BindingList<MapLocal>();
                public static BindingList<MapRemote> lstMapRemote = new BindingList<MapRemote>();

                #region//获取 MapProtocol 类型

                public static ProxyConfig.Proxy.MapProtocol GetMapProtocol_ByString(string MapProtocol)
                {
                    ProxyConfig.Proxy.MapProtocol MProtocol = ProxyConfig.Proxy.MapProtocol.Http;

                    try
                    {
                        MProtocol = (ProxyConfig.Proxy.MapProtocol)Enum.Parse(typeof(ProxyConfig.Proxy.MapProtocol), MapProtocol);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetMapProtocol_ByString), ex);
                    }

                    return MProtocol;
                }

