                #region//是否显示封包（过滤条件）

                public static bool IsShowPacket_ByFilter(PacketInfo pi)
                {
                    return IsShowByFilter(
                        pi.PacketSocket,
                        pi.PacketFrom,
                        pi.PacketTo,
                        pi.PacketBuffer,
                        pi.PacketLen,
                        pi.PacketType
                    );
                }

                public static bool IsShowProxy_ByFilter(ProxyInfo pi)
                {
                    return IsShowByFilter(
                        pi.PacketSocket,
                        pi.ClientAddr,
                        pi.ServerAddr,
                        pi.PacketBuffer,
                        pi.PacketLen,
                        pi.PacketType
                    );
                }

                private static bool IsShowByFilter(
                    int packetSocket, 
                    string fromAddr, 
                    string toAddr,
                    byte[] packetBuffer, 
                    int packetLen, 
                    PacketConfig.Packet.PacketType packetType)
                {
                    try
                    {
                        //套接字
                        if (SystemConfig.CheckSocket)
                        {
                            bool bIsFilter = IsFilter_BySocket(packetSocket);
                            if (SystemConfig.CheckNotShow == bIsFilter)
                            {
                                return false;
                            }
                        }

                        //IP地址
                        if (SystemConfig.CheckIP)
                        {
                            bool bIsFilter_From = IsFilter_ByIP(fromAddr);
                            bool bIsFilter_To = IsFilter_ByIP(toAddr);
                            if (SystemConfig.CheckNotShow == (bIsFilter_From || bIsFilter_To))
                            {
                                return false;
                            }
                        }

                        //端口号
                        if (SystemConfig.CheckPort)
                        {
                            bool bIsFilter_From = IsFilter_ByPort(fromAddr);
                            bool bIsFilter_To = IsFilter_ByPort(toAddr);
                            if (SystemConfig.CheckNotShow == (bIsFilter_From || bIsFilter_To))
                            {
                                return false;
                            }
                        }

                        //指定包头
                        if (SystemConfig.CheckHead)
                        {
                            bool bIsFilter = IsFilter_ByHead(packetBuffer);
                            if (SystemConfig.CheckNotShow == bIsFilter)
                            {
                                return false;
                            }
                        }

                        //封包内容
                        if (SystemConfig.CheckData)
                        {
                            bool bIsFilter = IsFilter_ByPacket(packetBuffer);
                            if (SystemConfig.CheckNotShow == bIsFilter)
                            {
                                return false;
                            }
                        }

                        //封包大小
                        if (SystemConfig.CheckLen)
                        {
                            bool bIsFilter = IsFilter_BySize(packetLen);
                            if (SystemConfig.CheckNotShow == bIsFilter)
                            {
                                return false;
                            }
                        }

                        //封包类别
                        if (SystemConfig.CheckType)
                        {
                            bool bIsFilter = FilterConfig.Filter.CheckFilterFunction_ByPacketType(packetType, Operate.SystemConfig.CheckType_Value);
                            if (SystemConfig.CheckNotShow == bIsFilter)
                            {
                                return false;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsShowByFilter), ex);
                    }

                    return true;
                }

                #region//检测套接字

                public static bool IsFilter_BySocket(int iPacketSocket)
                {
                    try
                    {
                        if (!string.IsNullOrEmpty(SystemConfig.CheckSocket_Value))
                        {
                            string[] sSocketArr = SystemConfig.CheckSocket_Value.Split(';');
                            HashSet<int> socketSet = new HashSet<int>();

                            foreach (string sSocket in sSocketArr)
                            {
                                if (!string.IsNullOrEmpty(sSocket) && int.TryParse(sSocket, out int iCheckSocket))
                                {
                                    socketSet.Add(iCheckSocket);
                                }
                            }

                            return socketSet.Contains(iPacketSocket);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_BySocket), ex);
                    }

                    return false;
                }

                #endregion

                #region//检测IP地址

                public static bool IsFilter_ByIP(string sPacketIP)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(sPacketIP) || string.IsNullOrEmpty(SystemConfig.CheckIP_Value))
                        {
                            return false;
                        }

                        string sIP = sPacketIP.Split(':')[0];
                        HashSet<string> ipSet = new HashSet<string>(SystemConfig.CheckIP_Value.Split(';'));

                        return ipSet.Contains(sIP);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_ByIP), ex);
                    }

                    return false;
                }

                #endregion

                #region//检测端口号

                public static bool IsFilter_ByPort(string sPacketPort)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(sPacketPort) || string.IsNullOrEmpty(SystemConfig.CheckPort_Value))
                        {
                            return false;
                        }

                        string sPort = sPacketPort.Split(':')[1];
                        HashSet<string> portSet = new HashSet<string>(SystemConfig.CheckPort_Value.Split(';'));

                        return portSet.Contains(sPort);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_ByPort), ex);
                    }

                    return false;
                }

                #endregion

                #region//检测包头

                public static bool IsFilter_ByHead(byte[] bBuffer)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(SystemConfig.CheckHead_Value))
                        {
                            return false;
                        }

                        string checkHeadValue = SystemConfig.CheckHead_Value.Replace(" ", "");
                        string[] headValues = checkHeadValue.Split(';');

                        foreach (string headValue in headValues)
                        {
                            if (!string.IsNullOrEmpty(headValue))
                            {
                                byte[] headBytes = SystemConfig.StringToBytes(Operate.PacketConfig.Packet.EncodingFormat.Hex, headValue);

                                if (bBuffer.Length >= headBytes.Length)
                                {
                                    bool match = true;
                                    for (int i = 0; i < headBytes.Length; i++)
                                    {
                                        if (bBuffer[i] != headBytes[i])
                                        {
                                            match = false;
                                            break;
                                        }
                                    }

                                    if (match)
                                    {
                                        return true;
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_ByHead), ex);
                    }

                    return false;
                }

                #endregion

                #region//检测封包内容

                public static bool IsFilter_ByPacket(byte[] bBuffer)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(SystemConfig.CheckData_Value))
                        {
                            return false;
                        }

                        string checkDataValue = SystemConfig.CheckData_Value.Replace(" ", "");
                        string[] checkDataArray = checkDataValue.Split(';');

                        string packetString = SystemConfig.BytesToString(Operate.PacketConfig.Packet.EncodingFormat.Hex, bBuffer).Replace(" ", "");

                        foreach (string checkData in checkDataArray)
                        {
                            if (!string.IsNullOrEmpty(checkData) && packetString.IndexOf(checkData) >= 0)
                            {
                                return true;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_ByPacket), ex);
                    }

                    return false;
                }

                #endregion

                #region//检测封包大小

                public static bool IsFilter_BySize(int PacketLength)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(SystemConfig.CheckLength_Value))
                        {
                            return false;
                        }

                        string[] lengthArray = SystemConfig.CheckLength_Value.Split(';');

                        foreach (string length in lengthArray)
                        {
                            if (string.IsNullOrEmpty(length))
                            {
                                continue;
                            }

                            if (length.Contains("-"))
                            {
                                string[] range = length.Split('-');
                                if (range.Length == 2 && int.TryParse(range[0], out int iFrom) && int.TryParse(range[1], out int iTo))
                                {
                                    if (PacketLength >= iFrom && PacketLength <= iTo)
                                    {
                                        return true;
                                    }
                                }
                            }
                            else
                            {
                                if (int.TryParse(length, out int iLength))
                                {
                                    if (PacketLength == iLength)
                                    {
                                        return true;
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(IsFilter_BySize), ex);
                    }

                    return false;
                }

                #endregion                

                #endregion

                #region//获取封包数据字符串（十六进制）

                public static string GetPacketData_Hex(Span<byte> bBuff, int Max_DataLen)
                {
                    string sReturn = string.Empty;

                    try
                    {
                        int iPacketLen = bBuff.Length;

                        if (iPacketLen > Max_DataLen)
                        {
                            Span<byte> bBuffSlice = bBuff.Slice(0, Max_DataLen);
                            sReturn = SystemConfig.BytesToString(Operate.PacketConfig.Packet.EncodingFormat.Hex, bBuffSlice) + " ...";
                        }
                        else
                        {
                            sReturn = SystemConfig.BytesToString(Operate.PacketConfig.Packet.EncodingFormat.Hex, bBuff);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetPacketData_Hex), ex);
                    }

                    return sReturn;
                }

                #endregion

                #region//获取 SockAddr 对应的 IP 地址和端口

                public static string GetIPString_BySocketAddr(int pSocket, Operate.PacketConfig.Packet.SockAddr pAddr, Operate.PacketConfig.Packet.PacketType pType)
                {
                    string sIP_From = string.Empty;
                    string sIP_To = string.Empty;

                    try
                    {
                        sIP_From = PacketConfig.Packet.GetIP_BySocket(pSocket, Operate.PacketConfig.Packet.IPType.From);

                        switch (pType)
                        {
                            case Operate.PacketConfig.Packet.PacketType.WS1_Send:
                            case Operate.PacketConfig.Packet.PacketType.WS2_Send:
                            case Operate.PacketConfig.Packet.PacketType.WS1_Recv:
                            case Operate.PacketConfig.Packet.PacketType.WS2_Recv:
                            case Operate.PacketConfig.Packet.PacketType.WSASend:
                            case Operate.PacketConfig.Packet.PacketType.WSARecv:
                            case Operate.PacketConfig.Packet.PacketType.WSARecvEx:
                            case Operate.PacketConfig.Packet.PacketType.TCP_Req:
                            case Operate.PacketConfig.Packet.PacketType.UDP_Req:
                            case Operate.PacketConfig.Packet.PacketType.TCP_Resp:
                            case Operate.PacketConfig.Packet.PacketType.UDP_Resp:

                                sIP_To = PacketConfig.Packet.GetIP_BySocket(pSocket, Operate.PacketConfig.Packet.IPType.To);

                                break;

                            case Operate.PacketConfig.Packet.PacketType.WS1_SendTo:
                            case Operate.PacketConfig.Packet.PacketType.WS2_SendTo:
                            case Operate.PacketConfig.Packet.PacketType.WS1_RecvFrom:
                            case Operate.PacketConfig.Packet.PacketType.WS2_RecvFrom:
                            case Operate.PacketConfig.Packet.PacketType.WSASendTo:
                            case Operate.PacketConfig.Packet.PacketType.WSARecvFrom:

                                sIP_To = PacketConfig.Packet.GetIP_BySockAddr(pAddr);

                                break;
                        }

                        if (!string.IsNullOrEmpty(sIP_From) && !string.IsNullOrEmpty(sIP_To))
                        {
                            var sb = new StringBuilder(sIP_From);
                            sb.Append("|");
                            sb.Append(sIP_To);
                            return sb.ToString();
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetIPString_BySocketAddr), ex);
                    }

                    return string.Empty;
                }

                public static string GetIP_BySockAddr(Operate.PacketConfig.Packet.SockAddr saAddr)
                {
                    string sReturn = string.Empty;

                    try
                    {
                        if (saAddr.sin_family == (short)AddressFamily.InterNetwork)
                        {
                            string sIP = Marshal.PtrToStringAnsi(WS2_32.inet_ntoa(saAddr.sin_addr));
                            string sPort = WS2_32.ntohs(saAddr.sin_port).ToString();
                            sReturn = $"{sIP}:{sPort}";
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetIP_BySockAddr), ex);
                    }

                    return sReturn;
                }

                public static string GetIP_BySocket(int Socket, Operate.PacketConfig.Packet.IPType IPType)
                {
                    string sReturn = "";

                    try
                    {
                        Operate.PacketConfig.Packet.SockAddr saAddr = new Operate.PacketConfig.Packet.SockAddr();
                        saAddr.sin_family = (short)AddressFamily.InterNetwork;
                        int iAddrLen = Marshal.SizeOf(saAddr);

                        switch (IPType)
                        {
                            case Operate.PacketConfig.Packet.IPType.From:
                                WS2_32.getsockname(Socket, ref saAddr, ref iAddrLen);
                                break;

                            case Operate.PacketConfig.Packet.IPType.To:
                                WS2_32.getpeername(Socket, ref saAddr, ref iAddrLen);
                                break;
                        }

                        sReturn = GetIP_BySockAddr(saAddr);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetIP_BySocket), ex);
                    }

                    return sReturn;
                }

                #endregion

                #region//获取 IP 地址和端口对应的 SockAddr

                public static Operate.PacketConfig.Packet.SockAddr GetSocketAddr_ByIPString(string IPString)
                {
                    Operate.PacketConfig.Packet.SockAddr saReturn = new Operate.PacketConfig.Packet.SockAddr();

                    try
                    {
                        if (!string.IsNullOrEmpty(IPString) && IPString.IndexOf(":") > 0)
                        {
                            string sIP = IPString.Split(':')[0];
                            int iPort = int.Parse(IPString.Split(':')[1]);

                            IPAddress ipAddress = IPAddress.Parse(sIP);

                            saReturn.sin_family = ((short)AddressFamily.InterNetwork);
                            saReturn.sin_port = (ushort)IPAddress.HostToNetworkOrder((short)iPort);
                            saReturn.sin_addr = (uint)ipAddress.GetHashCode();
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetSocketAddr_ByIPString), ex);
                    }

                    return saReturn;
                }

                #endregion

                #region//统计封包数量

                public static void CountPacketInfo(Operate.PacketConfig.Packet.PacketType ptPacketType, int packetLength)
                {
                    try
                    {
                        if (packetLength > 0)
                        {
                            Interlocked.Increment(ref Operate.PacketConfig.Packet.TotalPackets);

                            switch (ptPacketType)
                            {
                                case Operate.PacketConfig.Packet.PacketType.WS1_Send:
                                case Operate.PacketConfig.Packet.PacketType.WS2_Send:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.Send_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_SendBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WS1_SendTo:
                                case Operate.PacketConfig.Packet.PacketType.WS2_SendTo:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.SendTo_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_SendBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WSASend:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.WSASend_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_SendBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WSASendTo:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.WSASendTo_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_SendBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WS1_Recv:
                                case Operate.PacketConfig.Packet.PacketType.WS2_Recv:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.Recv_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_RecvBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WS1_RecvFrom:
                                case Operate.PacketConfig.Packet.PacketType.WS2_RecvFrom:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.RecvFrom_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_RecvBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WSARecv:
                                case Operate.PacketConfig.Packet.PacketType.WSARecvEx:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.WSARecv_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_RecvBytes, packetLength);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.WSARecvFrom:
                                    Interlocked.Increment(ref Operate.PacketConfig.Packet.WSARecvFrom_CNT);
                                    Interlocked.Add(ref Operate.PacketConfig.Packet.Total_RecvBytes, packetLength);
                                    break;

                                //与代理列表那支孪生 switch 同一条规矩：不认识的类型要出声，理由见那边的注释
                                default:
                                    Operate.SystemConfig.LogThrottled(
                                        "PacketType." + ptPacketType,
                                        string.Format(
                                            UI.T("List.UnknownType",
                                                "未计入统计的封包类型：{0}（{1}）—— 它进得了列表，但不算进「代理总数」/ 流量 / 速率"),
                                            (int)ptPacketType, ptPacketType));
                                    break;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CountPacketInfo), ex);
                    }
                }

                #endregion

                #region//判断 Socket 错误码是否是预期的错误

                public static bool IsExpectedSocketError(int errorCode)
                {
                    // 10053: 软件导致连接中止
                    // 10054: 远程主机强迫关闭了一个现有的连接
                    return errorCode == 10053 || errorCode == 10054;
                }

                #endregion
            }

            #endregion

            #region//封包队列

            public static class Queue
            {
                public static ConcurrentQueue<PacketInfo> cqPacketInfo = new ConcurrentQueue<PacketInfo>();

                #region//封包入队列            

                public static async void PacketInfo_ToQueue(
                    int iSocket,
                    byte[] bRawBuff,
                    byte[] bBuffByte,
                    string PacketData,
                    PacketConfig.Packet.PacketType ptPacketType,
                    PacketConfig.Packet.SockAddr sAddr,
                    FilterConfig.Filter.FilterAction pAction,
                    DateTime PacketTime)
                {
                    try
                    {
                        PacketConfig.Packet.CountPacketInfo(ptPacketType, bBuffByte.Length);

                        if (!SystemConfig.SpeedMode)
                        {
                            string sPacketIP = PacketConfig.Packet.GetIPString_BySocketAddr(iSocket, sAddr, ptPacketType);

                            if (!string.IsNullOrEmpty(sPacketIP) && sPacketIP.Contains("|"))
                            {
                                string[] ipParts = sPacketIP.Split('|');
                                string sIPFrom = ipParts[0];
                                string sIPTo = ipParts[1];
                                string sFromLocation = await SystemConfig.GetIPLocation(sIPFrom.Split(':')[0]);
                                string sToLocation = await SystemConfig.GetIPLocation(sIPTo.Split(':')[0]);

                                if (string.IsNullOrEmpty(PacketData))
                                {
                                    PacketData = PacketConfig.Packet.GetPacketData_Hex(bBuffByte, PacketConfig.Packet.PacketData_MaxLen);
                                }

                                PacketInfo pi = new PacketInfo(
                                    PacketTime, 
                                    iSocket, 
                                    ptPacketType, 
                                    sIPFrom, 
                                    sFromLocation,
                                    sIPTo, 
                                    sToLocation,
                                    bRawBuff, 
                                    bBuffByte,
                                    PacketData,
                                    bBuffByte.Length, 
                                    pAction);

                                cqPacketInfo.Enqueue(pi);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(PacketInfo_ToQueue), ex);
                    }
                }

                #endregion

                #region//清除封包队列

                public static void ClearPacketQueue()
                {
                    try
                    {
                        while (!cqPacketInfo.IsEmpty)
                        {
                            cqPacketInfo.TryDequeue(out PacketInfo spc);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ClearPacketQueue), ex);
                    }
                }

                #endregion
            }

            #endregion

            #region//封包列表

            public static class List
            {
                public static bool IsShow_ID = true;
                public static bool IsShow_ProxyTime = true;
                public static bool IsShow_PacketType = true;
                public static bool IsShow_PacketSocket = true;
                public static bool IsShow_ClientAddr = true;
                public static bool IsShow_ClientLocation = true;
                public static bool IsShow_ServerAddr = true;
                public static bool IsShow_ServerLocation = true;
                public static bool IsShow_PacketLen = true;
                public static bool IsShow_PacketData = true;
                public static bool AutoRoll = false;
                public static bool AutoClear = true;
                public static decimal AutoClear_Value = 5000;
                public static int Search_Index = -1;
                public static FindOptions FindOptions = new FindOptions();
                public static string FindRegex = string.Empty;

                /// <summary>
                /// 上一次 <see cref="SearchForList{T}"/> 命中的那一段在封包里的<b>字节</b>偏移，没有则 −1。
                ///
                /// 十六进制模式是精确的：那一路正则跑在「整包的十六进制文本」上，匹配位置除以 2 就是字节位置。
                /// 文本模式只能<b>估</b>：那串是 UTF8 解码来的，一个字符可能占好几个字节、
                /// 非法字节还会变成替换字符，字符下标换算不回字节下标 —— 做法见 Text 分支里的注释。
                /// </summary>
                public static int FindByteOffset = -1;

                /// <summary>
                /// 上一次命中<b>之后</b>该从哪儿接着找（在这一行<b>之内</b>的位置，单位与该模式的正则跑在
                /// 哪个串上一致：十六进制是十六进制文本的字符下标，文本是解码后字符串的字符下标）。
                ///
                /// ⚠️ 这一条是「查找下一个」能走到<b>同一个封包里下一处</b>的全部依据。
                /// 没有它的时候游标只有「行」这一个粒度，一个包里命中三次也只看得到第一处，
                /// 点「查找下一个」直接跳去下一条包 —— 而 WinForms 那边是逐处走的
                /// （那边十六进制控件自带的查找是从当前光标往后走的，实测 1 → 5 → 9 → −1，
                /// 而 ProxyList 只在它返回 false 时才把 Search_Index 加一）。
                ///
                /// 调用方把它原样再传回 <c>fromPos</c> 即可，<b>不需要知道它是什么单位</b>。
                /// </summary>
                public static int FindNextPos = 0;
                public static PacketInfo piSelect;
                public static BindingList<PacketInfo> lstPacketInfo = new BindingList<PacketInfo>();

                #region//按行号取封包（B9a）

                //封包字节不进推送流：列表只出元数据，界面选中某行时才按 Id 回来取完整字节。
                //100 条/秒 × 4KB 的字节流走推送是纯浪费，这两个方法就是那条「按需拉取」的通道。
                //行已被自动清理时返回 null，调用方按「该封包已不在列表里」处理。

                /// <summary>按行号取封包数据（经过滤镜改写后的内容）。取不到返回 null。</summary>
                public static byte[] GetPacketBufferById(long Id)
                {
                    PacketInfo pi = GetPacketById(Id);
                    return pi?.PacketBuffer;
                }

                /// <summary>按行号取原始封包数据（滤镜改写之前的内容）。取不到返回 null。</summary>
                public static byte[] GetRawBufferById(long Id)
                {
                    PacketInfo pi = GetPacketById(Id);
                    return pi?.RawBuffer;
                }

                /// <summary>
                /// 按行号找封包。
                ///
                /// <b>刻意用线性扫描而不是二分</b>：Id 在构造时分配，而 PacketInfo_ToQueue 是 async void，
                /// 构造与入队之间隔着十几行，多个 Hook 线程并发时列表里的 Id 可能出现逆序
                /// （线程 A 拿到 5、线程 B 拿到 6，但 B 先入队）。二分会因此漏查。
                /// 本方法只在用户点选某行时调用，扫 5000 行是微秒级，不值得为此赌顺序。
                /// </summary>
                public static PacketInfo GetPacketById(long Id)
                {
                    try
                    {
                        var list = lstPacketInfo;

                        //从后往前：用户点的通常是新数据
                        for (int i = list.Count - 1; i >= 0; i--)
                        {
                            PacketInfo pi = list[i];
                            if (pi != null && pi.Id == Id) { return pi; }
                        }
                    }
                    catch (Exception ex)
                    {
                        //并发裁剪可能让下标瞬时越界，按「找不到」处理即可
                        Operate.DoLog(nameof(GetPacketById), ex);
                    }

                    return null;
                }

                #endregion

                #region//封包列表右键菜单 - 外壳入口（只出基础类型，按 Id 收发）

                /*
                    对应 WinForms 的 PacketList.cs 里那个右键菜单（菜单本身由
                    PacketConfig.List.GetCMS_PacketList 定义、动作在 PacketList 的 switch 里）。

                    这一族与 ProxyConfig.List 里的 *_ByProxyIds <b>逐个对应</b>，
                    区别只在取哪份列表、以及地址字段的名字：
                    ProxyInfo 分「客户端 / 服务端」，PacketInfo 分「本机 / 远端」。
                    合成一份泛型的代价是把两个不相关的模型绑在一起，而它们各自还会长
                    —— 照着写一份更便宜。

                    <b>菜单结构没走桥</b>：与其余各屏一致，由前端自己拼。这里只出动作。
                    PacketInfo.Id 是运行期自增的 long，与按行取字节用的是同一个键。
                */

                /// <summary>
                /// 记下「当前选中的那一条封包」。
                ///
                /// <b>WinForms 侧是表格的 SelectedIndexChanged 顺手做的</b>（PacketList.cs:969），
                /// 外壳没有那个控件 —— 不设的话两条机器人指令会静默失效：
                /// 「发送 → 封包列表」（发的就是这一条）与「设置系统套接字 → 封包列表」。
                /// 这两条在注入模式下都跑在目标进程里，读的是 Runtime 快照里的这一份，
                /// 所以调用方设完还要把 Runtime 推下去。
                ///
                /// <paramref name="Id"/> 传 0 或找不到时清空（等价于 SelectedIndex = -1）。
                /// </summary>
                public static bool SetSelectedPacket_ById(long Id)
                {
                    try
                    {
                        piSelect = Id == 0 ? null : GetPacketById(Id);
                        return piSelect != null;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SetSelectedPacket_ById), ex);
                        return false;
                    }
                }

                /// <summary>Id 数组 → 模型列表，<b>按列表里的先后顺序</b>返回。</summary>
                internal static List<PacketInfo> PickPackets(IList<long> Ids)   //internal：封包编辑（PacketEditConfig）也按 Id 取同一份
                {
                    var picked = new List<PacketInfo>();

                    if (Ids == null || Ids.Count == 0)
                    {
                        return picked;
                    }

                    var want = new HashSet<long>(Ids);

                    foreach (PacketInfo pi in PacketConfig.List.lstPacketInfo)
                    {
                        if (want.Contains(pi.Id))
                        {
                            picked.Add(pi);
                        }
                    }

                    return picked;
                }

                /// <summary>
                /// 「复制」：选中那几条的十六进制，每条一行。
                ///
                /// 由 C# 拼好整段文本再交给前端写剪贴板 —— 让前端逐条取字节再自己转十六进制，
                /// 既多几十次往返，格式还会和 WinForms 那份不一致。
                /// </summary>
                public static string GetPacketHex_ByIds(IList<long> Ids)
                {
                    try
                    {
                        var sb = new StringBuilder();

                        foreach (PacketInfo pi in PacketConfig.List.PickPackets(Ids))
                        {
                            sb.AppendLine(SystemConfig.BytesToString(
                                PacketConfig.Packet.EncodingFormat.Hex, pi.PacketBuffer));
                        }

                        return sb.ToString();
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetPacketHex_ByIds), ex);
                        return string.Empty;
                    }
                }

                /// <summary>「添加到发送」：把选中那几条追加进某条发送的发送集。返回加了几条。</summary>
                public static int AddToSend_ByPacketIds(string SID, IList<long> Ids)
                {
                    try
                    {
                        Guid gid;

                        if (!Guid.TryParse(SID, out gid))
                        {
                            return 0;
                        }

                        List<PacketInfo> picked = PacketConfig.List.PickPackets(Ids);

                        if (picked.Count == 0)
                        {
                            return 0;
                        }

                        if (!SendConfig.Send.AddSendCollection_ByPacketInfo(gid, picked))
                        {
                            return 0;
                        }

                        /*
                            发送集变了，SendRow 的 PacketCount 跟着变 —— 但那是<b>就地改属性</b>，
                            不触发 ListChanged，不标脏的话发送列表那一列的数字不会动。
                        */
                        SendConfig.List.SaveSendList_ToDB();
                        FeedPump.MarkDirty(FeedList.Send);

                        return picked.Count;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddToSend_ByPacketIds), ex);
                        return 0;
                    }
                }

                /// <summary>「添加到仓库」。返回加了几条。</summary>
                public static int AddToWareHouse_ByPacketIds(string WID, IList<long> Ids)
                {
                    try
                    {
                        Guid gid;

                        if (!Guid.TryParse(WID, out gid))
                        {
                            return 0;
                        }

                        List<PacketInfo> picked = PacketConfig.List.PickPackets(Ids);

                        if (picked.Count == 0)
                        {
                            return 0;
                        }

                        if (!WareHouseConfig.WareHouse.AddStores_ByPacketInfo(gid, picked))
                        {
                            return 0;
                        }

                        FeedPump.MarkDirty(FeedList.WareHouse);
                        return picked.Count;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddToWareHouse_ByPacketIds), ex);
                        return 0;
                    }
                }

                /// <summary>
                /// 「添加到滤镜列表」。<b>只用第一条</b> —— 与 WinForms 一致（那边也是 piList[0]）：
                /// 一条滤镜描述的是「怎么匹配、怎么改」，多选几条也只能拿一条去造。
                /// </summary>
                public static bool AddToFilter_ByPacketId(long Id)
                {
                    try
                    {
                        List<PacketInfo> picked = PacketConfig.List.PickPackets(new List<long> { Id });

                        if (picked.Count == 0)
                        {
                            return false;
                        }

                        if (!FilterConfig.Filter.AddFilter_ByPacketInfo(picked[0], null))
                        {
                            return false;
                        }

                        FilterConfig.List.SaveFilterList_ToDB();
                        FeedPump.MarkDirty(FeedList.Filter);
                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddToFilter_ByPacketId), ex);
                        return false;
                    }
                }

                /// <summary>
                /// 「设置系统套接字」：把这一条的套接字号设成全局的。
                /// 发送编辑里勾「使用系统套接字」用的就是它。返回设成了几号，0 表示没设上。
                /// </summary>
                public static int SetSystemSocket_ByPacketId(long Id)
                {
                    try
                    {
                        List<PacketInfo> picked = PacketConfig.List.PickPackets(new List<long> { Id });

                        if (picked.Count == 0)
                        {
                            return 0;
                        }

                        /*
                            ⚠️ <b>只有 > 0 才算数</b>，与机器人那条「设置 - 系统套接字」指令
                            （RobotExecute 里的 if (iSocket > 0)）对齐。

                            SunnyNet 那条中间人路上产出的封包（HTTP / HTTPS / WebSocket）
                            <b>套接字一律是 0</b> —— 它们靠会话号回发，压根没有套接字
                            （SunnyNetCallback 里 8 个调用点传的都是字面量 0）。
                            不拦的话对着这种封包点一下，界面弹「设置失败」，
                            而这里已经把<b>原来设好的系统套接字抹成 0 了</b> —— 所有勾了
                            「使用系统套接字」的发送就此静默失效。

                            拦住之后 SystemSocket 只会 0 → 正数、不会退回去，
                            「勾着 + 未设置」这个状态从此不可达（发送编辑那个勾选框依赖这条）。
                        */
                        if (picked[0].PacketSocket <= 0)
                        {
                            return 0;
                        }

                        SystemConfig.SystemSocket = picked[0].PacketSocket;
                        return SystemConfig.SystemSocket;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SetSystemSocket_ByPacketId), ex);
                        return 0;
                    }
                }

                /// <summary>
                /// 「导出到 Excel」。<b>Ids 为空时导整张表</b> ——
                /// 这不是这里的特例，SavePacketListToExcel 本来就是这么写的
                /// （piList 为空则退回 lstPacketInfo），所以「什么都不选 = 导全部」。
                /// </summary>
                public static async Task ExportPacketExcel_ByIds(IList<long> Ids)
                {
                    try
                    {
                        await PacketConfig.List.SavePacketList_Dialog(
                            PacketConfig.Packet.InjectProcess,
                            PacketConfig.List.PickPackets(Ids));
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ExportPacketExcel_ByIds), ex);
                    }
                }

                #endregion

                #region//查找封包 - 外壳入口

                /// <summary>
                /// 从 <paramref name="FromIndex"/> 起按正则扫<b>注入模式</b>的封包列表，返回第一条命中的行。
                ///
                /// 与 <c>ProxyConfig.List.SearchProxy_Shell</c> 逐句对应，只差最后取哪张表
                /// —— <c>SearchForList</c> 的 <c>isPacketList</c> 参数就是为这件事留的。
                /// 出参只有基础类型；游标（「查找下一个」从第几行接着找）留在前端，
                /// C# 侧不碰 <c>Search_Index</c>：那是「谁在翻页谁的状态」。
                /// </summary>
                public static PacketSearchHit SearchPacket_Shell(string Pattern, bool IsHex, int FromIndex, int FromPos)
                {
                    var hit = new PacketSearchHit { Found = false, Id = 0, Index = -1, Offset = -1, Length = 0, NextPos = 0, Error = null };

                    try
                    {
                        if (string.IsNullOrEmpty(Pattern))
                        {
                            return hit;
                        }

                        /*
                            先自己把「写错了」和「没找到」分开 —— SearchForList 内部把异常吞成 -1，
                            两者长得一模一样。

                            ⚠️ 十六进制那一路的正则跑在<b>去掉空白之后</b>的串上（干草堆是连续的
                            十六进制，用户敲的 "0A 1B 2C" 里那两个空格匹配不到任何东西），
                            所以这里也要拿同一份串去校验，否则会出现「校验过了、搜的却是另一个串」。
                        */
                        string probe = IsHex ? Regex.Replace(Pattern, @"\s+", string.Empty) : Pattern;

                        if (probe.Length == 0)
                        {
                            return hit;
                        }

                        try
                        {
                            new Regex(probe);
                        }
                        catch (ArgumentException ex)
                        {
                            hit.Error = ex.Message;
                            return hit;
                        }

                        /*
                            纯十六进制却是奇数位（"0A1"）：一个字节两位，这种写法只可能命中半个字节，
                            而字节边界那道检查会把它全挡掉 —— 表现就是「明明有却报没找到」。
                            直接说清楚，别让用户去猜。（掺了别的字符就当正则，不管。）
                        */
                        if (IsHex && (probe.Length % 2) != 0 && Regex.IsMatch(probe, @"^[0-9A-Fa-f]+$"))
                        {
                            hit.Error = UI.T("SearchPacketForm.HexOdd", "十六进制位数必须是偶数：一个字节两位（如 0A1B2C）");
                            return hit;
                        }

                        if (FromIndex < 0)
                        {
                            FromIndex = 0;
                        }

                        //三样与 WinForms 的 SearchPacket.bSearch_Click 逐句一致
                        PacketConfig.List.FindOptions.Type = IsHex ? FindType.Hex : FindType.Text;
                        PacketConfig.List.FindRegex = Pattern;
                        PacketConfig.List.FindOptions.IsValid = true;

                        int index = PacketConfig.List.SearchForList<PacketInfo>(FromIndex, true, FromPos);

                        if (index < 0 || index >= lstPacketInfo.Count)
                        {
                            return hit;
                        }

                        PacketInfo pi = lstPacketInfo[index];
                        if (pi == null)
                        {
                            return hit;
                        }

                        hit.Found = true;
                        hit.Id = pi.Id;
                        hit.Index = index;

                        /*
                            偏移与「下一处从哪儿接着找」都由 SearchForList 算好，这里只是搬运。

                            ⚠️ <b>不要</b>在这儿拿命中的内容回缓冲里再找一次：同一段东西在一个包里
                            完全可能出现好几处，那样圈出来的永远是<b>第一处</b> —— 而「查找下一个」
                            走到第二处时，圈的还是第一处。
                        */
                        hit.NextPos = PacketConfig.List.FindNextPos;

                        int off = PacketConfig.List.FindByteOffset;
                        int hitLen = IsHex
                            ? (PacketConfig.List.FindOptions.Hex == null ? 0 : PacketConfig.List.FindOptions.Hex.Length)
                            : SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.UTF8, PacketConfig.List.FindOptions.Text).Length;

                        if (off >= 0 && hitLen > 0)
                        {
                            hit.Offset = off;
                            hit.Length = hitLen;
                        }

                        return hit;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SearchPacket_Shell), ex);
                        return hit;
                    }
                }

                #endregion

                #region//封包入列表

                /// <summary>
                /// 把队列里的封包批量搬进列表（B9c 引入，取代原来「每拍 1 条」的 PacketToList）。
                ///
                /// 一拍最多处理 SystemConfig.FeedBatchMax 条<b>出队</b>（不是入列）——
                /// 这样即使绝大多数封包被过滤掉，单拍耗时也有上界。
                ///
                /// 线程切换按<b>整批</b>做一次，不再每条切一次。
                /// 刻意<b>不</b>关闭 BindingList 的 ListChanged：关掉再 ResetBindings 虽然更省 CPU，
                /// 但会丢掉表格的滚动位置与选中行，代价比省下的那点开销大。
                /// </summary>
                public static void FlushToFeed()
                {
                    try
                    {
                        List<PacketInfo> added = null;
                        bool stored = false;   //这一拍有没有往仓库里放东西
                        int drained = 0;

                        while (drained < SystemConfig.FeedBatchMax
                               && PacketConfig.Queue.cqPacketInfo.TryDequeue(out PacketInfo pi))
                        {
                            drained++;

                            /*
                                入仓库（与代理那份逐条对应，改一处就要改另一处）。

                                ⚠️⚠️ **这一段以前只有代理模式有**（`Enable_AutoStores` 全项目只在
                                `ProxyConfig.List.FlushToFeed` 判一次）—— 于是注入模式下
                                「自动入库」的总开关、规则表全都能开能填，<b>一条都不会命中</b>，
                                而界面上没有任何东西说明这件事。两套 UI 都受影响。

                                ⚠️ 位置在<b>过滤判断之前</b>：代理那份写的是「对每条出队数据都判一次，
                                与是否显示无关」，而下面紧接着就是 continue。放到后面会让
                                被「过滤设置」挡掉的封包不进仓库，两种模式就此分叉。
                            */
                            if (Operate.WareHouseConfig.WareHouse.Enable_AutoStores)
                            {
                                var packetBuffer = pi.PacketBuffer;
                                var autoStoresList = Operate.WareHouseConfig.List.lstAutoStoresInfo;

                                foreach (AutoStoresInfo asi in autoStoresList)
                                {
                                    if (asi.IsEnable)
                                    {
                                        bool IsMatch = Operate.FilterConfig.Filter.CheckPacket_IsMatch_AppointHeader(packetBuffer, asi.PacketHead);
                                        if (IsMatch)
                                        {
                                            WareHouseInfo whi = Operate.WareHouseConfig.WareHouse.GetWareHouse_ByGuid(asi.WID);
                                            if (whi != null)
                                            {
                                                Operate.WareHouseConfig.WareHouse.AddStores(whi.Stores, packetBuffer);
                                                stored = true;
                                            }
                                        }
                                    }
                                }
                            }

                            if (!PacketConfig.Packet.IsShowPacket_ByFilter(pi))
                            {
                                PacketConfig.Packet.FilterPacket_CNT++;
                                continue;
                            }

                            if (added == null) { added = new List<PacketInfo>(SystemConfig.FeedBatchMax); }
                            added.Add(pi);
                        }

                        if (added != null)
                        {
                            //整批只切一次线程
                            if (Operate.SystemConfig.InvokeAction != null)
                            {
                                Operate.SystemConfig.InvokeAction(() =>
                                {
                                    foreach (PacketInfo pi in added) { lstPacketInfo.Add(pi); }
                                });
                            }
                            else
                            {
                                foreach (PacketInfo pi in added) { lstPacketInfo.Add(pi); }
                            }

                            //只有桥接入时才付 DTO 转换的代价，纯 WinForms 运行时整段跳过
                            if (UI.Feed.NeedsRows)
                            {
                                object[] rows = new object[added.Count];
                                for (int i = 0; i < added.Count; i++) { rows[i] = PacketRow.From_(added[i]); }
                                UI.Feed.Append(FeedList.Packet, rows);
                            }
                        }

                        /*
                            自动入库改的是 WareHouseInfo.Stores 这份<b>嵌套</b>列表，FeedPump 没订阅它，
                            不标脏的话仓库列表「仓储数量」那一列会一直停在 0（代理那边真发生过）。
                            一拍只标一次，不按条标 —— MarkDirty 要进锁。
                        */
                        if (stored)
                        {
                            FeedPump.MarkDirty(FeedList.WareHouse);
                        }

                        /*
                            自动清理：<b>只留最近 N 条</b>（2026-09-07 从整表清空改的）。
                            与代理列表那一份逐条对应，改一处就要改另一处。
                        */
                        if (AutoClear)
                        {
                            //AutoClear_Value 是 decimal（NumericUpDown 那边留下的），这里要显式转
                            int keep = (int)AutoClear_Value;

                            if (lstPacketInfo.Count > keep)
                            {
                                SystemConfig.TrimOldest(lstPacketInfo, keep);
                                UI.Feed.Trim(FeedList.Packet, keep);
                            }

                            //队列也要有界 —— 原来靠整表清空时顺手清掉它，见 TrimQueue 的说明
                            SystemConfig.LogDropped("PacketQueue",
                                SystemConfig.TrimQueue(PacketConfig.Queue.cqPacketInfo, keep));
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FlushToFeed), ex);
                    }
                }

                #endregion

                #region//清除封包列表

                public static void ClearPacketList()
                {
                    try
                    {
                        if (Operate.SystemConfig.InvokeAction != null)
                        {
                            Operate.SystemConfig.InvokeAction(() =>
                            {
                                Operate.PacketConfig.List.lstPacketInfo.Clear();
                            });
                        }
                        else
                        {
                            Operate.PacketConfig.List.lstPacketInfo.Clear();
                        }                        
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ClearPacketList), ex);
                    }
                }

                #endregion

                #region //搜索封包列表

                /// <param name="fromPos">
                /// 在第 <paramref name="fromIndex"/> 行<b>之内</b>从哪儿接着找（上一次的
                /// <see cref="FindNextPos"/>）。只对这一行有效，往后的行一律从头开始。
                /// ⚠️ 参数放在最后、给了默认值 —— WinForms 那两个调用点按位置传的是
                /// <paramref name="isPacketList"/>，插在中间会把它们悄悄改掉。
                /// </param>
                public static int SearchForList<T>(int fromIndex, bool isPacketList = true, int fromPos = 0) where T : class
                {
                    int iResult = -1;

                    //⚠️ 先清掉上一轮的，不然这次没命中时调用方会读到上一次的偏移
                    Operate.PacketConfig.List.FindByteOffset = -1;
                    Operate.PacketConfig.List.FindNextPos = 0;

                    if (fromPos < 0)
                    {
                        fromPos = 0;
                    }

                    try
                    {
                        if (!Operate.PacketConfig.List.FindOptions.IsValid)
                        {
                            return -1;
                        }

                        if (fromIndex < 0)
                        {
                            return -1;
                        }

                        int listCount;
                        IList<T> listItems;

                        if (isPacketList)
                        {
                            listCount = PacketConfig.List.lstPacketInfo.Count;
                            listItems = PacketConfig.List.lstPacketInfo as IList<T>;
                        }
                        else
                        {
                            listCount = ProxyConfig.List.lstProxyInfo.Count;
                            listItems = ProxyConfig.List.lstProxyInfo as IList<T>;
                        }

                        if (listItems == null || listCount == 0 || fromIndex >= listCount)
                        {
                            return -1;
                        }

                        switch (PacketConfig.List.FindOptions.Type)
                        {
                            case FindType.Text:

                                Regex reText;
                                try
                                {
                                    reText = new Regex(PacketConfig.List.FindRegex);
                                }
                                catch
                                {
                                    // 正则表达式错误
                                    return -1;
                                }

                                for (int i = fromIndex; i < listCount; i++)
                                {
                                    ReadOnlySpan<byte> packetBuffer = GetPacketBuffer(listItems[i], isPacketList);
                                    string packetData = SystemConfig.BytesToString(PacketConfig.Packet.EncodingFormat.UTF8, packetBuffer);

                                    //只有起点那一行接着上次的位置往后找，后面的行都从头来
                                    int at = (i == fromIndex) ? Math.Min(fromPos, packetData.Length) : 0;

                                    Match mFind = reText.Match(packetData, at);

                                    //空匹配（"a*" 这种）不算命中：既圈不出东西，还会让游标停在原地打转
                                    if (!mFind.Success || mFind.Length == 0)
                                    {
                                        continue;
                                    }

                                    PacketConfig.List.FindOptions.Text = mFind.Value;
                                    PacketConfig.List.FindNextPos = mFind.Index + 1;

                                    /*
                                        字节偏移：文本模式只能<b>估</b>。

                                        不能拿字符下标当字节偏移（一个字符可能占好几个字节），也不能
                                        把整个前缀重新编码去数字节 —— 缓冲里的非法字节解码成了替换字符，
                                        再编码回去是三个字节，位置就飘了。

                                        做法是「把命中的那段文字重新编码成字节，回缓冲里找一次」，
                                        但<b>从 mFind.Index 这个下限往后找</b>：UTF8 里每个字符至少占一个字节，
                                        所以真实字节偏移一定 ≥ 字符下标。加了这个下限，同一段文字在一个包里
                                        出现好几次时才不会永远圈住第一处（这正是这次要修的毛病）。
                                        找不到就退回 −1，前端只选中行、不圈字节。
                                    */
                                    byte[] needle = SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.UTF8, mFind.Value);
                                    if (needle != null && needle.Length > 0 && mFind.Index < packetBuffer.Length)
                                    {
                                        int hit = packetBuffer.Slice(mFind.Index).IndexOf(new ReadOnlySpan<byte>(needle));
                                        if (hit >= 0)
                                        {
                                            PacketConfig.List.FindByteOffset = mFind.Index + hit;
                                        }
                                    }

                                    return i;
                                }

                                break;

                            case FindType.Hex:

                                /*
                                    ⚠️ 这一路 2026-09-08 重写过，改之前<b>常见的写法一个都搜不到</b>：

                                      · 干草堆当时是 ToHexString 出的<b>带空格</b>串（"00 0A 1B 2C"），
                                        而用户十有八九敲的是 "0A1B2C" —— 中间没有空格，永远匹配不上；
                                      · Regex.Match 默认<b>区分大小写</b>，而干草堆是大写，敲小写 "0a1b2c" 同样落空；
                                      · 就算侥幸命中，还可能命中在<b>半个字节</b>上：
                                        缓冲 F0 A1 B2 的十六进制文本里能匹配到 "0A1B"，
                                        那是两个字节的后一半接下一个字节的前一半，根本不是一段真的字节。
                                        当时的结果是「报了命中、可十六进制面板圈不出东西」。

                                    现在三件事一起解决：
                                      · 干草堆改成<b>不带分隔符</b>的连续大写十六进制（HexRunOf）；
                                      · 正则加 IgnoreCase，并把用户串里的<b>空白</b>去掉
                                        （只去空白：'-' 在 [0-9A-F] 这类字符组里是有意义的，不能顺手一起去）；
                                      · 只认<b>落在字节边界上</b>的匹配（起点与长度都是偶数），
                                        不合的就在同一个包里继续往后找 —— 所以用 NextMatch 而不是 Match。

                                    正则本身仍然全须全尾（"0A.{2}2C" 这种「中间一个任意字节」照样能写），
                                    只是不再有那三个静默失效的坑。
                                */
                                if (!string.IsNullOrEmpty(PacketConfig.List.FindRegex))
                                {
                                    string hexPattern = Regex.Replace(PacketConfig.List.FindRegex, @"\s+", string.Empty);
                                    if (hexPattern.Length == 0)
                                    {
                                        return -1;
                                    }

                                    Regex reHex;
                                    try
                                    {
                                        reHex = new Regex(hexPattern, RegexOptions.IgnoreCase);
                                    }
                                    catch
                                    {
                                        // 正则表达式错误
                                        return -1;
                                    }

                                    for (int i = fromIndex; i < listCount; i++)
                                    {
                                        ReadOnlySpan<byte> packetBuffer = GetPacketBuffer(listItems[i], isPacketList);
                                        string packetData = SystemConfig.HexRunOf(packetBuffer);

                                        //只有起点那一行接着上次的位置往后找，后面的行都从头来
                                        int at = (i == fromIndex) ? Math.Min(fromPos, packetData.Length) : 0;

                                        for (Match mFind = reHex.Match(packetData, at); mFind.Success; mFind = mFind.NextMatch())
                                        {
                                            //空匹配（比如 "A*"）会让 NextMatch 原地打转，直接跳过
                                            if (mFind.Length == 0)
                                            {
                                                break;
                                            }

                                            //⚠️ 必须落在字节边界上，否则拿到的是「半个字节接半个字节」
                                            if ((mFind.Index % 2) != 0 || (mFind.Length % 2) != 0)
                                            {
                                                continue;
                                            }

                                            byte[] bHex = SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.Hex, mFind.Value);
                                            if (bHex.Length == 0)
                                            {
                                                continue;
                                            }

                                            Operate.PacketConfig.List.FindOptions.Hex = bHex;
                                            Operate.PacketConfig.List.FindByteOffset = mFind.Index / 2;

                                            //往后挪<b>一个字节</b>（两个字符）：挪一个字符只会落在半字节上，白跑一趟边界检查
                                            Operate.PacketConfig.List.FindNextPos = mFind.Index + 2;
                                            return i;
                                        }
                                    }
                                }

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SearchForList), ex);
                    }

                    return iResult;
                }

                private static ReadOnlySpan<byte> GetPacketBuffer<T>(T item, bool isPacketList)
                {
                    if (isPacketList && item is PacketInfo packetInfo)
                    {
                        return packetInfo.PacketBuffer.AsSpan();
                    }
                    else if (!isPacketList && item is ProxyInfo proxyInfo)
                    {
                        return proxyInfo.PacketBuffer.AsSpan();
                    }

                    return ReadOnlySpan<byte>.Empty;
                }

                #endregion

                #region//封包列表统计

                public static DataTable StatisticalSocketList_ByPacketLen()
                {
                    DataTable dtReturn = new DataTable();
                    dtReturn.Columns.Add("PacketLength", typeof(int));
                    dtReturn.Columns.Add("Number", typeof(int));

                    try
                    {
                        Dictionary<int, int> packetLenCount = new Dictionary<int, int>();

                        foreach (PacketInfo packetInfo in lstPacketInfo)
                        {
                            int packetLen = packetInfo.PacketLen;

                            if (packetLenCount.ContainsKey(packetLen))
                            {
                                packetLenCount[packetLen]++;
                            }
                            else
                            {
                                packetLenCount.Add(packetLen, 1);
                            }
                        }

                        Dictionary<int, int> sortedByKeyAsc = SystemConfig.SortDictionaryByKey(packetLenCount, ascending: true);

                        foreach (KeyValuePair<int, int> kvp in sortedByKeyAsc)
                        {
                            DataRow row = dtReturn.NewRow();
                            row[0] = kvp.Key;
                            row[1] = kvp.Value;
                            dtReturn.Rows.Add(row);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(StatisticalSocketList_ByPacketLen), ex);
                    }

                    return dtReturn;
                }

                public static DataTable StatisticalSocketList_ByPacketSocket()
                {
                    DataTable dtReturn = new DataTable();
                    dtReturn.Columns.Add("PacketSocket", typeof(int));
                    dtReturn.Columns.Add("Number", typeof(int));

                    try
                    {
                        Dictionary<int, int> packetLenCount = new Dictionary<int, int>();

                        foreach (PacketInfo packetInfo in lstPacketInfo)
                        {
                            int packetLen = packetInfo.PacketSocket;

                            if (packetLenCount.ContainsKey(packetLen))
                            {
                                packetLenCount[packetLen]++;
                            }
                            else
                            {
                                packetLenCount.Add(packetLen, 1);
                            }
                        }

                        Dictionary<int, int> sortedByKeyAsc = SystemConfig.SortDictionaryByKey(packetLenCount, ascending: true);

                        foreach (KeyValuePair<int, int> kvp in sortedByKeyAsc)
                        {
                            DataRow row = dtReturn.NewRow();
                            row[0] = kvp.Key;
                            row[1] = kvp.Value;
                            dtReturn.Rows.Add(row);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(StatisticalSocketList_ByPacketSocket), ex);
                    }

                    return dtReturn;
                }                

                #endregion

                #region//发送封包列表中当前选中的封包

                public static void SendSocketList_BySelect()
                {
                    try
                    {
                        //【B-IPC 阶段 0】不再直读 piSelect：改造后封包列表在外壳，
                        //目标侧读的是随 Runtime 快照下推的那一份副本。
                        SelectedPacket sp = HookHost.Current.GetSelectedPacket();

                        if (sp != null)
                        {
                            Operate.PacketConfig.Packet.SendPacket(
                                sp.Socket, sp.PacketType, sp.PacketFrom, sp.PacketTo, sp.PacketBuffer);
