                public static bool AddFilter_ByPacketInfo(PacketInfo pi, byte[] bBuffer)
                {
                    try
                    {
                        if (pi != null)
                        {
                            if (bBuffer == null || bBuffer.Length == 0)
                            {
                                bBuffer = pi.PacketBuffer;
                            }

                            /*
                                默认名与 AddFilter_ByProxyInfo 同一个口径：<b>远端地址 + 封包长度</b>（如 101.227.22.133:443 [180]）。
                                原来取的是本程序的进程名 —— 封包编辑从发送集里「添加到滤镜」时一屏滤镜全叫 WPEHybrid，
                                与封包列表右键加出来的名字对不上。远端地址为空时才退回进程名。
                            */
                            string sTo = (pi.PacketTo ?? string.Empty).Trim();

                            if (sTo.Length == 0)
                            {
                                sTo = Process.GetCurrentProcess().ProcessName.Trim();
                            }

                            FilterConfig.Filter.AddFilter(
                                false,
                                Guid.NewGuid(),
                                sTo + " [" + bBuffer.Length + "]",
                                false,
                                string.Empty, 
                                false, 
                                string.Empty, 
                                false, 
                                string.Empty, 
                                false, 
                                string.Empty,
                                FilterConfig.Filter.FilterMode.Normal,
                                FilterConfig.Filter.FilterAction.Replace, 
                                false,
                                FilterExecuteType.None,
                                Guid.Empty,
                                FilterConfig.Filter.GetFilterFunction_ByPacketType(pi.PacketType),
                                FilterConfig.Filter.FilterStartFrom.Head, 
                                false, 
                                false, 
                                1, 
                                false, 
                                1, 
                                string.Empty, 
                                0, 
                                string.Empty,
                                string.Empty,
                                FilterConfig.Filter.GetFilterString_ByBytes(bBuffer), 
                                string.Empty);

                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddFilter_ByPacketInfo), ex);
                    }

                    return false;
                }

                public static bool AddFilter_ByProxyInfo(ProxyInfo pi, byte[] bBuffer)
                {
                    try
                    {
                        if (pi != null)
                        {
                            if (bBuffer == null || bBuffer.Length == 0)
                            {
                                bBuffer = pi.PacketBuffer;
                            }

                            Guid FID = Guid.NewGuid();
                            /*
                                滤镜名用<b>服务端地址 + 封包长度</b>，例如 "101.227.22.133:443 [180]"。

                                原来取的是 Process.GetCurrentProcess().ProcessName —— 那是<b>本程序</b>的名字
                                （代理模式下就是 WPEHybrid / WinsockPacketEditor），一屏滤镜全叫一个名，
                                看不出这条是从哪个连接抓来的。这个方法只服务于代理模式（收的是 ProxyInfo，
                                五个调用点全在代理那条路上），所以直接换掉，不必分支。

                                ProxyInfo 里这个字段叫 ServerAddr（不是 PacketInfo 的 PacketTo）。
                                理论上可能为空，那时退回原来的进程名，至少还有个长度。
                            */
                            string sTo = (pi.ServerAddr ?? string.Empty).Trim();

                            if (sTo.Length == 0)
                            {
                                sTo = Process.GetCurrentProcess().ProcessName.Trim();
                            }

                            string sFName = sTo + " [" + bBuffer.Length + "]";
                            PacketConfig.Packet.PacketType ptType = pi.PacketType;
                            FilterConfig.Filter.FilterMode FilterMode = FilterConfig.Filter.FilterMode.Normal;
                            FilterConfig.Filter.FilterAction FilterAction = FilterConfig.Filter.FilterAction.Replace;
                            FilterConfig.Filter.FilterFunction FilterFunction = FilterConfig.Filter.GetFilterFunction_ByPacketType(ptType);
                            FilterConfig.Filter.FilterStartFrom FilterStartFrom = FilterConfig.Filter.FilterStartFrom.Head;
                            string sFSearch = FilterConfig.Filter.GetFilterString_ByBytes(bBuffer);

                            FilterConfig.Filter.AddFilter(
                                false,
                                FID,
                                sFName,
                                false,
                                string.Empty,
                                false,
                                string.Empty,
                                false,
                                string.Empty,
                                false,
                                string.Empty,
                                FilterMode,
                                FilterAction,
                                false,
                                FilterExecuteType.None,
                                Guid.Empty,
                                FilterFunction,
                                FilterStartFrom,
                                false,
                                false,
                                1,
                                false,
                                1,
                                string.Empty,
                                0,
                                string.Empty,
                                string.Empty,
                                sFSearch,
                                string.Empty);

                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddFilter_ByProxyInfo), ex);
                    }

                    return false;
                }

                public static void AddFilter(
                    bool IsEnable,
                    Guid FID,
                    string FName,
                    bool bAppointHeader,
                    string HeaderContent,
                    bool bAppointSocket,
                    string SocketContent,
                    bool bAppointLength,
                    string LengthContent,
                    bool bAppointPort,
                    string PortContent,
                    FilterConfig.Filter.FilterMode FilterMode,
                    FilterConfig.Filter.FilterAction FilterAction,
                    bool IsExecute,
                    Operate.FilterConfig.Filter.FilterExecuteType FEType,
                    Guid Execute_GUID,
                    FilterConfig.Filter.FilterFunction FilterFunction,
                    FilterConfig.Filter.FilterStartFrom FilterStartFrom,
                    bool IsProgressionDone,
                    bool IsProgressionContinuous,
                    int ProgressionStep,
                    bool IsProgressionCarry,
                    int ProgressionCarryNumber,
                    string ProgressionPosition,
                    int ProgressionCount,
                    string ExcludePosition,
                    string RandomPosition,
                    string FSearch,
                    string FModify)
                {
                    try
