                #region//检查滤镜是否生效

                public static bool CheckFilter_IsEffective(
                    Int32 iSocket,
                    Span<byte> bufferSpan,
                    PacketConfig.Packet.PacketType ptType,
                    PacketConfig.Packet.SockAddr sAddr,
                    FilterInfo sfi)
                {
                    if (!sfi.IsEnable)
                        return false;

                    if (!FilterConfig.Filter.CheckFilterFunction_ByPacketType(ptType, sfi.FFunction))
                        return false;

                    if (sfi.AppointSocket && !FilterConfig.Filter.CheckPacket_IsMatch_AppointSocket(iSocket, sfi.SocketContent))
                        return false;

                    if (sfi.AppointPort && !FilterConfig.Filter.CheckPacket_IsMatch_AppointPort(iSocket, ptType, sAddr, sfi.PortContent))
                        return false;

                    if (sfi.AppointLength && !FilterConfig.Filter.CheckPacket_IsMatch_AppointLength(bufferSpan.Length, sfi.LengthContent))
                        return false;

                    if (sfi.AppointHeader && !FilterConfig.Filter.CheckPacket_IsMatch_AppointHeader(bufferSpan, sfi.HeaderContent))
                        return false;

                    return true;
                }

                #endregion

                #region//检查封包类别

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                public static unsafe bool CheckFilterFunction_ByPacketType(PacketConfig.Packet.PacketType ptType, in FilterFunction ffFunction)
                {
                    fixed (bool* pFlags = &ffFunction.Send)
                    {
                        byte* indexMap = stackalloc byte[17]
                        {
                            0,   // WS1_Send -> Send (offset 0)
                            0,   // WS2_Send -> Send
                            1,   // WS1_SendTo -> SendTo
                            1,   // WS2_SendTo -> SendTo
                            2,   // WS1_Recv -> Recv
                            2,   // WS2_Recv -> Recv
                            3,   // WS1_RecvFrom -> RecvFrom
                            3,   // WS2_RecvFrom -> RecvFrom
                            4,   // WSASend -> WSASend
                            5,   // WSASendTo -> WSASendTo
                            6,   // WSARecv -> WSARecv
                            6,   // WSARecvEx -> WSARecv
                            7,   // WSARecvFrom -> WSARecvFrom
                            8,   // TCP_Req -> TCP_Req
                            9,   // UDP_Req -> UDP_Req
                            10,  // TCP_Resp -> TCP_Resp
                            11   // UDP_Resp -> UDP_Resp
                        };

                        int index = (int)ptType;
                        if (index >= 0 && index < 17)
                        {
                            return pFlags[indexMap[index]];
                        }
                    }
                    return false;
                }

                #endregion

                #region//检查是否匹配指定套接字

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                public static bool CheckPacket_IsMatch_AppointSocket(Int32 iSocket, string socketContent)
                {
                    if (string.IsNullOrEmpty(socketContent))
                        return false;

                    try
                    {
                        string[] parts = socketContent.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

                        foreach (string part in parts)
                        {
                            if (int.TryParse(part.Trim(), out int currentValue))
                            {
                                if (currentValue == iSocket)
                                {
                                    return true;
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckPacket_IsMatch_AppointSocket), ex);                        
                    }

                    return false;
                }

                #endregion

                #region//检查是否匹配指定长度

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                public static bool CheckPacket_IsMatch_AppointLength(int len, string lengthContent)
                {
                    if (string.IsNullOrEmpty(lengthContent))
                        return false;

                    try
                    {
                        string[] parts = lengthContent.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

                        foreach (string part in parts)
                        {
                            string trimmedPart = part.Trim();
                            int dashIndex = trimmedPart.IndexOf('-');

                            if (dashIndex >= 0)
                            {
                                string fromStr = trimmedPart.Substring(0, dashIndex).Trim();
                                string toStr = trimmedPart.Substring(dashIndex + 1).Trim();

                                if (int.TryParse(fromStr, out int lenFrom) &&
                                    int.TryParse(toStr, out int lenTo) &&
                                    len >= lenFrom &&
                                    len <= lenTo)
                                {
                                    return true;
                                }
                            }
                            else
                            {
                                if (int.TryParse(trimmedPart, out int exactLen) && len == exactLen)
                                {
                                    return true;
                                }
                            }
                        }

                        return false;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckPacket_IsMatch_AppointLength), ex);
                        return false;
                    }
                }

                #endregion

                #region//检查是否匹配指定端口

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static bool CheckPacket_IsMatch_AppointPort(
                    int iSocket,
                    PacketConfig.Packet.PacketType ptType,
                    PacketConfig.Packet.SockAddr sAddr,
                    string portContent)
                {
                    if (string.IsNullOrEmpty(portContent))
                        return false;

                    try
                    {
                        string packetIP = PacketConfig.Packet.GetIPString_BySocketAddr(iSocket, sAddr, ptType);
                        string[] ipPortPairs = packetIP.Split('|');
                        string[] portConditions = portContent.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

                        foreach (string ipPortPair in ipPortPairs)
                        {
                            if (FilterConfig.Filter.TryParsePort(ipPortPair, out int actualPort) && actualPort != -1)
                            {
                                foreach (string condition in portConditions)
                                {
                                    if (FilterConfig.Filter.CheckPortMatch(condition.Trim(), actualPort))
                                    {
                                        return true;
                                    }                                        
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckPacket_IsMatch_AppointPort), ex);                        
                    }

                    return false;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool TryParsePort(string ipPortPart, out int port)
                {
                    port = -1;

                    int colonIndex = ipPortPart.LastIndexOf(':');
                    if (colonIndex > 0 && colonIndex < ipPortPart.Length - 1)
                    {
                        string portStr = ipPortPart.Substring(colonIndex + 1);
                        return int.TryParse(portStr, out port);
                    }

                    return false;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool CheckPortMatch(string portContent, int actualPort)
                {
                    string[] parts = portContent.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

                    foreach (string part in parts)
                    {
                        string trimmedPart = part.Trim();

                        int dashIndex = trimmedPart.IndexOf('-');
                        if (dashIndex > 0)
                        {
                            string fromStr = trimmedPart.Substring(0, dashIndex).Trim();
                            string toStr = trimmedPart.Substring(dashIndex + 1).Trim();

                            if (int.TryParse(fromStr, out int minPort) &&
                                int.TryParse(toStr, out int maxPort) &&
                                actualPort >= minPort && actualPort <= maxPort)
                            {
                                return true;
                            }
                            continue;
                        }

                        if (int.TryParse(trimmedPart, out int port) && actualPort == port)
                        {
                            return true;
                        }
                    }

                    return false;
                }

                #endregion

                #region//检查是否匹配指定包头

                /*
                    包头字符串 → 字节 的缓存。

                    ⚠️ <b>这个方法在两条「每条封包都要走」的路上</b>：
                      · 滤镜：DoFilterList 里对每条封包 × 每条带「指定包头」的滤镜跑一次
                        —— 那是<b>钩子线程</b>，抓包的真热路径；
                      · 自动入库：搬运拍里对每条出队封包 × 每条启用规则跑一次。

                    而 headerContent 是<b>常量</b>（规则里填好就不动了），原来每次调用都把它
                    重新解析成字节 —— 实测约 <b>4µs/次</b>（含反射开销，真实值更低）。
                    3000 包/秒 × 几条规则就是每秒上万次重复解析。

                    <b>键就是那个字符串本身，所以不需要任何失效逻辑</b> —— 改了包头就是另一个键，
                    旧键留着也只是一条几十字节的死条目。这一点比「把解析结果挂在
                    AutoStoresInfo / FilterInfo 上」省事得多：那样每个 setter 都要记得作废，
                    漏一处就是「改了包头还按旧的匹配」，而且不报错。

                    上限只是防呆（正常就几条规则）；撑爆了整个清掉重来，下次调用重新填。

                    ConcurrentDictionary：钩子线程与 UI 线程会同时进来。
                */
                private static readonly ConcurrentDictionary<string, byte[]> headerBytesCache =
                    new ConcurrentDictionary<string, byte[]>(StringComparer.Ordinal);

                private const int HeaderCacheMax = 512;

                private static readonly byte[] emptyHeader = new byte[0];

                /// <summary>
                /// 取包头的字节形式，解析过一次就记住。
                ///
                /// 解析失败也<b>照样记住（记成空）</b>：包头填错时原来是每条封包记一条日志，
                /// 抓包时那是每秒上千条 —— 现在只有第一次会记。
                /// </summary>
                private static byte[] HeaderBytes(string HeaderContent)
                {
                    byte[] cached;

                    if (headerBytesCache.TryGetValue(HeaderContent, out cached)) { return cached; }

                    byte[] parsed;

                    try
                    {
                        parsed = SystemConfig.StringToBytes(
                            PacketConfig.Packet.EncodingFormat.Hex,
                            HeaderContent) ?? emptyHeader;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(HeaderBytes), ex);
                        parsed = emptyHeader;
                    }

                    if (headerBytesCache.Count >= HeaderCacheMax) { headerBytesCache.Clear(); }

                    headerBytesCache[HeaderContent] = parsed;

                    return parsed;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static bool CheckPacket_IsMatch_AppointHeader(ReadOnlySpan<byte> bufferSpan, string headerContent)
                {
                    if (string.IsNullOrEmpty(headerContent))
                        return false;

                    byte[] headerBytes = HeaderBytes(headerContent);

                    if (headerBytes.Length > 0 && headerBytes.Length <= bufferSpan.Length)
                    {
                        return bufferSpan.Slice(0, headerBytes.Length).SequenceEqual(headerBytes);
                    }

                    return false;
                }

                #endregion

                #region//检查滤镜辅助方法

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static HashSet<int> ParseExcludePositions(string excludeString)
                {
                    var positions = new HashSet<int>();

                    if (string.IsNullOrEmpty(excludeString))
                        return positions;

                    try
                    {
                        var excludeParts = excludeString.AsSpan();

                        while (!excludeParts.IsEmpty)
                        {
                            int commaIndex = excludeParts.IndexOf(',');
                            ReadOnlySpan<char> partSpan = commaIndex >= 0
                                ? excludeParts.Slice(0, commaIndex)
                                : excludeParts;

                            excludeParts = commaIndex >= 0
                                ? excludeParts.Slice(commaIndex + 1)
                                : ReadOnlySpan<char>.Empty;

                            if (partSpan.IsEmpty || partSpan.IsWhiteSpace())
                                continue;

                            var positionSpan = partSpan.Trim();
                            if (TryParseNonNegativeInt(positionSpan, out int position))
                            {
                                positions.Add(position);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ParseExcludePositions), ex);
                    }

                    return positions;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool HexCharsWithWildcardToByte(ReadOnlySpan<char> s, out byte result, out byte mask)
                {
                    result = 0;
                    mask = 0;

                    if (s.Length != 2)
                        return false;

                    if (s[0] == '*')
                    {
                        mask &= 0x0F;
                    }
                    else
                    {
                        int high = CharToNibble(s[0]);
                        if (high == -1) return false;
                        result |= (byte)(high << 4);
                        mask |= 0xF0;
                    }

                    if (s[1] == '*')
                    {
                        mask &= 0xF0;
                    }
                    else
                    {
                        int low = CharToNibble(s[1]);
                        if (low == -1) return false;
                        result |= (byte)low;
                        mask |= 0x0F;
                    }

                    return true;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool TryParseNonNegativeInt(ReadOnlySpan<char> s, out int result)
                {
                    result = 0;
                    if (s.IsEmpty) return false;

                    foreach (char c in s)
                    {
                        if (c < '0' || c > '9')
                            return false;
                        result = result * 10 + (c - '0');
                    }
                    return true;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static int CharToNibble(char c)
                {
                    uint digit = (uint)(c - '0');
                    if (digit < 10) return (int)digit;

                    uint lower = (uint)(c - 'a');
                    if (lower < 6) return (int)(10 + lower);

                    uint upper = (uint)(c - 'A');
                    if (upper < 6) return (int)(10 + upper);

                    return -1;
                }

                #endregion

                #region //检查滤镜是否匹配成功（普通滤镜）

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static bool CheckFilter_IsMatch_Normal(FilterInfo sfi, ReadOnlySpan<byte> bufferSpan)
                {
                    if (string.IsNullOrEmpty(sfi.FSearch) || bufferSpan.IsEmpty)
                        return false;

                    try
                    {
                        HashSet<int> excludePositions = null;
                        if (!string.IsNullOrEmpty(sfi.ExcludePosition))
                        {
                            excludePositions = ParseExcludePositions(sfi.ExcludePosition);
                        }

                        var searchParts = sfi.FSearch.AsSpan();

                        while (!searchParts.IsEmpty)
                        {
                            int commaIndex = searchParts.IndexOf(',');
                            ReadOnlySpan<char> partSpan = commaIndex >= 0
                                ? searchParts.Slice(0, commaIndex)
                                : searchParts;

                            searchParts = commaIndex >= 0
                                ? searchParts.Slice(commaIndex + 1)
                                : ReadOnlySpan<char>.Empty;

                            if (partSpan.IsEmpty || partSpan.IsWhiteSpace())
                                continue;

                            int pipeIndex = partSpan.IndexOf('|');
                            if (pipeIndex <= 0 || pipeIndex >= partSpan.Length - 1)
                                return false;

                            var indexSpan = partSpan.Slice(0, pipeIndex).Trim();
                            if (!TryParseNonNegativeInt(indexSpan, out int index) ||
                                index >= bufferSpan.Length)
                            {
                                return false;
                            }

                            var hexSpan = partSpan.Slice(pipeIndex + 1).Trim();
                            if (!HexCharsWithWildcardToByte(hexSpan, out byte expected, out byte mask))
                                return false;

                            bool isExcludePosition = excludePositions != null && excludePositions.Contains(index);

                            if (isExcludePosition)
                            {
                                byte actualValue = bufferSpan[index];
                                if ((actualValue & mask) == (expected & mask))
                                {
                                    return false;
                                }
                            }
                            else
                            {
                                if ((bufferSpan[index] & mask) != (expected & mask))
                                {
                                    return false;
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckFilter_IsMatch_Normal), ex);
                        return false;
                    }

                    return true;
                }

                #endregion

                #region//检查滤镜是否匹配成功（高级滤镜）

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static List<int> CheckFilter_IsMatch_Advanced(FilterInfo sfi, ReadOnlySpan<byte> bufferSpan)
                {
                    var result = new List<int>();
                    if (string.IsNullOrEmpty(sfi.FSearch))
                        return result;

                    try
                    {
                        HashSet<int> excludePositions = null;
                        if (!string.IsNullOrEmpty(sfi.ExcludePosition))
                        {
                            excludePositions = ParseExcludePositions(sfi.ExcludePosition);
                        }

                        var searchConditions = ParseSearchConditions(sfi.FSearch);
                        if (searchConditions.Count == 0)
                            return result;

                        var firstCondition = searchConditions[0];
                        byte firstValue = firstCondition.Value;
                        int relativePosition = firstCondition.RelativePosition;

                        for (int i = 0; i < bufferSpan.Length; i++)
                        {
                            if (bufferSpan[i] == firstValue)
                            {
                                bool isMatch = true;
                                int lastCheckedIndex = i;

                                for (int j = 1; j < searchConditions.Count; j++)
                                {
                                    var condition = searchConditions[j];
                                    int checkIndex = i + condition.RelativePosition - relativePosition;

                                    if (checkIndex < 0 || checkIndex >= bufferSpan.Length)
                                    {
                                        isMatch = false;
                                        break;
                                    }

                                    bool isExcludePosition = excludePositions != null && excludePositions.Contains(condition.RelativePosition);

                                    if (isExcludePosition)
                                    {
                                        byte actualByte = bufferSpan[checkIndex];
                                        if ((actualByte & condition.Mask) == (condition.Value & condition.Mask))
                                        {
                                            isMatch = false;
                                            break;
                                        }
                                    }
                                    else
                                    {
                                        if (condition.IsPartialWildcard)
                                        {
                                            byte actualByte = bufferSpan[checkIndex];
                                            if ((actualByte & condition.Mask) != (condition.Value & condition.Mask))
                                            {
                                                isMatch = false;
                                                break;
                                            }
                                        }
                                        else
                                        {
                                            if (bufferSpan[checkIndex] != condition.Value)
                                            {
                                                isMatch = false;
                                                break;
                                            }
                                        }
                                    }

                                    lastCheckedIndex = Math.Max(lastCheckedIndex, checkIndex);
                                }

                                if (isMatch)
                                {
                                    result.Add(i);

                                    if (sfi.FStartFrom == FilterConfig.Filter.FilterStartFrom.Head)
                                    {
                                        break;
                                    }

                                    i = lastCheckedIndex;
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CheckFilter_IsMatch_Advanced), ex);
                    }

                    return result;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static List<SearchCondition> ParseSearchConditions(string searchPattern)
                {
                    var conditions = new List<SearchCondition>();
                    string[] parts = searchPattern.Split(',');

                    foreach (string part in parts)
                    {
                        if (string.IsNullOrEmpty(part))
                            continue;

                        string[] pair = part.Split('|');
                        if (pair.Length != 2)
                            continue;

                        if (int.TryParse(pair[0], out int position))
                        {
                            string hexValue = pair[1].Trim();

                            if (hexValue.Contains('*'))
                            {
                                if (hexValue.Length == 2 && (hexValue[0] == '*' || hexValue[1] == '*'))
                                {
                                    if (HexCharsWithWildcardToByte(hexValue.AsSpan(), out byte value, out byte mask))
                                    {
                                        conditions.Add(new SearchCondition
                                        {
                                            RelativePosition = position,
                                            Value = value,
                                            Mask = mask,
                                            IsPartialWildcard = true
                                        });
                                    }
                                }
                            }
                            else
                            {
                                if (byte.TryParse(hexValue, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out byte value))
                                {
                                    conditions.Add(new SearchCondition
                                    {
                                        RelativePosition = position,
                                        Value = value,
                                        Mask = 0xFF,
                                        IsPartialWildcard = false
                                    });
                                }
                            }
                        }
                    }

                    conditions.Sort((a, b) => a.RelativePosition.CompareTo(b.RelativePosition));

                    return conditions;
                }

                #endregion

                #region//执行滤镜

                public static FilterConfig.Filter.FilterAction DoFilter(
                    FilterInfo fi,
                    Int32 iSocket,
                    Span<byte> bufferSpan,
                    out byte[] bNewBuffer,
                    PacketConfig.Packet.PacketType ptType,
                    PacketConfig.Packet.SockAddr sAddr)
                {
                    FilterConfig.Filter.FilterAction faReturn = FilterConfig.Filter.FilterAction.None;
                    bNewBuffer = null;

                    try
                    {
                        if (!FilterConfig.Filter.CheckFilter_IsEffective(iSocket, bufferSpan, ptType, sAddr, fi))
                        {
                            return faReturn;
                        }

                        bool bDoFilter = false;
                        bool isMatch = false;
                        List<int> MatchIndex = null;

                        if (fi.FMode == FilterConfig.Filter.FilterMode.Normal)
                        {
                            isMatch = FilterConfig.Filter.CheckFilter_IsMatch_Normal(fi, bufferSpan);
                        }
                        else if (fi.FMode == FilterConfig.Filter.FilterMode.Advanced)
                        {
                            MatchIndex = FilterConfig.Filter.CheckFilter_IsMatch_Advanced(fi, bufferSpan);
                            isMatch = MatchIndex != null && MatchIndex.Count > 0;
                        }

                        if (!isMatch)
                        {
                            return faReturn;
                        }

                        byte[] tempBuffer = null;

                        switch (fi.FAction)
                        {
                            case FilterConfig.Filter.FilterAction.Replace:

                                fi.IsProgressionDone = false;

                                if (fi.FMode == FilterConfig.Filter.FilterMode.Normal)
                                {
                                    bDoFilter = FilterConfig.Filter.Replace_Normal(fi, bufferSpan);
                                    if (bDoFilter)
                                    {
                                        tempBuffer = bufferSpan.ToArray();
                                    }
                                }
                                else if (fi.FMode == FilterConfig.Filter.FilterMode.Advanced && MatchIndex != null)
                                {
                                    foreach (int iIndex in MatchIndex)
                                    {
                                        bDoFilter = FilterConfig.Filter.Replace_Advanced(fi, iIndex, bufferSpan);
                                    }

                                    tempBuffer = bufferSpan.ToArray();
                                }

                                if (fi.IsProgressionDone && fi.IsProgressionContinuous)
                                {
                                    fi.ProgressionCount++;
                                }

                                break;

                            case FilterConfig.Filter.FilterAction.Change:

                                fi.IsProgressionDone = false;

                                tempBuffer = FilterConfig.Filter.ChangePacket_Filter(fi);
                                bDoFilter = tempBuffer != null && tempBuffer.Length > 0;

                                if (fi.IsProgressionDone && fi.IsProgressionContinuous)
                                {
                                    fi.ProgressionCount++;
                                }

                                break;

                            case FilterConfig.Filter.FilterAction.Intercept:
                            case FilterConfig.Filter.FilterAction.NoModify_Display:
                            case FilterConfig.Filter.FilterAction.NoModify_NoDisplay:
                                bDoFilter = true;
                                break;
                        }

                        if (fi.IsExecute && fi.Execute_GUID != null && fi.Execute_GUID != Guid.Empty)
                        {
                            switch (fi.FEType)
                            {
                                case FilterConfig.Filter.FilterExecuteType.Send:

                                    SendConfig.Send.DoSend(fi.Execute_GUID);

                                    break;

                                case FilterConfig.Filter.FilterExecuteType.Robot:

                                    Dictionary<string, object> parameters = new Dictionary<string, object>
                                    {
                                        { 
                                            "FilterSocket", 
                                            iSocket 
                                        }
                                    };

                                    RobotConfig.Robot.DoRobot(fi.Execute_GUID, parameters);

                                    break;

                                case FilterConfig.Filter.FilterExecuteType.Filter:

                                    FilterInfo fiExecute = FilterConfig.Filter.GetFilter_ByGuid(fi.Execute_GUID);
                                    FilterConfig.Filter.DoFilter(fiExecute, iSocket, bufferSpan, out bNewBuffer, ptType, sAddr);

                                    break;

                                case FilterConfig.Filter.FilterExecuteType.WareHouse:

                                    //【B-IPC 阶段 0】仓库查找与落库搬进 IHookHost 的实现里。
                                    //改造后目标进程不再持有仓库（仓库连同 SQLite 一起在外壳），
                                    //这里只把「哪个仓库 + 哪段字节」送出去。
                                    HookHost.Current.OnStore(
                                        fi.Execute_GUID,
                                        tempBuffer == null ? bufferSpan.ToArray() : tempBuffer);

                                    break;
                            }

                            bDoFilter = true;
                        }

                        if (bDoFilter)
                        {
                            faReturn = fi.FAction;
                            fi.ExecutionCount++;

                            switch (fi.FAction)
                            {
                                case Filter.FilterAction.Replace:
                                    Interlocked.Increment(ref FilterConfig.Filter.FilterReplace_CNT);
                                    break;

                                case Filter.FilterAction.Change:
                                    Interlocked.Increment(ref FilterConfig.Filter.FilterChange_CNT);
                                    break;

                                case Filter.FilterAction.Intercept:
                                    Interlocked.Increment(ref FilterConfig.Filter.FilterIntercept_CNT);
                                    break;

                                case Filter.FilterAction.NoModify_Display:
                                    Interlocked.Increment(ref FilterConfig.Filter.FilterDisplay_CNT);
                                    break;

                                case Filter.FilterAction.NoModify_NoDisplay:
                                    Interlocked.Increment(ref FilterConfig.Filter.FilterNoDisplay_CNT);
                                    break;
                            }

                            Interlocked.Increment(ref FilterConfig.Filter.FilterExecute_CNT);

                            if (tempBuffer != null)
                            {
                                bNewBuffer = tempBuffer;
                            }

                            if (!SystemConfig.SpeedMode)
                            {
                                if (MatchIndex != null && MatchIndex.Count > 0)
                                {
                                    DoFilterLog(fi.FName, fi.FAction, MatchIndex.Count, ptType, bufferSpan.Length);
                                }
                                else
                                {
                                    DoFilterLog(fi.FName, fi.FAction, 1, ptType, bufferSpan.Length);
                                }
                            }                            
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(DoFilter), ex);
                    }

                    return faReturn;
                }

                #endregion

                #region//执行滤镜 - SOCKS 代理模式

                public static void DoFilter_SOCKS_TCP(ProxySession psSession, Span<byte> bData, Operate.PacketConfig.Packet.PacketType ptType)
                {
                    try
                    {
                        Socket TargetSocket = null;

                        switch (ptType)
                        {
                            case Operate.PacketConfig.Packet.PacketType.TCP_Req:
                                TargetSocket = psSession.TargetSocket;
                                break;

                            case Operate.PacketConfig.Packet.PacketType.TCP_Resp:
                                TargetSocket = psSession.SocketSession.Client;
                                break;
                        }

                        if (TargetSocket == null || !TargetSocket.Connected)
                        {
                            return;
                        }

                        IPEndPoint epRemote = TargetSocket.RemoteEndPoint as IPEndPoint;
                        int SocketID = TargetSocket.Handle.ToInt32();

                        byte[] bRawBuffer = bData.ToArray();
                        byte[] bNewBuffer = null;

                        Operate.FilterConfig.Filter.FilterAction FilterAction =
                            Operate.FilterConfig.List.DoFilterList(
                                SocketID,
                                bData,
                                out bNewBuffer,
                                ptType,
                                new Operate.PacketConfig.Packet.SockAddr());

                        if (FilterAction != Operate.FilterConfig.Filter.FilterAction.Intercept)
                        {
                            switch (ptType)
                            {
                                case Operate.PacketConfig.Packet.PacketType.TCP_Req:
                                    psSession.TargetSocket.Send(bNewBuffer);
                                    break;

                                case Operate.PacketConfig.Packet.PacketType.TCP_Resp:
                                    psSession.TrySend(bNewBuffer, 0, bNewBuffer.Length);
                                    break;
                            }
                        }

                        _ = Operate.ProxyConfig.Queue.ProxyInfo_ToQueue(
                            DateTime.Now,
                            FilterAction,
                            bNewBuffer.Length,
                            SocketID,
                            0,
                            ptType,
                            0,
                            $"{psSession.ClientIP}:{psSession.ClientPort}",
                            $"{psSession.ServerIP}:{psSession.ServerPort}",
                            psSession.ServerAddress,
                            psSession.DomainType,
                            bRawBuffer,
                            bNewBuffer,
                            null);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(DoFilter_SOCKS_TCP), ex);
                    }
                }

                public static void DoFilter_SOCKS_UDP(ProxySession psSession, ProxyUDP pu, IPEndPoint epRemote, Span<byte> bData, Operate.PacketConfig.Packet.PacketType ptType)
                {
                    try
                    {
                        IPEndPoint epSend = null;
                        switch (ptType)
                        {
                            case Operate.PacketConfig.Packet.PacketType.UDP_Req:
                                epSend = epRemote;
                                break;

                            case Operate.PacketConfig.Packet.PacketType.UDP_Resp:
                                epSend = pu.ClientEndPoint;
                                break;
                        }

                        if (epSend == null || pu?.ClientSocket == null)
                        {
                            return;
                        }

                        int iSocket = pu.ClientSocket.Handle.ToInt32();

                        Int32 res = 0;
                        byte[] bRawBuffer = bData.ToArray();
                        byte[] bNewBuffer = null;

                        Operate.FilterConfig.Filter.FilterAction FilterAction =
                            Operate.FilterConfig.List.DoFilterList(
                                iSocket,
                                bData,
                                out bNewBuffer,
                                ptType,
                                new Operate.PacketConfig.Packet.SockAddr());

                        if (FilterAction != Operate.FilterConfig.Filter.FilterAction.Intercept)
                        {
                            res = psSession.SendUdpData(pu.ClientSocket, bNewBuffer, epSend);
                        }

                        string ClientAddr = $"{pu.ClientEndPoint.Address.ToString()}:{pu.ClientEndPoint.Port.ToString()}";
                        string ServerAddr = $"{epRemote.Address.ToString()}:{epRemote.Port.ToString()}";

                        _ = Operate.ProxyConfig.Queue.ProxyInfo_ToQueue(
                            DateTime.Now,
                            FilterAction,
                            res,
                            iSocket,
                            0,
                            ptType,
                            0,
                            ClientAddr,
                            ServerAddr,
                            ServerAddr,
                            Operate.ProxyConfig.Proxy.DomainType.External,
                            bRawBuffer,
                            bNewBuffer,
                            null);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(DoFilter_SOCKS_UDP), ex);
                    }
                }

                #endregion                

                #region//执行替换（普通滤镜）

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static bool Replace_Normal(FilterInfo fi, Span<byte> bufferSpan)
                {
                    if (string.IsNullOrEmpty(fi.FSearch))
                        return false;

                    bool hasModifications = !string.IsNullOrEmpty(fi.FModify);
                    bool hasProgressions = !string.IsNullOrEmpty(fi.ProgressionPosition);
                    bool hasRandoms = !string.IsNullOrEmpty(fi.RandomPosition);

                    if (!hasModifications && !hasProgressions && !hasRandoms)
                    {
                        return false;
                    }                        

                    try
                    {
                        bool result = false;

                        if (hasModifications)
                        {
                            result |= FilterConfig.Filter.ProcessModifications(fi, bufferSpan);
                        }

                        if (hasProgressions)
                        {
                            result |= FilterConfig.Filter.ProcessProgressions(fi, bufferSpan);
                        }

                        if (hasRandoms)
                        {
                            result |= FilterConfig.Filter.ProcessRandoms(fi, bufferSpan);
                        }

                        return result;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(Replace_Normal), ex);
                        return false;
                    }
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessModifications(FilterInfo fi, Span<byte> bufferSpan)
                {
                    bool modified = false;
                    string[] modifications = fi.FModify.Split(',');

                    foreach (string modification in modifications)
                    {
                        if (string.IsNullOrEmpty(modification))
                            continue;

                        string[] parts = modification.Split('|');
                        if (parts.Length != 2)
                            continue;

                        if (int.TryParse(parts[0], out int index) &&
                            index >= 0 &&
                            index < bufferSpan.Length &&
                            byte.TryParse(parts[1], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out byte value))
                        {
                            bufferSpan[index] = value;
                            modified = true;
                        }
                    }

                    return modified;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessProgressions(FilterInfo fi, Span<byte> bufferSpan)
                {
                    bool modified = false;
                    int carryCount = 0;
                    int step = (int)fi.ProgressionStep;
                    string[] positions = fi.ProgressionPosition.Split(',');

                    foreach (string position in positions)
                    {
                        if (string.IsNullOrEmpty(position) ||
                            !int.TryParse(position, out int index) ||
                            index < 0 ||
                            index >= bufferSpan.Length)
                        {
                            continue;
                        }

                        byte currentValue = bufferSpan[index];
                        byte newValue = SystemConfig.GetStepByte(currentValue, step * (fi.ProgressionCount + 1), out carryCount);
                        bufferSpan[index] = newValue;
                        modified = true;
                        fi.IsProgressionDone = true;

                        if (fi.IsProgressionCarry && carryCount > 0)
                        {
                            for (int i = 0; i < fi.ProgressionCarryNumber; i++)
                            {
                                int prevIndex = index - (i + 1);
                                if (prevIndex < 0)
                                    break;

                                byte prevValue = bufferSpan[prevIndex];
                                prevValue = SystemConfig.GetStepByte(prevValue, carryCount, out carryCount);
                                bufferSpan[prevIndex] = prevValue;
                                modified = true;

                                if (carryCount == 0)
                                    break;
                            }
                        }
                    }

                    return modified;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessRandoms(FilterInfo fi, Span<byte> bufferSpan)
                {
                    bool modified = false;
                    string[] positions = fi.RandomPosition.Split(',');

                    foreach (string position in positions)
                    {
                        if (string.IsNullOrEmpty(position) ||
                            !int.TryParse(position, out int index) ||
                            index < 0 ||
                            index >= bufferSpan.Length)
                        {
                            continue;
                        }

                        byte newValue = SystemConfig.GetRandomHexByte(bufferSpan[index]);
                        bufferSpan[index] = newValue;

                        modified = true;
                    }

                    return modified;
                }

                #endregion

                #region//执行替换（高级滤镜）

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                public static bool Replace_Advanced(FilterInfo fi, int matchIndex, Span<byte> bufferSpan)
                {
                    if (string.IsNullOrEmpty(fi.FSearch))
                        return false;

                    bool hasModifications = !string.IsNullOrEmpty(fi.FModify);
                    bool hasProgressions = !string.IsNullOrEmpty(fi.ProgressionPosition);
                    bool hasRandoms = !string.IsNullOrEmpty(fi.RandomPosition);

                    if (!hasModifications && !hasProgressions && !hasRandoms)
                    {
                        return false;
                    }

                    try
                    {
                        bool result = false;
                        var startFrom = fi.FStartFrom;

                        if (hasModifications)
                        {
                            result |= FilterConfig.Filter.ProcessAdvancedModifications(fi, matchIndex, bufferSpan, startFrom);
                        }

                        if (hasProgressions)
                        {
                            result |= FilterConfig.Filter.ProcessAdvancedProgressions(fi, matchIndex, bufferSpan, startFrom);
                        }

                        if (hasRandoms)
                        {
                            result |= FilterConfig.Filter.ProcessAdvancedRandoms(fi, matchIndex, bufferSpan, startFrom);
                        }

                        return result;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(Replace_Advanced), ex);
                        return false;
                    }
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessAdvancedModifications(
                    FilterInfo fi,
                    int matchIndex,
                    Span<byte> bufferSpan,
                    FilterConfig.Filter.FilterStartFrom startFrom)
                {
                    bool modified = false;
                    string[] modifications = fi.FModify.Split(',');

                    foreach (string modification in modifications)
                    {
                        if (string.IsNullOrEmpty(modification))
                            continue;

                        string[] parts = modification.Split('|');
                        if (parts.Length != 2)
                            continue;

                        if (!int.TryParse(parts[0], out int index))
                            continue;

                        if (startFrom == FilterConfig.Filter.FilterStartFrom.Position)
                        {
                            index += matchIndex;
                        }

                        if (index < 0 || index >= bufferSpan.Length)
                            continue;

                        if (byte.TryParse(parts[1], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out byte value))
                        {
                            /*
                                <b>写了就算命中，不比较新旧值是否相同。</b>

                                这里原本有一道 `if (bufferSpan[index] != value)` ——
                                改成同一个值时 modified 保持 false，于是 Replace_Advanced 返回 false、
                                DoFilter 返回 None，这条滤镜的执行次数不加、日志不记、统计不计，
                                在界面上看就是「滤镜启用了却完全没反应」。

                                它是六条改写路径里<b>唯一</b>带这道守卫的：
                                普通模式的 修改 / 递进 / 随机、高级模式的 递进 / 随机，
                                全都是写进去就置 modified —— 所以这不是设计，是它自己不一致。

                                语义上也该按「匹配成功」算：滤镜命不命中由查找条件决定，
                                跟改写后的字节碰巧等于原值没有关系。
                                「把这一位钉成 17」本来就是一次有效的改写，
                                只是这个包原来就是 17。
                            */
                            bufferSpan[index] = value;
                            modified = true;
                        }
                    }

                    return modified;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessAdvancedProgressions(
                    FilterInfo fi,
                    int matchIndex,
                    Span<byte> bufferSpan,
                    FilterConfig.Filter.FilterStartFrom startFrom)
                {
                    bool modified = false;
                    int carryCount = 0;
                    int step = (int)fi.ProgressionStep;
                    string[] positions = fi.ProgressionPosition.Split(',');

                    foreach (string position in positions)
                    {
                        if (string.IsNullOrEmpty(position) || !int.TryParse(position, out int index))
                            continue;

                        if (startFrom == FilterConfig.Filter.FilterStartFrom.Position)
                        {
                            index += matchIndex;
                        }

                        if (index < 0 || index >= bufferSpan.Length)
                            continue;

                        byte currentValue = bufferSpan[index];
                        byte newValue = SystemConfig.GetStepByte(currentValue, step * (fi.ProgressionCount + 1), out carryCount);
                        bufferSpan[index] = newValue;
                        modified = true;
                        fi.IsProgressionDone = true;

                        if (fi.IsProgressionCarry && carryCount > 0)
                        {
                            HandleCarryOver(fi, bufferSpan, index, ref carryCount);
                        }
                    }

                    return modified;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static bool ProcessAdvancedRandoms(
                    FilterInfo fi,
                    int matchIndex,
                    Span<byte> bufferSpan,
                    FilterConfig.Filter.FilterStartFrom startFrom)
                {
                    bool modified = false;
                    string[] positions = fi.RandomPosition.Split(',');

                    foreach (string position in positions)
                    {
                        if (string.IsNullOrEmpty(position) || !int.TryParse(position, out int index))
                            continue;

                        if (startFrom == FilterConfig.Filter.FilterStartFrom.Position)
                        {
                            index += matchIndex;
                        }

                        if (index < 0 || index >= bufferSpan.Length)
                            continue;

                        byte newValue = SystemConfig.GetRandomHexByte(bufferSpan[index]);
                        bufferSpan[index] = newValue;

                        modified = true;
                    }

                    return modified;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]

                private static void HandleCarryOver(FilterInfo fi, Span<byte> bufferSpan, int index, ref int carryCount)
                {
                    for (int i = 0; i < fi.ProgressionCarryNumber && carryCount > 0; i++)
                    {
                        int prevIndex = index - (i + 1);
                        if (prevIndex < 0)
                            break;

                        byte prevValue = bufferSpan[prevIndex];
                        prevValue = SystemConfig.GetStepByte(prevValue, carryCount, out carryCount);
                        bufferSpan[prevIndex] = prevValue;
                    }
                }

                #endregion

                #region//执行换包

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                public static byte[] ChangePacket_Filter(FilterInfo sfi)
                {
                    if (string.IsNullOrEmpty(sfi.FModify))
                    {
                        return Array.Empty<byte>();
                    }

                    try
                    {
                        var modifications = FilterConfig.Filter.ParseModifications(sfi.FModify);
                        if (modifications.Count == 0)
                            return Array.Empty<byte>();

                        byte[] newBuffer = new byte[modifications.Max(m => m.Index) + 1];
                        FilterConfig.Filter.ApplyModifications(newBuffer, modifications);

                        if (!string.IsNullOrEmpty(sfi.ProgressionPosition))
                        {
                            ApplyProgressions(sfi, newBuffer);
                        }

                        return newBuffer;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ChangePacket_Filter), ex);
                        return Array.Empty<byte>();
                    }
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                private static List<FilterConfig.Filter.Modification> ParseModifications(string modifyString)
                {
                    var modifications = new List<FilterConfig.Filter.Modification>();
                    string[] parts = modifyString.Split(',');

                    foreach (string part in parts)
                    {
                        if (string.IsNullOrEmpty(part))
                            continue;

                        string[] pair = part.Split('|');
                        if (pair.Length != 2)
                            continue;

                        if (int.TryParse(pair[0], out int index) &&
                            byte.TryParse(pair[1], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out byte value))
                        {
                            modifications.Add(new FilterConfig.Filter.Modification { Index = index, Value = value });
                        }
                    }

                    return modifications;
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                private static void ApplyModifications(byte[] buffer, List<FilterConfig.Filter.Modification> modifications)
                {
                    foreach (var mod in modifications)
                    {
                        if (mod.Index >= 0 && mod.Index < buffer.Length)
                        {
                            buffer[mod.Index] = mod.Value;
                        }
                    }
                }

                [MethodImpl(MethodImplOptions.AggressiveInlining)]
                private static void ApplyProgressions(FilterInfo sfi, byte[] buffer)
                {
                    int carryCount = 0;
                    int step = (int)sfi.ProgressionStep;
                    string[] positions = sfi.ProgressionPosition.Split(',');

                    foreach (string position in positions)
                    {
                        if (string.IsNullOrEmpty(position) ||
                            !int.TryParse(position, out int index) ||
                            index < 0 ||
                            index >= buffer.Length)
                        {
                            continue;
                        }

                        byte currentValue = buffer[index];
                        byte newValue = SystemConfig.GetStepByte(currentValue, step * (sfi.ProgressionCount + 1), out carryCount);
                        buffer[index] = newValue;
                        sfi.IsProgressionDone = true;

                        if (sfi.IsProgressionCarry && carryCount > 0)
                        {
                            for (int i = 0; i < sfi.ProgressionCarryNumber; i++)
                            {
                                int prevIndex = index - (i + 1);
                                if (prevIndex < 0)
                                    break;

                                byte prevValue = buffer[prevIndex];
                                prevValue = SystemConfig.GetStepByte(prevValue, carryCount, out carryCount);
                                buffer[prevIndex] = prevValue;

                                if (carryCount == 0)
                                    break;
                            }
                        }
                    }
                }

                #endregion

                #region//处理 Hook 结果（异步）

                public static Task ProcessingHookResultAsync(
                    int socket,
                    byte[] bRawBuffer,
                    byte[] bBuffer,
                    int res,
                    Operate.PacketConfig.Packet.PacketType ptType,
                    Operate.FilterConfig.Filter.FilterAction filterAction,
                    Operate.PacketConfig.Packet.SockAddr sockaddr,
                    DateTime packetTime)
                {
                    if (filterAction == Operate.FilterConfig.Filter.FilterAction.NoModify_NoDisplay)
                        return Task.CompletedTask;

                    if (filterAction != Operate.FilterConfig.Filter.FilterAction.Intercept && res <= 0)
                        return Task.CompletedTask;

                    return Task.Run(() =>
                    {
                        try
                        {
                            Operate.PacketConfig.Queue.PacketInfo_ToQueue(
                                socket, 
                                bRawBuffer, 
                                bBuffer,
                                PacketConfig.Packet.GetPacketData_Hex(bBuffer, PacketConfig.Packet.PacketData_MaxLen),
                                ptType, 
                                sockaddr, 
                                filterAction, 
                                packetTime);
                        }
                        catch (Exception ex)
                        {
                            Operate.DoLog(nameof(ProcessingHookResultAsync), ex);
                        }
                    });
                }

                #endregion
            }

            #endregion

            #region//滤镜列表

            public static class List
            {
                public static bool IsFilterListFormShow = false;
                public static BindingList<FilterInfo> lstFilterInfo = new BindingList<FilterInfo>();

                #region//滤镜入列表

                public static void FilterToList(FilterInfo fi)
                {
                    try
                    {
                        FilterConfig.List.lstFilterInfo.Add(fi);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FilterToList), ex);
                    }
                }

                #endregion

                #region//初始化滤镜列表的计数

                public static void InitFilterList_Count()
                {
                    try
                    {
                        foreach (FilterInfo sfi in lstFilterInfo)
                        {
                            sfi.ExecutionCount = 0;
                            sfi.ProgressionCount = 0;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(InitFilterList_Count), ex);
                    }
                }

                #endregion

                #region//清空滤镜列表（对话框）

                public static async Task CleanUpFilterList_Dialog()
                {
                    if (await UI.Confirm(UI.T("InjectModeForm.miFilterList", "滤镜列表"), UI.T("SureToDelete", "确定删除数据吗?")))
                    {
                        FilterConfig.List.FilterListClear();
                    }
                }

                public static void FilterListClear()
                {
                    try
                    {
                        lstFilterInfo.Clear();
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FilterListClear), ex);
                    }
                }

                #endregion

                #region//滤镜列表 - 只出基础类型的入口（给不引用 AntdUI 的外壳用）

                /*
                    `FilterInfo` 继承 AntdUI 的 `NotifyProperty`，一出现在外壳能看到的签名上
                    就是 CS0012（第 6 次撞上，前五次见 CLAUDE.md 的「维护提示」）。
                    所以这一组按 Id 字符串收发，只出基础类型与 FilterRow。

                    【⚠️ 顺序就是数据，别改成增量推送】
                    DoFilterList 是<b>按列表顺序</b>逐个执行滤镜的 —— 这正是
                    「置顶 / 上移 / 下移 / 置底」存在的理由。所以 FeedList.Filter
                    必须一直走整表 Replace（FeedPump 的默认），
                    绝不能照代理账号那样为了省字节改成增量：
                    账号漏一条只是少一行，滤镜漏一条是<b>执行顺序错了而且看不出来</b>。

                    【⚠️ 每个改动动作都要落库】
                    WinForms 靠 ProxyModeForm 关窗时统一 SaveSystemList_ToDB()，
                    外壳没有那个时机（也不该在关窗时补 —— 用户停在启动页就退出的话
                    这些列表还没加载，那一句会把库里的滤镜全删光）。
                    所以下面每个会改动列表的入口，末尾都调一次 SaveFilterList_ToDB()。
                    它是 delete-all + insert-all，几十行的表很便宜，而且天然保序。
                */

                /// <summary>按 Id 字符串找一个滤镜。这一组的公共前半段。</summary>
                private static FilterInfo FindFilter_ById(string FID)
                {
                    try
                    {
                        if (!string.IsNullOrEmpty(FID))
                        {
                            foreach (FilterInfo fi in FilterConfig.List.lstFilterInfo)
                            {
                                //FilterRow.From_ 推出去的是 ToUpper 后的串，这里不假设大小写
                                if (string.Equals(fi.FID.ToString(), FID, StringComparison.OrdinalIgnoreCase))
                                {
                                    return fi;
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FindFilter_ById), ex);
                    }

                    return null;
                }

                /// <summary>
                /// Id 数组 → 模型列表，<b>按列表里的先后顺序</b>返回。
                ///
                /// 顺序要紧：上移 / 下移是逐个做的，若按前端传来的顺序处理，
                /// 多选时会互相插队，动完的结果和用户看到的对不上。
                /// </summary>
                private static List<FilterInfo> PickFilters(IList<string> Ids)
                {
                    var picked = new List<FilterInfo>();

                    if (Ids == null || Ids.Count == 0)
                    {
                        return picked;
                    }

                    var want = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                    foreach (string id in Ids)
                    {
                        if (!string.IsNullOrEmpty(id)) { want.Add(id); }
                    }

                    foreach (FilterInfo fi in FilterConfig.List.lstFilterInfo)
                    {
                        if (want.Contains(fi.FID.ToString()))
                        {
                            picked.Add(fi);
                        }
                    }

                    return picked;
                }

                /// <summary>新建一个空滤镜（名字自动编号），返回它的 Id。</summary>
                public static string AddFilter_New_ById()
                {
                    int before = FilterConfig.List.lstFilterInfo.Count;

                    FilterConfig.Filter.AddFilter_New();

                    if (FilterConfig.List.lstFilterInfo.Count <= before)
                    {
                        return string.Empty;
                    }

                    FilterConfig.List.SaveFilterList_ToDB();

                    //AddFilter 是往后追加的，新的那条就在表尾
                    return FilterConfig.List.lstFilterInfo[FilterConfig.List.lstFilterInfo.Count - 1]
                        .FID.ToString().ToUpper();
                }

                /// <summary>只改启用状态。与账号那边一样，走这里才会落库。</summary>
                public static bool SetFilterEnable_ById(string FID, bool IsEnable)
                {
                    FilterInfo fi = FilterConfig.List.FindFilter_ById(FID);

                    if (fi == null)
                    {
                        return false;
                    }

                    fi.IsEnable = IsEnable;
                    FilterConfig.List.SaveFilterList_ToDB();

                    //就地改属性不触发 ListChanged，得自己让下一拍推出去
                    FeedPump.MarkDirty(FeedList.Filter);
                    return true;
                }

                /// <summary>全部启用 / 全部禁用（对应工具条上那两个按钮）。返回改了几条。</summary>
                public static int SetAllFilterEnable(bool IsEnable)
                {
                    int n = 0;

                    foreach (FilterInfo fi in FilterConfig.List.lstFilterInfo)
                    {
                        if (fi.IsEnable != IsEnable)
                        {
                            fi.IsEnable = IsEnable;
                            n++;
                        }
                    }

                    if (n > 0)
                    {
                        FilterConfig.List.SaveFilterList_ToDB();
                        FeedPump.MarkDirty(FeedList.Filter);
                    }

                    return n;
                }

                /// <summary>
                /// 重置执行次数（对应工具条的「重置计数」）。
                /// <b>不落库</b>：ExecutionCount / ProgressionCount 是运行期计数，
                /// 与 WinForms 一致，本来也不该进库。
                /// </summary>
                public static void ResetFilterCount()
                {
                    FilterConfig.List.InitFilterList_Count();
                    FeedPump.MarkDirty(FeedList.Filter);
                }

                /// <summary>
                /// 右键菜单的七个动作，按 Id 数组收。
                /// 动作编号照搬 <see cref="SystemConfig.ListAction"/>，
                /// 与发送 / 机器人 / 仓库三份列表共用同一套语义。
                /// </summary>
                public static async Task<int> FilterListAction_ByIds(int Action, IList<string> Ids)
                {
                    List<FilterInfo> picked = FilterConfig.List.PickFilters(Ids);

                    if (picked.Count == 0)
                    {
                        return 0;
                    }

                    int before = FilterConfig.List.lstFilterInfo.Count;

                    await FilterConfig.List.UpdateFilterList_ByListAction(
                        (SystemConfig.ListAction)Action, picked);

                    /*
                        导出只是写文件，不动列表，不必落库；其余六个都动了顺序或内容。
                        删除可能被确认框取消 —— 那时条数没变，但重存一遍也无害，
                        比在这里猜「用户点没点确定」可靠。
                    */
                    if ((SystemConfig.ListAction)Action != SystemConfig.ListAction.Export)
                    {
                        FilterConfig.List.SaveFilterList_ToDB();
                    }

                    return FilterConfig.List.lstFilterInfo.Count - before;
                }

                /// <summary>清空全部（带确认框）。</summary>
                public static async Task CleanUpFilterList_Dialog_Shell()
                {
                    int before = FilterConfig.List.lstFilterInfo.Count;

                    await FilterConfig.List.CleanUpFilterList_Dialog();

                    if (FilterConfig.List.lstFilterInfo.Count != before)
                    {
                        FilterConfig.List.SaveFilterList_ToDB();
                    }
                }

                /// <summary>导入滤镜列表（带文件框）。导进来之后要落库。</summary>
                public static async Task LoadFilterList_Dialog_Shell()
                {
                    int before = FilterConfig.List.lstFilterInfo.Count;

                    await FilterConfig.List.LoadFilterList_Dialog();

                    if (FilterConfig.List.lstFilterInfo.Count != before)
                    {
                        FilterConfig.List.SaveFilterList_ToDB();
                    }
                }

                /// <summary>导出全部滤镜（带文件框）。不改列表，不落库。</summary>
                public static async Task SaveAllFilters_Dialog()
                {
                    if (FilterConfig.List.lstFilterInfo.Count > 0)
                    {
                        await FilterConfig.List.SaveFilterList_Dialog(string.Empty, null);
                    }
                }

                #endregion

                #region//滤镜编辑 - 取一条 / 存一条（只出基础类型与 DTO）

                /*
                    滤镜的存储格式只有这一处知道，前端拿到的是解析好的格子数组。

                    源模型里是四串：
                      FSearch / FModify        "索引|十六进制值,索引|值,"
                      ExcludePosition          "索引,索引,"     查找位：这一位<b>不能</b>等于该值
                      ProgressionPosition      "索引,索引,"     修改位：每次命中后累加
                      RandomPosition           "索引,索引,"     修改位：每次命中随机取值

                    两边各写一份解析必然走岔（分隔符、尾逗号、越界索引），所以这一层只留在 C#。
                    库里只有 FSearch / FModify 两串，但<b>索引的含义随 Mode + FStartFrom 变</b>：
                    普通与「高级·包头」是绝对位置 0~999，「高级·指定位置」是相对匹配点的偏移
                    -1000~999。所以下面的解析一律不判非负，边界交给保存时的 lo 去卡。
                */

                /// <summary>解析 "索引|值,索引|值," 。坏的条目跳过，不让一处笔误毁掉整条滤镜。</summary>
                private static Dictionary<int, string> ParsePairs(string S)
                {
                    var map = new Dictionary<int, string>();

                    if (string.IsNullOrEmpty(S))
                    {
                        return map;
                    }

                    foreach (string part in S.Split(','))
                    {
                        if (string.IsNullOrEmpty(part))
                        {
                            continue;
                        }

                        string[] kv = part.Split('|');
                        int i;

                        /*
                            <b>不能判 i >= 0。</b>高级模式「修改起始于指定位置」时，
                            修改位的索引是相对匹配点的偏移，取值 -1000 ~ 999 ——
                            加个非负判断会把左边一千列悄悄丢掉，而且丢得毫无痕迹。
                        */
                        if (kv.Length >= 2 && int.TryParse(kv[0], out i))
                        {
                            map[i] = kv[1];
                        }
                    }

                    return map;
                }

                /// <summary>解析 "索引,索引," 。</summary>
                private static HashSet<int> ParseIndexes(string S)
                {
                    var set = new HashSet<int>();

                    if (string.IsNullOrEmpty(S))
                    {
                        return set;
                    }

                    foreach (string part in S.Split(','))
                    {
                        int i;

                        //同样不判非负，理由见 ParsePairs
                        if (!string.IsNullOrEmpty(part) && int.TryParse(part, out i))
                        {
                            set.Add(i);
                        }
                    }

                    return set;
                }

                /// <summary>
                /// 取一条滤镜的完整内容（含格子）。找不到返回 null。
                ///
                /// 只下发<b>有内容或有标记</b>的列 —— 格子有 1000 列（FilterSize_MaxLen），
                /// 而真实滤镜通常只用到前几个字节，整表下发是白费。
                /// </summary>
                /// <summary>
                /// 「执行」下拉的候选项：按类型出对应列表的 名称 + Id。
                ///
                /// <b>Type 收的是 FilterExecuteType 的枚举值，不是下拉框的下标。</b>
                /// 这两者对不上：枚举是 Send=0 Robot=1 <b>None=2</b> Filter=3 WareHouse=4，
                /// 而 WinForms 的下拉只摆四项（0 发送 1 机器人 2 滤镜 3 仓库），
                /// 中间跳过了 None。存进库的是枚举值，所以这里也认枚举值。
                ///
                /// 出 名称 + Id 两个基础类型而不是模型本身 —— SendInfo / RobotInfo /
                /// FilterInfo / WareHouseInfo 全都（当年）继承 AntdUI.NotifyProperty，
                /// 一出现在外壳能看到的签名上就是 CS0012。
                /// </summary>
                /// <param name="ExcludeFID">滤镜类型专用：要排除的滤镜（一条滤镜不能执行它自己）。</param>
                public static ExecuteTargetRow[] GetExecuteTargets(int Type, string ExcludeFID)
                {
                    var outv = new List<ExecuteTargetRow>();

                    try
                    {
                        switch ((FilterConfig.Filter.FilterExecuteType)Type)
                        {
                            case FilterConfig.Filter.FilterExecuteType.Send:

                                foreach (SendInfo x in SendConfig.List.lstSendInfo)
                                {
                                    outv.Add(new ExecuteTargetRow
                                    {
                                        Id = x.SID.ToString().ToUpper(),
                                        Name = x.SName,
                                    });
                                }

                                break;

                            case FilterConfig.Filter.FilterExecuteType.Robot:

                                foreach (RobotInfo x in RobotConfig.List.lstRobotInfo)
                                {
                                    outv.Add(new ExecuteTargetRow
                                    {
                                        Id = x.RID.ToString().ToUpper(),
                                        Name = x.RName,
                                    });
                                }

                                break;

                            case FilterConfig.Filter.FilterExecuteType.Filter:

                                Guid skip;

                                if (!Guid.TryParse(ExcludeFID ?? string.Empty, out skip))
                                {
                                    skip = Guid.Empty;
                                }

                                foreach (FilterInfo x in FilterConfig.List.lstFilterInfo)
                                {
                                    //一条滤镜执行它自己就是死循环，与 InitFilterInfo 的 ExcludeFID 同一个道理
                                    if (x.FID == skip) { continue; }

                                    outv.Add(new ExecuteTargetRow
                                    {
                                        Id = x.FID.ToString().ToUpper(),
                                        Name = x.FName,
                                    });
                                }

                                break;

                            case FilterConfig.Filter.FilterExecuteType.WareHouse:

                                foreach (WareHouseInfo x in WareHouseConfig.List.lstWareHouseInfo)
                                {
                                    outv.Add(new ExecuteTargetRow
                                    {
                                        Id = x.WID.ToString().ToUpper(),
                                        Name = x.WName,
                                    });
                                }

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetExecuteTargets), ex);
                    }

                    return outv.ToArray();
                }

                public static FilterEditRow GetFilterEdit_ById(string FID)
                {
                    try
                    {
                        FilterInfo fi = FilterConfig.List.FindFilter_ById(FID);

                        if (fi == null)
                        {
                            return null;
                        }

                        Dictionary<int, string> search = FilterConfig.List.ParsePairs(fi.FSearch);
                        Dictionary<int, string> modify = FilterConfig.List.ParsePairs(fi.FModify);
                        HashSet<int> exclude = FilterConfig.List.ParseIndexes(fi.ExcludePosition);
                        HashSet<int> progression = FilterConfig.List.ParseIndexes(fi.ProgressionPosition);
                        HashSet<int> random = FilterConfig.List.ParseIndexes(fi.RandomPosition);

                        /*
                            查找与修改<b>各自成表</b>，索引空间不共用 ——
                            高级模式下两者独立，修改位在「指定位置」时还可能是负偏移。
                            各自按列号排好，前端不必再排。
                        */
                        var sIdx = new SortedSet<int>();
                        foreach (int i in search.Keys) { sIdx.Add(i); }
                        foreach (int i in exclude) { sIdx.Add(i); }

                        var mIdx = new SortedSet<int>();
                        foreach (int i in modify.Keys) { mIdx.Add(i); }
                        foreach (int i in progression) { mIdx.Add(i); }
                        foreach (int i in random) { mIdx.Add(i); }

                        var sCells = new List<FilterSearchCell>();

                        foreach (int i in sIdx)
                        {
                            sCells.Add(new FilterSearchCell
                            {
                                Index = i,
                                Value = search.ContainsKey(i) ? search[i] : string.Empty,
                                Exclude = exclude.Contains(i),
                            });
                        }

                        var mCells = new List<FilterModifyCell>();

                        foreach (int i in mIdx)
                        {
                            mCells.Add(new FilterModifyCell
                            {
                                Index = i,
                                Value = modify.ContainsKey(i) ? modify[i] : string.Empty,
                                Progression = progression.Contains(i),
                                Random = random.Contains(i),
                            });
                        }

                        FilterRow head = FilterRow.From_(fi);

                        return new FilterEditRow
                        {
                            Id = head.Id,
                            Name = fi.FName,
                            Mode = (int)fi.FMode,
                            Action = (int)fi.FAction,
                            StartFrom = (int)fi.FStartFrom,
                            FunctionMask = head.FunctionMask,
                            AppointHeader = fi.AppointHeader,
                            HeaderContent = fi.HeaderContent,
                            AppointSocket = fi.AppointSocket,
                            SocketContent = fi.SocketContent,
                            AppointLength = fi.AppointLength,
                            LengthContent = fi.LengthContent,
                            AppointPort = fi.AppointPort,
                            PortContent = fi.PortContent,
                            IsExecute = fi.IsExecute,
                            ExecuteType = (int)fi.FEType,
                            ExecuteId = fi.Execute_GUID.ToString().ToUpper(),
                            IsProgressionContinuous = fi.IsProgressionContinuous,
                            ProgressionStep = fi.ProgressionStep,
                            IsProgressionCarry = fi.IsProgressionCarry,
                            ProgressionCarryNumber = fi.ProgressionCarryNumber,
                            Search = sCells.ToArray(),
                            Modify = mCells.ToArray(),
                        };
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetFilterEdit_ById), ex);
                        return null;
                    }
                }

                /// <summary>
                /// 存一条滤镜。返回空串表示成功，否则是给用户看的错误原因。
                ///
                /// <b>校验放在这里</b>，与 WinForms 的 CheckFilterIsValid 同一份规则 ——
                /// 前端再写一遍就有两套真相，而这是「能不能匹配上」的业务约束，不是界面细节。
                /// </summary>
                public static string SaveFilterEdit(FilterEditRow Row)
                {
                    try
                    {
                        if (Row == null)
                        {
                            return UI.T("FilterEditForm.FilterName.Empty", "请输入滤镜名称");
                        }

                        FilterInfo fi = FilterConfig.List.FindFilter_ById(Row.Id);

                        if (fi == null)
                        {
                            return UI.T("FilterEditForm.NotFound", "这条滤镜已经不在列表里了");
                        }

                        string name = (Row.Name ?? string.Empty).Trim();

                        if (name.Length == 0)
                        {
                            return UI.T("FilterEditForm.FilterName.Empty", "请输入滤镜名称");
                        }

                        //勾了「指定」却没填值 = 这条规则不成立，与过滤设置同一个道理
                        string bad = FilterConfig.List.CheckAppoint(Row);

                        if (bad != null)
                        {
                            return bad;
                        }

                        //换包要求修改行从头连续，见 CheckChange
                        bad = FilterConfig.List.CheckChange(Row);

                        if (bad != null)
                        {
                            return bad;
                        }

                        var search = new StringBuilder();
                        var modify = new StringBuilder();
                        var exclude = new StringBuilder();
                        var progression = new StringBuilder();
                        var random = new StringBuilder();

                        int max = FilterConfig.Filter.FilterSize_MaxLen;

                        //查找位永远是绝对位置，0 ~ 999
                        if (Row.Search != null)
                        {
                            foreach (FilterSearchCell c in Row.Search)
                            {
                                if (c == null || c.Index < 0 || c.Index >= max)
                                {
                                    continue;
                                }

                                string s = (c.Value ?? string.Empty).Trim();

                                if (s.Length > 0)
                                {
                                    search.Append(c.Index).Append("|").Append(s).Append(",");

                                    //排除是查找位的标记，没有查找值就无从排除
                                    if (c.Exclude) { exclude.Append(c.Index).Append(","); }
                                }
                            }
                        }

                        /*
                            修改位的下界随 StartFrom 变：
                              Head      绝对位置        0 ~ 999
                              Position  相对匹配点的偏移  -1000 ~ 999
                            <b>写死非负会把「指定位置」左边那一千列整个吞掉。</b>
                        */
                        bool offset = Row.Mode == (int)FilterConfig.Filter.FilterMode.Advanced
                            && Row.StartFrom == (int)FilterConfig.Filter.FilterStartFrom.Position;

                        int lo = offset ? -max : 0;

                        if (Row.Modify != null)
                        {
                            foreach (FilterModifyCell c in Row.Modify)
                            {
                                if (c == null || c.Index < lo || c.Index >= max)
                                {
                                    continue;
                                }

                                string m = (c.Value ?? string.Empty).Trim();

                                if (m.Length > 0)
                                {
                                    modify.Append(c.Index).Append("|").Append(m).Append(",");
                                }

                                /*
                                    递进 / 随机是修改位的标记。与 WinForms 一致：
                                    它们<b>不要求</b>该位有修改值 —— 随机位本来就不需要预设值。
                                    两者互斥，源模型里也是 else-if。
                                */
                                if (c.Progression) { progression.Append(c.Index).Append(","); }
                                else if (c.Random) { random.Append(c.Index).Append(","); }
                            }
                        }

                        fi.FName = name;
                        fi.FMode = (FilterConfig.Filter.FilterMode)Row.Mode;
                        fi.FAction = (FilterConfig.Filter.FilterAction)Row.Action;
                        fi.FStartFrom = (FilterConfig.Filter.FilterStartFrom)Row.StartFrom;
                        fi.FFunction = FilterConfig.List.MaskToFunction(Row.FunctionMask);

                        fi.AppointHeader = Row.AppointHeader;
                        fi.HeaderContent = (Row.HeaderContent ?? string.Empty).Trim();
                        fi.AppointSocket = Row.AppointSocket;
                        fi.SocketContent = (Row.SocketContent ?? string.Empty).Trim();
                        fi.AppointLength = Row.AppointLength;
                        fi.LengthContent = (Row.LengthContent ?? string.Empty).Trim();
                        fi.AppointPort = Row.AppointPort;
                        fi.PortContent = (Row.PortContent ?? string.Empty).Trim();

                        fi.IsExecute = Row.IsExecute;
                        fi.FEType = (FilterConfig.Filter.FilterExecuteType)Row.ExecuteType;

                        Guid g;
                        fi.Execute_GUID = Guid.TryParse(Row.ExecuteId, out g) ? g : Guid.Empty;

                        fi.IsProgressionContinuous = Row.IsProgressionContinuous;
                        fi.ProgressionStep = Row.ProgressionStep < 1 ? 1 : Row.ProgressionStep;
                        fi.IsProgressionCarry = Row.IsProgressionCarry;
                        fi.ProgressionCarryNumber = Row.ProgressionCarryNumber < 1 ? 1 : Row.ProgressionCarryNumber;

                        //TrimEnd(',') 与 WinForms 的 bSave_Click 逐字一致 —— 存进库的串要能对得上
                        fi.FSearch = search.ToString().TrimEnd(',');
                        fi.FModify = modify.ToString().TrimEnd(',');
                        fi.ExcludePosition = exclude.ToString().TrimEnd(',');
                        fi.ProgressionPosition = progression.ToString().TrimEnd(',');
                        fi.RandomPosition = random.ToString().TrimEnd(',');

                        //改的是对象属性，不动列表结构 —— 没有 ListChanged，得自己推
                        FilterConfig.List.SaveFilterList_ToDB();
                        FeedPump.MarkDirty(FeedList.Filter);

                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveFilterEdit), ex);
                        return ex.Message;
                    }
                }

                /// <summary>勾了「指定」就必须有值。返回 null 表示都合规。</summary>
                /*
                    四个「指定」框的校验，逐条照 CheckFilterIsValid（FilterEdit 864–960）。

                    每一项都是两道：<b>勾了不能空</b>，以及<b>格式要对</b>。
                    之前只做了第一道 —— 格式错的串照样存得进去，然后在
                    DoFilterList 里静默地永不命中，比报错难查得多。

                    三个正则原样照抄，不要"顺手改好看"：
                      套接字  ^(\d+)(;\d+)*$      分号分隔，<b>不支持区间</b>
                      端口    ^(\d+[-;])*\d+$     分号或减号，支持 80-90 这样的区间
                      长度    ^(\d+[-;])*\d+$     同端口
                    套接字比另外两个严，是因为套接字是句柄、区间没有意义。
                */
                private static string CheckAppoint(FilterEditRow Row)
                {
                    if (Row.AppointHeader)
                    {
                        string s = (Row.HeaderContent ?? string.Empty).Trim();

                        //包头是十六进制串：两位一组，组间可空格（IsHexString 的规则）
                        if (s.Length == 0 || !SystemConfig.IsHexString(s))
                        {
                            return UI.T("FilterEditForm.AppointHead.Error", "指定包头数据错误");
                        }
                    }

                    if (Row.AppointSocket)
                    {
                        string s = (Row.SocketContent ?? string.Empty).Trim();

                        if (s.Length == 0 || !Regex.IsMatch(s, @"^(\d+)(;\d+)*$"))
                        {
                            return UI.T("FilterEditForm.AppointSocket.Error", "指定套接字错误");
                        }
                    }

                    if (Row.AppointLength)
                    {
                        string s = (Row.LengthContent ?? string.Empty).Trim();

                        if (s.Length == 0 || !Regex.IsMatch(s, @"^(\d+[-;])*\d+$"))
                        {
                            return UI.T("FilterEditForm.AppointLength.Error", "指定长度错误");
                        }
                    }

                    if (Row.AppointPort)
                    {
                        string s = (Row.PortContent ?? string.Empty).Trim();

                        if (s.Length == 0 || !Regex.IsMatch(s, @"^(\d+[-;])*\d+$"))
                        {
                            return UI.T("FilterEditForm.AppointPort.Error", "指定端口错误");
                        }
                    }

                    return null;
                }

                /*
                    换包（Action = Change）的数据完整度检测，照 CheckFilterIsValid 962–1100。

                    换包是<b>用修改行整体替换封包</b>，所以那一行必须是从头开始
                    连续的一段字节：中间空一格就等于"这一位不改"，与整体替换自相矛盾。

                    三种表形的起点都是 <b>0</b>：
                      普通 / 高级·包头   列 0 开始
                      高级·指定位置     <b>偏移 0</b> 开始（源码里是从列下标 FilterSize_MaxLen
                                        起算，那正是偏移 0 那一列），负偏移不参与检查

                    <b>一处刻意的放宽</b>：源码用 `iMaxIndex == 0` 判空，于是"只填了第 0 格"
                    也会被当成没填而报错 —— 一个字节的替换包是合法的，那是它判空方式的副作用。
                    这里改成按"有没有填过"判断，单字节放行。

                    <b>一处刻意的照搬</b>：标了随机的格子值是空的（设为随机会清值），
                    所以它在这里算"缺口"，换包里不能夹随机位。这是原产品的行为，不自作主张放开。
                */
                private static string CheckChange(FilterEditRow Row)
                {
                    if (Row.Action != (int)FilterConfig.Filter.FilterAction.Change)
                    {
                        return null;
                    }

                    string bad = UI.T("FilterEditForm.Change.Error", "换包数据错误");

                    var filled = new HashSet<int>();
                    int max = -1;

                    if (Row.Modify != null)
                    {
                        foreach (FilterModifyCell c in Row.Modify)
                        {
                            if (c == null || c.Index < 0) { continue; }

                            if (!string.IsNullOrEmpty((c.Value ?? string.Empty).Trim()))
                            {
                                filled.Add(c.Index);

                                if (c.Index > max) { max = c.Index; }
                            }
                        }
                    }

                    //一格都没填
                    if (max < 0) { return bad; }

                    //0 到最后一格之间不能有缺口
                    for (int i = 0; i < max; i++)
                    {
                        if (!filled.Contains(i)) { return bad; }
                    }

                    return null;
                }

                /// <summary>位掩码 → 12 个 bool。位序与 FilterRow.ToMask 严格对应，改一处必须改两处。</summary>
                private static FilterConfig.Filter.FilterFunction MaskToFunction(int Mask)
                {
                    var f = new FilterConfig.Filter.FilterFunction();

                    f.Send = (Mask & (1 << 0)) != 0;
                    f.SendTo = (Mask & (1 << 1)) != 0;
                    f.Recv = (Mask & (1 << 2)) != 0;
                    f.RecvFrom = (Mask & (1 << 3)) != 0;
                    f.WSASend = (Mask & (1 << 4)) != 0;
                    f.WSASendTo = (Mask & (1 << 5)) != 0;
                    f.WSARecv = (Mask & (1 << 6)) != 0;
                    f.WSARecvFrom = (Mask & (1 << 7)) != 0;
                    f.TCP_Req = (Mask & (1 << 8)) != 0;
                    f.UDP_Req = (Mask & (1 << 9)) != 0;
                    f.TCP_Resp = (Mask & (1 << 10)) != 0;
                    f.UDP_Resp = (Mask & (1 << 11)) != 0;

                    return f;
                }

                #endregion

                #region//获取滤镜列表执行模式

                public static FilterConfig.Filter.Execute GetFilterListExecute_ByString(string sFLExecute)
                {
                    FilterConfig.Filter.Execute FLExecute = new FilterConfig.Filter.Execute();

                    try
                    {
                        FLExecute = (FilterConfig.Filter.Execute)Enum.Parse(typeof(FilterConfig.Filter.Execute), sFLExecute);
                    }
                    catch (Exception ex)
                    {
                        FLExecute = FilterConfig.Filter.Execute.Priority;
                        Operate.DoLog(nameof(GetFilterListExecute_ByString), ex);
                    }

                    return FLExecute;
                }

                #endregion

                #region//滤镜列表的列表操作

                public static async Task UpdateFilterList_ByListAction(SystemConfig.ListAction listAction, List<FilterInfo> fiList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (FilterInfo fi in fiList)
                                {
                                    FilterConfig.List.lstFilterInfo.Remove(fi);
                                    FilterConfig.List.lstFilterInfo.Insert(0, fi);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (FilterInfo fi in fiList)
                                {
                                    int iIndex = FilterConfig.List.lstFilterInfo.IndexOf(fi);

                                    if (iIndex > 0)
                                    {
                                        FilterConfig.List.lstFilterInfo.Remove(fi);
                                        FilterConfig.List.lstFilterInfo.Insert(iIndex - 1, fi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (FilterInfo fi in fiList)
                                {
                                    int iIndex = FilterConfig.List.lstFilterInfo.IndexOf(fi);

                                    if (iIndex > -1 && iIndex < FilterConfig.List.lstFilterInfo.Count - 1)
                                    {
                                        FilterConfig.List.lstFilterInfo.Remove(fi);
                                        FilterConfig.List.lstFilterInfo.Insert(iIndex + 1, fi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (FilterInfo fi in fiList)
                                {
                                    FilterConfig.List.lstFilterInfo.Remove(fi);
                                    FilterConfig.List.lstFilterInfo.Add(fi);
                                }

                                break;

                            case SystemConfig.ListAction.Copy:

                                foreach (FilterInfo fi in fiList)
                                {
                                    FilterConfig.Filter.CopyFilter(fi);
                                }

                                break;

                            case SystemConfig.ListAction.Export:

                                string sFName = fiList[0].FName;
                                await FilterConfig.List.SaveFilterList_Dialog(sFName, fiList);

                                break;

                            case SystemConfig.ListAction.Delete:

                                await FilterConfig.Filter.DeleteFilter_Dialog(fiList);

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateFilterList_ByListAction), ex);
                    }
                }

                #endregion

                #region//执行滤镜列表

                public static FilterConfig.Filter.FilterAction DoFilterList(
                    Int32 iSocket, 
                    Span<byte> bufferSpan, 
                    out byte[] bNewBuffer, 
                    PacketConfig.Packet.PacketType ptType, 
                    PacketConfig.Packet.SockAddr sAddr)
                {
                    FilterConfig.Filter.FilterAction faReturn = FilterConfig.Filter.FilterAction.None;
                    bNewBuffer = null;

                    try
                    {
                        //【B-IPC 阶段 1】取一次引用用到底。
                        //无头核心下会拿到一份不可变数组（Volatile 换引用，见 Ipc/FilterEngine），
                        //外壳 / WinForms 下就是 lstFilterInfo 本身，行为与改造前一致。
                        var filters = Ipc.FilterEngine.Filters;
                        for (int i = 0; i < filters.Count; i++)
                        {
                            FilterConfig.Filter.FilterAction faDoFilter = FilterConfig.Filter.DoFilter(filters[i], iSocket, bufferSpan, out bNewBuffer, ptType, sAddr);

                            if (faDoFilter != Filter.FilterAction.None)
                            {
                                faReturn = faDoFilter;

                                if (faReturn == Filter.FilterAction.Intercept ||
                                    faReturn == Filter.FilterAction.Change ||
                                    faReturn == Filter.FilterAction.NoModify_Display ||
                                    faReturn == Filter.FilterAction.NoModify_NoDisplay ||                                    
                                    FilterConfig.Filter.FilterExecute == FilterConfig.Filter.Execute.Priority)
                                {
                                    if (bNewBuffer == null)
                                    {
                                        bNewBuffer = bufferSpan.ToArray();
                                    }

                                    return faReturn;
                                }
                            }                            
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(DoFilterList), ex);
                    }

                    if (bNewBuffer == null)
                    {
                        bNewBuffer = bufferSpan.ToArray();
                    }                    

                    return faReturn;
                }

                #endregion

                #region//保存滤镜列表到数据库

                /*
                    整表保存。删空 + 全部插入，<b>装在同一个事务里</b>（见 DataBase.SaveTable_Filter）。

                    原来是「删一次事务 + N 条各一次事务」，中间那个窗口里磁盘上的表是空的 ——
                    在那儿崩溃滤镜就没了。而这个方法在每次改动滤镜后都会被调用一次。
                */
                public static void SaveFilterList_ToDB()
                {
                    DataBase.SaveTable_Filter(FilterConfig.List.lstFilterInfo);
                }

                #endregion

                #region//从数据库加载滤镜列表

                public static void LoadFilterList_FromDB()
                {
                    try
                    {
                        DataTable dtFilter = DataBase.SelectTable_Filter();

                        foreach (DataRow dataRow in dtFilter.Rows)
                        {
                            FilterConfig.Filter.AddFilter(
                                Convert.ToBoolean(dataRow["IsEnable"]),
                                Guid.Parse(dataRow["GUID"].ToString()),
                                dataRow["Name"].ToString(),
                                Convert.ToBoolean(dataRow["AppointHeader"]),
                                dataRow["HeaderContent"].ToString(),
                                Convert.ToBoolean(dataRow["AppointSocket"]),
                                dataRow["SocketContent"].ToString(),
                                Convert.ToBoolean(dataRow["AppointLength"]),
                                dataRow["LengthContent"].ToString(),
                                Convert.ToBoolean(dataRow["AppointPort"]),
                                dataRow["PortContent"].ToString(),
                                FilterConfig.Filter.GetFilterMode_ByString(dataRow["Mode"].ToString()),
                                FilterConfig.Filter.GetFilterAction_ByString(dataRow["Action"].ToString()),
                                Convert.ToBoolean(dataRow["IsExecute"]),
                                FilterConfig.Filter.GetFilterExecuteType_ByString(dataRow["ExecuteType"].ToString()),
                                Guid.Parse(dataRow["ExecuteGUID"].ToString()),
                                FilterConfig.Filter.GetFilterFunction_ByString(dataRow["Function"].ToString()),
                                FilterConfig.Filter.GetFilterStartFrom_ByString(dataRow["StartFrom"].ToString()),
                                false,
                                Convert.ToBoolean(dataRow["IsProgressionContinuous"]),
                                Convert.ToInt32(dataRow["ProgressionStep"]),
                                Convert.ToBoolean(dataRow["IsProgressionCarry"]),
                                Convert.ToInt32(dataRow["ProgressionCarryNumber"]),
                                dataRow["ProgressionPosition"].ToString(),
                                0,
                                dataRow["ExcludePosition"].ToString(),
                                dataRow["RandomPosition"].ToString(),
                                dataRow["Search"].ToString(),
                                dataRow["Modify"].ToString());
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadFilterList_FromDB), ex);
                    }
                }

                #endregion

                #region//保存滤镜列表到文件（对话框）

                public static async Task SaveFilterList_Dialog(string FileName, List<FilterInfo> fiList)
                {
                    try
                    {
                        if (FilterConfig.List.lstFilterInfo.Count > 0)
                        {
                            FilePick sfdSaveFile = new FilePick();
                            sfdSaveFile.Filter = UI.T("FilterListFile", "滤镜列表文件") + "（*.fp）|*.fp";

                            if (!string.IsNullOrEmpty(FileName))
                            {
                                sfdSaveFile.FileName = FileName;
                            }

                            string sPickedPath = await UI.PickSave(sfdSaveFile);
                            if (!string.IsNullOrEmpty(sPickedPath))
                            {
                                string FilePath = sPickedPath;
                                if (!string.IsNullOrEmpty(FilePath))
                                {
                                    var EncryptPassword = await SystemConfig.GetEncryptExportAsync(UI.T("ExportFilterList", "导出滤镜列表"));

                                    if (SaveFilterList(FilePath, fiList, EncryptPassword.DoEncrypt, EncryptPassword.Password))
                                    {
                                        string Title = UI.T("ExportFilterList.Success", "导出滤镜列表成功");
                                        UI.Notify(UiIcon.Success, Title, FilePath);
                                        Operate.DoLog(nameof(SaveFilterList_Dialog), Title + ": " + FilePath);
                                    }
                                    else
                                    {
                                        string Title = UI.T("ExportFilterList.Error", "导出滤镜列表失败");
                                        string Content = UI.T("CheckSystemLog", "请检查系统日志");
                                        UI.Notify(UiIcon.Error, Title, Content);
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveFilterList_Dialog), ex);
                    }
                }

                private static bool SaveFilterList(string FilePath, List<FilterInfo> fiList, bool DoEncrypt, string Password)
                {
                    try
                    {
                        XDocument xdoc = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };

                        XElement xeRoot = FilterConfig.List.GetFilterList_XML(fiList);
                        if (xeRoot == null)
                        {
                            return false;
                        }

                        xdoc.Add(xeRoot);
                        xdoc.Save(FilePath);

                        if (DoEncrypt)
                        {
                            if (!string.IsNullOrEmpty(Password))
                            {
                                SystemConfig.EncryptXMLFile(FilePath, Password);
                            }
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveFilterList), ex);
                    }

                    return false;
                }

                public static XElement GetFilterList_XML(List<FilterInfo> fiList)
                {
                    try
                    {
                        XElement xeRoot = new XElement("FilterList");

                        if (fiList == null)
                        {
                            fiList = Operate.FilterConfig.List.lstFilterInfo.ToList();
                        }

                        foreach (FilterInfo fi in fiList)
                        {
                            XElement xeFilter =
                                new XElement("Filter",
                                new XElement("IsEnable", fi.IsEnable.ToString()),
                                new XElement("ID", fi.FID.ToString().ToUpper()),
                                new XElement("Name", fi.FName),
                                new XElement("AppointHeader", fi.AppointHeader.ToString()),
                                new XElement("HeaderContent", fi.HeaderContent),
                                new XElement("AppointSocket", fi.AppointSocket.ToString()),
                                new XElement("SocketContent", fi.SocketContent),
                                new XElement("AppointLength", fi.AppointLength.ToString()),
                                new XElement("LengthContent", fi.LengthContent),
                                new XElement("AppointPort", fi.AppointPort.ToString()),
                                new XElement("PortContent", fi.PortContent),
                                new XElement("Mode", fi.FMode),
                                new XElement("Action", fi.FAction),
                                new XElement("IsExecute", fi.IsExecute.ToString()),
                                new XElement("ExecuteType", fi.FEType),
                                new XElement("ExecuteGUID", fi.Execute_GUID.ToString().ToUpper()),
                                new XElement("Function", FilterConfig.Filter.GetFilterFunctionString(fi.FFunction)),
                                new XElement("StartFrom", fi.FStartFrom),
                                new XElement("IsProgressionContinuous", fi.IsProgressionContinuous.ToString()),
                                new XElement("ProgressionStep", fi.ProgressionStep),
                                new XElement("IsProgressionCarry", fi.IsProgressionCarry.ToString()),
                                new XElement("ProgressionCarryNumber", fi.ProgressionCarryNumber),
                                new XElement("ProgressionPosition", fi.ProgressionPosition),
                                new XElement("ExcludePosition", fi.ExcludePosition),
                                new XElement("RandomPosition", fi.RandomPosition),
                                new XElement("Search", fi.FSearch),
                                new XElement("Modify", fi.FModify)
                                );

                            xeRoot.Add(xeFilter);
                        }

                        return xeRoot;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetFilterList_XML), ex);
                    }

                    return null;
                }

                #endregion

                #region//从文件加载滤镜列表（对话框）

                public static async Task LoadFilterList_Dialog()
                {
                    try
                    {
                        FilePick ofdLoadFile = new FilePick();
                        ofdLoadFile.Filter = UI.T("FilterListFile", "滤镜列表文件") + "（*.fp）|*.fp";

                        string sPickedPath = await UI.PickOpen(ofdLoadFile);
                        if (!string.IsNullOrEmpty(sPickedPath))
                        {
                            string FilePath = sPickedPath;
                            if (!string.IsNullOrEmpty(FilePath))
                            {
                                if (await LoadFilterList(FilePath, true))
                                {
                                    string Title = UI.T("ImportFilterList.Success", "导入滤镜列表成功");
                                    UI.Notify(UiIcon.Success, Title, FilePath);
                                    Operate.DoLog(nameof(LoadFilterList_Dialog), Title + ": " + FilePath);
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadFilterList_Dialog), ex);
                    }
                }

                private static async Task<bool> LoadFilterList(string FilePath, bool LoadFromUser)
                {
                    try
                    {
                        if (File.Exists(FilePath))
                        {
                            XDocument xdoc = null;

                            bool bEncrypt = SystemConfig.IsEncryptXMLFile(FilePath);
                            if (bEncrypt)
                            {
                                if (LoadFromUser)
                                {
                                    xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("ImportFilterList", "导入滤镜列表"), FilePath);
                                }                                
                            }
                            else
                            {
                                xdoc = XDocument.Load(FilePath);
                            }

                            if (xdoc == null)
                            {
                                string sError = UI.T("Password.Incorrect", "导入失败: 密码错误");

                                if (LoadFromUser)
                                {
                                    UI.Toast(UiIcon.Error, sError);
                                }
                                else
                                {
                                    Operate.DoLog(nameof(LoadFilterList), sError);
                                }

                                return false;
                            }

                            LoadFilterList_FromXDocument(xdoc);
                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadFilterList), ex);
                    }

                    return false;
                }

                public static void LoadFilterList_FromXDocument(XDocument xdoc)
                {
                    try
                    {
                        foreach (XElement xeFilter in xdoc.Root.Elements())
                        {
                            bool bIsEnable = false;
                            if (xeFilter.Element("IsEnable") != null)
                            {
                                bIsEnable = bool.Parse(xeFilter.Element("IsEnable").Value);
                            }

                            Guid FID = Guid.Empty;
                            if (xeFilter.Element("ID") == null || !Guid.TryParse(xeFilter.Element("ID").Value, out FID) || FilterConfig.Filter.GetFilter_ByGuid(FID) != null)
                            {
                                FID = Guid.NewGuid();
                            }

                            string sFName = string.Empty;
                            if (xeFilter.Element("Name") != null)
                            {
                                sFName = xeFilter.Element("Name").Value;
                            }

                            bool bAppointHeader = false;
                            if (xeFilter.Element("AppointHeader") != null)
                            {
                                bAppointHeader = bool.Parse(xeFilter.Element("AppointHeader").Value);
                            }

                            string sFHeaderContent = string.Empty;
                            if (xeFilter.Element("HeaderContent") != null)
                            {
                                sFHeaderContent = xeFilter.Element("HeaderContent").Value;
                            }

                            bool bAppointSocket = false;
                            if (xeFilter.Element("AppointSocket") != null)
                            {
                                bAppointSocket = bool.Parse(xeFilter.Element("AppointSocket").Value);
                            }

                            string sFSocketContent = string.Empty;
                            if (xeFilter.Element("SocketContent") != null)
                            {
                                sFSocketContent = xeFilter.Element("SocketContent").Value;
                            }

                            bool bAppointLength = false;
                            if (xeFilter.Element("AppointLength") != null)
                            {
                                bAppointLength = bool.Parse(xeFilter.Element("AppointLength").Value);
                            }

                            string sFLengthContent = string.Empty;
                            if (xeFilter.Element("LengthContent") != null)
                            {
                                sFLengthContent = xeFilter.Element("LengthContent").Value;
                            }

                            bool bAppointPort = false;
                            if (xeFilter.Element("AppointPort") != null)
                            {
                                bAppointPort = bool.Parse(xeFilter.Element("AppointPort").Value);
                            }

                            string sFPortContent = string.Empty;
                            if (xeFilter.Element("PortContent") != null)
                            {
                                sFPortContent = xeFilter.Element("PortContent").Value;
                            }

                            FilterConfig.Filter.FilterMode FilterMode = FilterConfig.Filter.FilterMode.Normal;
                            if (xeFilter.Element("Mode") != null)
                            {
                                FilterMode = FilterConfig.Filter.GetFilterMode_ByString(xeFilter.Element("Mode").Value);
                            }

                            FilterConfig.Filter.FilterAction FilterAction = FilterConfig.Filter.FilterAction.NoModify_Display;
                            if (xeFilter.Element("Action") != null)
                            {
                                FilterAction = FilterConfig.Filter.GetFilterAction_ByString(xeFilter.Element("Action").Value);
                            }

                            bool bIsExecute = false;
                            if (xeFilter.Element("IsExecute") != null)
                            {
                                bIsExecute = bool.Parse(xeFilter.Element("IsExecute").Value);
                            }

                            FilterConfig.Filter.FilterExecuteType FilterExecuteType = new FilterConfig.Filter.FilterExecuteType();
                            if (xeFilter.Element("ExecuteType") != null)
                            {
                                FilterExecuteType = FilterConfig.Filter.GetFilterExecuteType_ByString(xeFilter.Element("ExecuteType").Value);
                            }

                            Guid Execute_GUID = Guid.Empty;
                            if (xeFilter.Element("ExecuteGUID") != null)
                            {
                                Guid.TryParse(xeFilter.Element("ExecuteGUID").Value, out Execute_GUID);
                            }

                            FilterConfig.Filter.FilterFunction FilterFunction = new FilterConfig.Filter.FilterFunction();
                            if (xeFilter.Element("Function") != null)
                            {
                                FilterFunction = FilterConfig.Filter.GetFilterFunction_ByString(xeFilter.Element("Function").Value);
                            }

                            FilterConfig.Filter.FilterStartFrom FilterStartFrom = FilterConfig.Filter.FilterStartFrom.Head;
                            if (xeFilter.Element("StartFrom") != null)
                            {
                                FilterStartFrom = FilterConfig.Filter.GetFilterStartFrom_ByString(xeFilter.Element("StartFrom").Value);
                            }

                            bool IsProgressionDone = false;

                            bool bIsProgressionContinuous = false;
                            if (xeFilter.Element("IsProgressionContinuous") != null)
                            {
                                bIsProgressionContinuous = bool.Parse(xeFilter.Element("IsProgressionContinuous").Value);
                            }

                            int iFProgressionStep = 1;
                            if (xeFilter.Element("ProgressionStep") != null)
                            {
                                iFProgressionStep = int.Parse(xeFilter.Element("ProgressionStep").Value);
                            }

                            bool bIsProgressionCarry = false;
                            if (xeFilter.Element("IsProgressionCarry") != null)
                            {
                                bIsProgressionCarry = bool.Parse(xeFilter.Element("IsProgressionCarry").Value);
                            }

                            int iFProgressionCarryNumber = 1;
                            if (xeFilter.Element("ProgressionCarryNumber") != null)
                            {
                                iFProgressionCarryNumber = int.Parse(xeFilter.Element("ProgressionCarryNumber").Value);
                            }

                            string sFProgressionPosition = string.Empty;
                            if (xeFilter.Element("ProgressionPosition") != null)
                            {
                                sFProgressionPosition = xeFilter.Element("ProgressionPosition").Value;
                            }

                            int iProgressionCount = 0;

                            string sFExcludePosition = string.Empty;
                            if (xeFilter.Element("ExcludePosition") != null)
                            {
                                sFExcludePosition = xeFilter.Element("ExcludePosition").Value;
                            }

                            string RandomPosition = string.Empty;
                            if (xeFilter.Element("RandomPosition") != null)
                            {
                                RandomPosition = xeFilter.Element("RandomPosition").Value;
                            }

                            string sFSearch = string.Empty;
                            if (xeFilter.Element("Search") != null)
                            {
                                sFSearch = xeFilter.Element("Search").Value;
                            }

                            string sFModify = string.Empty;
                            if (xeFilter.Element("Modify") != null)
                            {
                                sFModify = xeFilter.Element("Modify").Value;
                            }

                            FilterConfig.Filter.AddFilter(
                                bIsEnable,
                                FID,
                                sFName,
                                bAppointHeader,
                                sFHeaderContent,
                                bAppointSocket,
                                sFSocketContent,
                                bAppointLength,
                                sFLengthContent,
                                bAppointPort,
                                sFPortContent,
                                FilterMode,
                                FilterAction,
                                bIsExecute,
                                FilterExecuteType,
                                Execute_GUID,
                                FilterFunction,
                                FilterStartFrom,
                                IsProgressionDone,
                                bIsProgressionContinuous,
                                iFProgressionStep,
                                bIsProgressionCarry,
                                iFProgressionCarryNumber,
                                sFProgressionPosition,
                                iProgressionCount,
                                sFExcludePosition,
                                RandomPosition,
                                sFSearch,
                                sFModify);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadFilterList_FromXDocument), ex);
                    }
                }

                #endregion
            }

            #endregion
        }

        #endregion

        #region//发送配置

        public static class SendConfig
        {
            #region//发送

            public static class Send
            {
                #region//新增发送

                public static void AddSend_New()
                {
                    try
                    {
                        bool IsEnable = false;
                        Guid SID = Guid.NewGuid();
                        int SNum = SendConfig.List.lstSendInfo.Count + 1;
                        string SName = string.Format(UI.T("SendList.NewSend", "发送 {0}"), SNum.ToString());
                        bool SSystemSocket = false;
                        int SLoopCNT = 1;
                        int SLoopINT = 1000;
                        string SNotes = string.Empty;
                        BindingList<PacketInfo> SCollection = new BindingList<PacketInfo>();

                        Send.AddSend(IsEnable, SID, SName, SSystemSocket, SLoopCNT, SLoopINT, SCollection, SNotes);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddSend_New), ex);
                    }
                }

                /*
                    ⚠️⚠️ <b>循环次数的下限落在这里，不在控件属性上</b>（2026-09-10 补）。

                    「循环 0 次」的发送跑起来是 `for (i = 0; i < 0; i++)` —— <b>外层循环一次都不进</b>：
                    一个包不发、三个计数全是 0、连「执行次数」都不加，而日志照写「执行完毕」。
                    实测（改动前）：Total=0 OK=0 Fail=0 ExecCount=0。

                    下限 1 原来<b>只写在两处控件上</b>：WinForms 的 nudLoopCNT.Minimum、
                    外壳的 min="1"。而 <b>HTML 的 min 只在表单校验时生效，直接键入 0 照样进去</b>，
                    另外三条写入路径（从库读回、备份导入、复制发送）更是一层都没有 ——
                    这与账号那个「限制数量 0」是<b>同一个错</b>，见「控件属性不是约束」。

                    所以夹在 AddSend / UpdateSend 这两个咽喉上，它俩覆盖：
                    外壳保存 · WinForms 保存 · LoadSendList_FromDB · 备份导入 · 复制发送。

                    ⚠️ 间隔（SLoopINT）只夹负数、<b>不夹 0</b> —— 0 是「不间隔、连着发」，
                    是个正当取值（界面上 min 就是 0），而且它还兼着「要不要报进度」那个开关。
                */
                internal static int NormalizeLoopCount(int SLoopCNT, string SName)
                {
                    if (SLoopCNT >= 1) { return SLoopCNT; }

                    SystemConfig.LogThrottled("SendLoopCNT." + SName, string.Format(
                        UI.T("SendList.LoopCount.Fixed",
                             "发送「{0}」的循环次数不正确（{1}），已按 1 次处理。"),
                        SName, SLoopCNT));

                    return 1;
                }

                public static void AddSend(bool IsEnable, Guid SID, string SName, bool SSystemSocket, int SLoopCNT, int SLoopINT, BindingList<PacketInfo> SCollection, string SNotes)
                {
                    try
                    {
                        if (SID != Guid.Empty && !string.IsNullOrEmpty(SName))
                        {
                            SLoopCNT = NormalizeLoopCount(SLoopCNT, SName);
                            if (SLoopINT < 0) { SLoopINT = 0; }

                            SendInfo si = new SendInfo(IsEnable, SID, SName, SSystemSocket, SLoopCNT, SLoopINT, SCollection, SNotes);
                            SendConfig.List.SendToList(si);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddSend), ex);
                    }
                }

                #endregion

                #region//新增发送集

                public static bool AddSendCollection_ByPacketInfo(Guid SID, List<PacketInfo> piList)
                {
                    try
                    {
                        if (SID != null && SID != Guid.Empty && piList.Count > 0)
                        {
                            foreach (SendInfo si in SendConfig.List.lstSendInfo)
                            {
                                if (si.SID == SID)
                                {
                                    foreach (PacketInfo pi in piList)
                                    {
                                        SendConfig.Send.AddSendCollection(si.SCollection, pi.PacketSocket, pi.PacketType, pi.PacketFrom, pi.PacketTo, pi.PacketBuffer);
                                    }
                                }
                            }

                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddSendCollection_ByPacketInfo), ex);
                    }

                    return false;
                }

                public static bool AddSendCollection_ByProxyInfo(Guid SID, List<ProxyInfo> piList)
                {
                    try
                    {
                        if (SID != null && SID != Guid.Empty && piList.Count > 0)
                        {
                            foreach (SendInfo si in SendConfig.List.lstSendInfo)
                            {
                                if (si.SID == SID)
                                {
                                    foreach (ProxyInfo pi in piList)
                                    {
                                        SendConfig.Send.AddSendCollection(si.SCollection, pi.PacketSocket, pi.PacketType, pi.ClientAddr, pi.ServerAddr, pi.PacketBuffer);
                                    }
                                }
                            }

                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddSendCollection_ByProxyInfo), ex);
                    }

                    return false;
                }

                public static void AddSendCollection(BindingList<PacketInfo> SCollection, int Socket, PacketConfig.Packet.PacketType ptType, string PacketFrom, string PacketTo, byte[] PacketBuffer)
                {
                    try
                    {
                        PacketInfo pi = new PacketInfo();
                        pi.PacketSocket = Socket;
                        pi.PacketType = ptType;
                        pi.PacketFrom = PacketFrom;
                        pi.PacketTo = PacketTo;
                        pi.PacketBuffer = PacketBuffer;
                        pi.PacketLen = PacketBuffer.Length;
                        pi.PacketData = PacketConfig.Packet.GetPacketData_Hex(PacketBuffer, PacketConfig.Packet.PacketData_MaxLen);
                        SCollection.Add(pi);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddSendCollection), ex);
                    }
                }

                #endregion                

                #region//更新发送

                public static void UpdateSend(SendInfo ssi, string SName, bool SSystemSocket, int SLoopCNT, int SLoopINT, BindingList<PacketInfo> SCollection, string SNotes)
                {
                    try
                    {
                        if (ssi != null)
                        {
                            ssi.SName = SName;
                            ssi.SSystemSocket = SSystemSocket;
                            ssi.SLoopCNT = NormalizeLoopCount(SLoopCNT, SName);   //见 NormalizeLoopCount 上面那段
                            ssi.SLoopINT = SLoopINT < 0 ? 0 : SLoopINT;
                            ssi.SCollection = new BindingList<PacketInfo>(SCollection.ToList());
                            ssi.SNotes = SNotes;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateSend), ex);
                    }
                }

