                #region//发送集的列表操作

                public static async Task UpdateSendCollection_ByListAction(BindingList<PacketInfo> SendCollection, SystemConfig.ListAction listAction, List<PacketInfo> piList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (PacketInfo pi in piList)
                                {
                                    SendCollection.Remove(pi);
                                    SendCollection.Insert(0, pi);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (PacketInfo pi in piList)
                                {
                                    int iIndex = SendCollection.IndexOf(pi);
                                    if (iIndex > 0)
                                    {
                                        SendCollection.Remove(pi);
                                        SendCollection.Insert(iIndex - 1, pi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (PacketInfo pi in piList)
                                {
                                    int iIndex = SendCollection.IndexOf(pi);
                                    if (iIndex > -1 && iIndex < SendCollection.Count - 1)
                                    {
                                        SendCollection.Remove(pi);
                                        SendCollection.Insert(iIndex + 1, pi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (PacketInfo pi in piList)
                                {
                                    SendCollection.Remove(pi);
                                    SendCollection.Add(pi);
                                }

                                break;

                            case SystemConfig.ListAction.Copy:

                                foreach (PacketInfo pi in piList)
                                {
                                    SendConfig.Send.AddSendCollection(
                                        SendCollection, 
                                        pi.PacketSocket, 
                                        pi.PacketType, 
                                        pi.PacketFrom, 
                                        pi.PacketTo, 
                                        pi.PacketBuffer);
                                }

                                break;

                            case SystemConfig.ListAction.Delete:

                                foreach (PacketInfo pi in piList)
                                {
                                    SendCollection.Remove(pi);
                                }

                                break;

                            case SystemConfig.ListAction.Export:

                                if (piList.Count > 0)
                                {
                                    await Send.SaveSendCollection_Dialog(string.Empty, piList);
                                }
                                else
                                {
                                    await Send.SaveSendCollection_Dialog(string.Empty, SendCollection.ToList());
                                }                                

                                break;

                            case SystemConfig.ListAction.Import:

                                await Send.LoadSendCollection_Dialog(SendCollection);

                                break;

                            case SystemConfig.ListAction.CleanUp:

                                if (SendCollection.Count > 0)
                                {
                                    if (await UI.Confirm(UI.T("SendCollection", "发送集列表"), UI.T("SureToDelete", "确定删除数据吗?")))
                                    {
                                        SendCollection.Clear();
                                    }
                                }

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateSendCollection_ByListAction), ex);
                    }
                }

                #endregion

                #region//保存发送集（对话框）

                public static async Task SaveSendCollection_Dialog(string FileName, List<PacketInfo> SendCollection)
                {
                    try
                    {
                        if (SendCollection.Count > 0)
                        {
                            FilePick sfdSaveFile = new FilePick();
                            sfdSaveFile.Filter = UI.T("SendList.SendCollectionFile", "发送集文件") + "（*.sc）|*.sc";

                            if (!string.IsNullOrEmpty(FileName))
                            {
                                sfdSaveFile.FileName = FileName;
                            }

                            string sPickedPath = await UI.PickSave(sfdSaveFile);
                            if (!string.IsNullOrEmpty(sPickedPath))
                            {
                                string FilePath = sPickedPath;
                                if (!string.IsNullOrEmpty(FilePath))
                                {
                                    var EncryptPassword = await SystemConfig.GetEncryptExportAsync(UI.T("ExportSendCollection", "导出发送集"));

                                    if (SaveSendCollection(FilePath, SendCollection, EncryptPassword.DoEncrypt, EncryptPassword.Password))
                                    {
                                        string Title = UI.T("ExportSendCollection.Success", "导出发送集成功");
                                        UI.Notify(UiIcon.Success, Title, FilePath);
                                        Operate.DoLog(nameof(SaveSendCollection_Dialog), Title + ": " + FilePath);
                                    }
                                    else
                                    {
                                        string Title = UI.T("ExportSendCollection.Error", "导出发送集失败");
                                        string Content = UI.T("CheckSystemLog", "请检查系统日志");
                                        UI.Notify(UiIcon.Error, Title, Content);
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendCollection_Dialog), ex);
                    }
                }

                public static bool SaveSendCollection(string FilePath, List<PacketInfo> SendCollection, bool DoEncrypt, string Password)
                {
                    try
                    {
                        SaveSendCollection_ToXDocument(FilePath, SendCollection);

                        if (DoEncrypt)
                        {
                            if (!string.IsNullOrEmpty(Password))
                            {
                                SystemConfig.EncryptXMLFile(FilePath, Password);
                            }
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendCollection), ex);
                    }

                    return false;
                }

                private static void SaveSendCollection_ToXDocument(string FilePath, List<PacketInfo> SendCollection)
                {
                    try
                    {
                        XDocument xdoc = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };

                        XElement xeRoot = new XElement("SendCollection");
                        xdoc.Add(xeRoot);

                        foreach (PacketInfo spi in SendCollection)
                        {
                            string sBuffer = SystemConfig.BytesToString(PacketConfig.Packet.EncodingFormat.Hex, spi.PacketBuffer);

                            XElement xeColl =
                                new XElement("Collection",
                                new XElement("Socket", spi.PacketSocket),
                                new XElement("Type", spi.PacketType),
                                new XElement("IPFrom", spi.PacketFrom),
                                new XElement("IPTo", spi.PacketTo),
                                new XElement("Buffer", sBuffer)
                                );

                            xeRoot.Add(xeColl);
                        }

                        xdoc.Save(FilePath);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendCollection_ToXDocument), ex);
                    }
                }

                #endregion

