                        Operate.DoLog(nameof(LoadSendCollection_Dialog), ex);
                    }
                }

                public static async Task<bool> LoadSendCollection(string FilePath, BindingList<PacketInfo> SendCollection, bool LoadFromUser)
                {
                    try
                    {
                        if (File.Exists(FilePath))
                        {
                            XDocument xdoc = null;

                            bool bEncrypt = SystemConfig.IsEncryptXMLFile(FilePath);
                            if (bEncrypt)
                            {
                                if (LoadFromUser)
                                {
                                    xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("ImportSendCollection", "导入发送集"), FilePath);
                                }
                            }
                            else
                            {
                                xdoc = XDocument.Load(FilePath);
                            }

                            if (xdoc == null)
                            {
                                string sError = UI.T("Password.Incorrect", "导入失败: 密码错误");
                                if (LoadFromUser)
                                {
                                    UI.Toast(UiIcon.Error, sError);
                                }
                                else
                                {
                                    Operate.DoLog(nameof(LoadSendCollection), sError);
                                }

                                return false;
                            }

                            LoadSendCollection_FromXDocument(xdoc, SendCollection);
                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendCollection), ex);
                    }
                    return false;
                }

                private static void LoadSendCollection_FromXDocument(XDocument xdoc, BindingList<PacketInfo> SendCollection)
                {
                    try
                    {
                        XElement xeRoot = xdoc.Root;

                        switch (xeRoot.Name.LocalName)
                        {
                            case "SendList":

                                #region//SendList File

                                foreach (XElement xeSend in xeRoot.Elements())
                                {
                                    int iSocket = 0;
                                    if (xeSend.Element("Socket") != null)
                                    {
                                        iSocket = int.Parse(xeSend.Element("Socket").Value);
                                    }

                                    PacketConfig.Packet.PacketType ptType = new PacketConfig.Packet.PacketType();
                                    if (xeSend.Element("Type") != null)
                                    {
                                        ptType = PacketConfig.Packet.GetPacketType_ByString(xeSend.Element("Type").Value);
                                    }

                                    string sIPFrom = string.Empty;
                                    if (xeSend.Element("IPFrom") != null)
                                    {
                                        sIPFrom = xeSend.Element("IPFrom").Value;
                                    }

                                    string sIPTo = string.Empty;
                                    if (xeSend.Element("ToAddress") != null)
                                    {
                                        sIPTo = xeSend.Element("ToAddress").Value;
                                    }

                                    byte[] bBuffer = null;
                                    if (xeSend.Element("Data") != null)
                                    {
                                        bBuffer = SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.Hex, xeSend.Element("Data").Value);
                                    }

                                    Send.AddSendCollection(SendCollection, iSocket, ptType, sIPFrom, sIPTo, bBuffer);
                                }

                                #endregion

                                break;

                            case "SendCollection":

                                #region//SendCollection File

                                foreach (XElement xeCollection in xeRoot.Elements())
                                {
                                    int iSocket = 0;
                                    if (xeCollection.Element("Socket") != null)
                                    {
                                        iSocket = int.Parse(xeCollection.Element("Socket").Value);
                                    }

                                    PacketConfig.Packet.PacketType ptType = new PacketConfig.Packet.PacketType();
                                    if (xeCollection.Element("Type") != null)
                                    {
                                        ptType = PacketConfig.Packet.GetPacketType_ByString(xeCollection.Element("Type").Value);
                                    }

                                    string sIPFrom = string.Empty;
                                    if (xeCollection.Element("IPFrom") != null)
                                    {
                                        sIPFrom = xeCollection.Element("IPFrom").Value;
                                    }

                                    string sIPTo = string.Empty;
                                    if (xeCollection.Element("IPTo") != null)
                                    {
                                        sIPTo = xeCollection.Element("IPTo").Value;
                                    }

                                    byte[] bBuffer = null;
                                    if (xeCollection.Element("Buffer") != null)
                                    {
                                        bBuffer = SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.Hex, xeCollection.Element("Buffer").Value);
                                    }

                                    Send.AddSendCollection(SendCollection, iSocket, ptType, sIPFrom, sIPTo, bBuffer);
                                }

                                #endregion

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendCollection_FromXDocument), ex);
                    }
                }

                #endregion

                #region//发送编辑 - 外壳入口（只出基础类型，按 Id 收发）

                /*
                    对应 WinForms 的 Controls/SendEdit。

                    【为什么要一个「编辑会话」】那边把发送集<b>拷一份</b>出来编辑
                    （SendEdit_Load 里 new BindingList<PacketInfo>(si.SCollection.ToList())），
                    只在按「保存」时才写回 —— 所以取消就是真的取消，改了的顺序、删掉的行都不算数。
                    外壳没有 UserControl 实例来存这份拷贝，只能放在这里。

                    外壳一次只开一个发送编辑弹窗，与那边一个 UserControl 实例一一对应，
                    所以用静态字段而不是字典。开新的会覆盖旧的（CloseSendEdit 会先收尾）。
                */

                private static Guid editSID = Guid.Empty;
                private static BindingList<PacketInfo> editCollection;

                /// <summary>发送编辑里那个「执行」用的执行器。与发送列表的 bgwSendList 是两回事。</summary>
                private static SendExecute editExecute = new SendExecute();

                /// <summary>
                /// 工作副本里按运行期 Id 找一条封包 —— 封包编辑从发送集里双击打开时用。
                /// 改的就是副本里那一条，按发送编辑的「保存」才随整份副本写回。
                /// </summary>
                public static PacketInfo FindEditPacket_ById(long Id)
                {
                    if (editCollection == null) { return null; }

                    foreach (PacketInfo pi in editCollection)
                    {
                        if (pi.Id == Id) { return pi; }
                    }

                    return null;
                }

                /// <summary>
                /// 打开编辑：把这条发送的字段与发送集拷一份出来。
                /// 返回的 <c>Id</c> 为空表示没找到。
                /// </summary>
                public static SendEditRow OpenSendEdit_ById(string SID)
                {
                    try
                    {
                        SendInfo si = SendConfig.List.FindSend_ById(SID);

                        if (si == null)
                        {
                            return new SendEditRow();
                        }

                        //上一次没关干净就先收尾，别让两个会话共用一个执行器
                        SendConfig.Send.CloseSendEdit();

                        editSID = si.SID;
                        editCollection = new BindingList<PacketInfo>(
                            si.SCollection == null ? new List<PacketInfo>() : si.SCollection.ToList());

                        return new SendEditRow
                        {
                            Id = si.SID.ToString().ToUpper(),
                            Name = si.SName,
                            UseSystemSocket = si.SSystemSocket,
                            LoopCount = si.SLoopCNT,
                            LoopInterval = si.SLoopINT,
                            Notes = si.SNotes,

                            //界面上要显示「用系统套接字」到底是哪个号，顺手带出去，省一次往返
                            SystemSocket = SystemConfig.SystemSocket,
                        };
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(OpenSendEdit_ById), ex);
                        return new SendEditRow();
                    }
                }

                /// <summary>关闭编辑：停掉执行器、丢掉工作副本。取消与保存都要调。</summary>
                public static void CloseSendEdit()
                {
                    try
                    {
                        editExecute.StopSend();
                        editSID = Guid.Empty;
                        editCollection = null;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(CloseSendEdit), ex);
                    }
                }

                /// <summary>工作副本里的发送集。</summary>
                public static SendPacketRow[] GetSendCollectionRows()
                {
                    try
                    {
                        if (editCollection == null)
                        {
                            return new SendPacketRow[0];
                        }

                        var rows = new SendPacketRow[editCollection.Count];

                        for (int i = 0; i < editCollection.Count; i++)
                        {
                            rows[i] = SendPacketRow.From_(editCollection[i]);
                        }

                        return rows;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetSendCollectionRows), ex);
                        return new SendPacketRow[0];
                    }
                }

                /// <summary>
                /// 发送集的右键菜单，按 Id 数组收。
                /// <b>只有六个动作</b>（置顶 / 上移 / 下移 / 置底 / 复制 / 删除）——
                /// 与发送列表那七个不同，这里没有「导出」，导出在工具条上、且是整表导。
                /// </summary>
                public static async Task<int> SendCollectionAction_ByIds(int Action, IList<string> Ids)
                {
                    try
                    {
                        if (editCollection == null)
                        {
                            return 0;
                        }

                        var picked = new List<PacketInfo>();
                        var want = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                        foreach (string id in Ids ?? new List<string>())
                        {
                            if (!string.IsNullOrEmpty(id)) { want.Add(id); }
                        }

                        //按列表里的先后顺序挑，理由与 PickFilters / PickSends 相同
                        foreach (PacketInfo pi in editCollection)
                        {
                            if (want.Contains(pi.Id.ToString()))
                            {
                                picked.Add(pi);
                            }
                        }

                        if (picked.Count == 0)
                        {
                            return 0;
                        }

                        int before = editCollection.Count;

                        await SendConfig.Send.UpdateSendCollection_ByListAction(
                            editCollection, (SystemConfig.ListAction)Action, picked);

                        return editCollection.Count - before;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SendCollectionAction_ByIds), ex);
                        return 0;
                    }
                }

                /// <summary>导入发送集（带文件框），追加进工作副本。</summary>
                public static async Task ImportSendCollection_Dialog_Shell()
                {
                    if (editCollection == null) { return; }

                    await SendConfig.Send.LoadSendCollection_Dialog(editCollection);
                }

                /// <summary>导出发送集（带文件框）。不改工作副本。</summary>
                public static async Task ExportSendCollection_Dialog_Shell()
                {
                    if (editCollection == null || editCollection.Count == 0) { return; }

                    await SendConfig.Send.SaveSendCollection_Dialog(string.Empty, editCollection.ToList());
                }

                /// <summary>清空发送集（带确认框）。只动工作副本，不保存就不算数。</summary>
                public static async Task ClearSendCollection_Dialog_Shell()
                {
                    if (editCollection == null || editCollection.Count == 0) { return; }

                    if (await UI.Confirm(
                        UI.T("InjectModeForm.miSendList", "发送列表"),
                        UI.T("SureToDelete", "确定删除数据吗?")))
                    {
                        editCollection.Clear();
                    }
                }

                /// <summary>
                /// 保存。返回空串表示成功，否则是要显示给用户的错误文案。
                ///
                /// 校验照搬 WinForms 的 SaveSend：<b>名称不能为空</b>。
                /// 保存成功后工作副本原样写回 SCollection，并落库 —— 后者是 WinForms
                /// 没做的（那边靠关窗统一保存，外壳没有那个时机）。
                /// </summary>
                public static string SaveSendEdit(
                    string SName, bool SSystemSocket, int SLoopCNT, int SLoopINT, string SNotes)
                {
                    try
                    {
                        SendInfo si = SendConfig.List.FindSend_ById(editSID.ToString());

                        if (si == null || editCollection == null)
                        {
                            return UI.T("SendEditForm.Gone", "这条发送已经不在列表里了");
                        }

                        string name = (SName ?? string.Empty).Trim();

                        if (name.Length == 0)
                        {
                            return UI.T("SendEditForm.SendName.Empty", "发送名称为空");
                        }

                        SendConfig.Send.UpdateSend(
                            si, name, SSystemSocket, SLoopCNT, SLoopINT,
                            new BindingList<PacketInfo>(editCollection.ToList()),
                            (SNotes ?? string.Empty).Trim());

                        SendConfig.List.SaveSendList_ToDB();
                        FeedPump.MarkDirty(FeedList.Send);

                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendEdit), ex);
                        return ex.Message;
                    }
                }

                /// <summary>
                /// 执行。返回空串表示已经开始，否则是错误文案。
                ///
                /// 两条前置校验照搬 WinForms 的 bExecute_Click：发送集不能为空、
                /// 勾了「系统套接字」就必须真的设过（<c>SystemConfig.SystemSocket &gt; 0</c>）。
                /// 后者不校验的话，Send_DoWork 里会直接 return，界面上表现为「点了没反应」。
                ///
                /// <b>执行前先保存</b>，与 WinForms 一致 —— 执行的是保存后的那份，
                /// 否则跑的和看到的不是一回事。
                /// </summary>
                public static string StartSendEdit(
                    string SName, bool SSystemSocket, int SLoopCNT, int SLoopINT, string SNotes)
                {
                    try
                    {
                        if (editCollection == null || editCollection.Count == 0)
                        {
                            return UI.T("SendEditForm.Collection.Empty", "发送集是空的");
                        }

                        if (SSystemSocket && SystemConfig.SystemSocket <= 0)
                        {
                            return UI.T("System.SystemSocket.Error", "系统套接字未设置");
                        }

                        string err = SendConfig.Send.SaveSendEdit(SName, SSystemSocket, SLoopCNT, SLoopINT, SNotes);

                        if (err.Length > 0)
                        {
                            return err;
                        }

                        SendInfo si = SendConfig.List.FindSend_ById(editSID.ToString());

                        if (si == null)
                        {
                            return UI.T("SendEditForm.Gone", "这条发送已经不在列表里了");
                        }

                        editExecute.StartSend(si);
                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(StartSendEdit), ex);
                        return ex.Message;
                    }
                }

                /// <summary>停止执行。</summary>
                public static void StopSendEdit()
                {
                    editExecute.StopSend();
                }

                /// <summary>
                /// 执行进度。前端在跑的时候按 200ms 轮询这个。
                ///
                /// ⚠️ <b>不要改成挂 Worker.ProgressChanged 推事件</b>：
                /// Send_DoWork 里 <c>ReportProgress</c> 只在 <c>LoopINT &gt; 0</c> 时才调
                /// （见 SendExecute.Send_DoWork），间隔填 0 就一个事件都没有，
                /// 三个计数会一直停在 0 直到跑完。轮询没有这个问题。
                ///
                /// 同样因为这个，<c>Index</c>（当前发到第几条）在间隔为 0 时不会动 ——
                /// WinForms 那边也是如此，不是这里漏了。
                /// </summary>
                public static SendProgressRow GetSendEditProgress()
                {
                    try
                    {
                        return new SendProgressRow
                        {
                            Running = editExecute.Running,
                            Index = editExecute.SendCollection_Index,
                            Total = editExecute.Total_Send,
                            Success = editExecute.Send_Success,
                            Fail = editExecute.Send_Failure,
                        };
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetSendEditProgress), ex);
                        return new SendProgressRow();
                    }
                }

                #endregion

            }

            #endregion

            #region//发送列表

            public static class List
            {
                /*
                    ⚠️⚠️ 这份表<b>工作线程与 UI 线程同时在动</b>，而它是个裸 List<T>：

                      SendList_Body（发送列表的工作线程）  Add · ToList · Remove
                      StopSendList   （UI 线程，用户点「停止」）  ToList · Remove
                      DoSend_ByIndex （UI 线程，快捷键 9001~9010）Add

                    「点停止」这条路<b>本来就会</b>让两条线程同时进来：UI 线程在遍历删，
                    工作线程的排空循环也在遍历删。List&lt;T&gt; 的 ToList() 走的是
                    Array.Copy —— 先读 _size 再拷数组，另一条线程正好在 Add 里扩容时
                    可以拷到越界或半截。表现是偶发的一次崩溃，且没法稳定复现。

                    锁只圈<b>对表本身的读写</b>：先在锁里取快照，出锁再去 StopSend()
                    与查 IsBusy —— 那两个会阻塞，握着锁做必然招来死锁。
                */
                private static readonly object seLock = new object();
                public static List<SendExecute> lstSendExecute = new List<SendExecute>();

                internal static void SendExecute_Add(SendExecute se)
                {
                    if (se == null) { return; }
                    lock (seLock) { lstSendExecute.Add(se); }
                }

                internal static void SendExecute_Remove(SendExecute se)
                {
                    lock (seLock) { lstSendExecute.Remove(se); }
                }

                internal static void SendExecute_Clear()
                {
                    lock (seLock) { lstSendExecute.Clear(); }
                }

                internal static int SendExecute_Count()
                {
                    lock (seLock) { return lstSendExecute.Count; }
                }

                /// <summary>取一份快照。⚠️ 拿到之后再去 StopSend / 查 IsBusy，别在锁里做。</summary>
                internal static List<SendExecute> SendExecute_Snapshot()
                {
                    lock (seLock) { return new List<SendExecute>(lstSendExecute); }
                }
                public static BindingList<SendInfo> lstSendInfo = new BindingList<SendInfo>();

                /*
                    ⚠️ 2026-09-11：从 BackgroundWorker 换成 Task（BW → Task 第二步）。

                    <b>顺带修好一个真 bug</b>：BW 时代 DoWork 要靠 InitListExecute() 从外部挂上，
                    而<b>只有外壳调过它</b>，注入模式的目标进程里从来没调 —— 于是「注入模式下
                    开始发送整份列表什么都不做」（bgwSendList 空转一下就结束）。
                    Task 自带 body，不用谁来挂，两处都好了。InitListExecute 已删。

                    取消仍是唯一真源的 sendListCts（第一步已在）。
                */
                private static CancellationTokenSource sendListCts;
                private static Task sendListTask;

                #region//发送列表索引项

                public class SendListItem
                {
                    public string SName { get; set; }

                    public Guid SID { get; set; }

                    public override string ToString()
                    {
                        return SName;
                    }
                }

                #endregion

                #region//发送入列表

                public static void SendToList(SendInfo si)
                {
                    try
                    {
                        SendConfig.List.lstSendInfo.Add(si);
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SendToList), ex);
                    }
                }

                #endregion                

                #region//执行发送列表

                /*
                    「一条都跑不了」的预检。

                    每条发送各自的拦截在 SendConfig.Send.DoSend 里（那是三条链路的咽喉），
                    这里<b>多拦一次全军覆没的情形</b>：否则 worker 照样起来、界面亮起「发送中」、
                    一秒后自己结束，而计数一个都没动 —— 又是一次「点了没反应」。

                    只在<b>全都被拦</b>时才拦：只有一部分不能跑时，剩下的照跑，
                    被拦的那几条各自会在 DoSend 里报一次。

                    ⚠️ 做成 public 是给<b>注入模式</b>用的：那边 StartSendList 跑在<b>目标进程</b>里，
                    目标里没有 UI，提示弹不出来（只剩日志经 evt 管道回到外壳的系统日志）。
                    所以外壳在把命令发过去<b>之前</b>先在自己这边跑一次同样的预检 ——
                    SystemSocket 本来就是外壳这份为准、再随 Runtime 快照推给目标的。
                */
                public static bool AllBlockedBySystemSocket()
                {
                    List<SendInfo> runnable = Operate.SendConfig.List.lstSendInfo
                        .Where(item => item.IsEnable)
                        .ToList();

                    if (runnable.Count == 0 || !runnable.All(item => Send.SystemSocketMissing(item)))
                    {
                        return false;
                    }

                    Send.NoticeSystemSocketMissing(runnable[0]);
                    return true;
                }

                public static void StartSendList()
                {
                    try
                    {
                        if (Operate.SendConfig.List.lstSendInfo.Count > 0)
                        {
                            if (!IsSendListRunning)
                            {
                                if (AllBlockedBySystemSocket())
                                {
                                    return;
                                }

                                //⚠️ 每轮一个新的：CTS 取消过就不能复位
                                if (sendListCts != null) { sendListCts.Dispose(); }
                                sendListCts = new CancellationTokenSource();

                                Operate.SendConfig.List.SendExecute_Clear();

                                CancellationToken token = sendListCts.Token;
                                sendListTask = Task.Run(() => SendList_Body(token), token);
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(StartSendList), ex);
                    }
                }

                public static void StopSendList()
                {
                    try
                    {
                        //⚠️ 只 Cancel token —— 取消只能有一个真源
                        CancellationTokenSource c = sendListCts;
                        if (c != null) { c.Cancel(); }

                        //⚠️ 先在锁里取快照，出锁再 StopSend —— 那是个会阻塞的调用，握着锁做会死锁
                        foreach (SendExecute se in Operate.SendConfig.List.SendExecute_Snapshot())
                        {
                            if (se.Running)
                            {
                                se.StopSend();
                            }

                            Operate.SendConfig.List.SendExecute_Remove(se);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(StopSendList), ex);
                    }
                }

                /*
                    ⚠️ <b>这里保留 try/catch</b>（与两个执行器<b>不同</b>）：列表级 body 没有 continuation
                    去接异常。任何异常记一条日志就好 —— 每条发送自己的结局由 SendExecute.Send_OnDone 报，
                    这一层只是驱动。取消走 token（不再有 e.Cancel 那个没人读的信号）。
                */
                public static void SendList_Body(CancellationToken token)
                {
                    try
                    {
                        for (int index = 0; index < Operate.SendConfig.List.lstSendInfo.Count; index++)
                        {
                            SendInfo si = Operate.SendConfig.List.lstSendInfo[index];
                            if (si.IsEnable)
                            {
                                SendExecute se = Operate.SendConfig.Send.DoSend(si.SID);
                                if (se != null)
                                {
                                    if (Operate.SystemConfig.ListExecute == Operate.SystemConfig.Execute.Together)
                                    {
                                        Operate.SendConfig.List.SendExecute_Add(se);
                                    }
                                    else
                                    {
                                        //⚠️ 「等某件事做完」用 WaitOne，取消当场返回（原来最坏还要睡满 10ms）
                                        while (se.Running)
                                        {
                                            if (token.WaitHandle.WaitOne(10))
                                            {
                                                se.StopSend();
                                                return;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        //「同时执行」：等所有已启动的发送各自跑完；取消就把它们停掉再走
                        bool bCancelled = false;

                        while (Operate.SendConfig.List.SendExecute_Count() > 0)
                        {
                            foreach (SendExecute se in Operate.SendConfig.List.SendExecute_Snapshot())
                            {
                                if (token.IsCancellationRequested)
                                {
                                    bCancelled = true;
                                    se.StopSend();
                                }

                                if (!se.Running)
                                {
                                    Operate.SendConfig.List.SendExecute_Remove(se);
                                }
                            }

                            /*
                                ⚠️ 取消<b>之前</b>用 WaitOne：按下停止当场醒，不必先睡满 100ms 才轮到调 StopSend。
                                ⚠️⚠️ 取消<b>之后</b>必须换回 Sleep：token 已 signaled，WaitOne 会立刻返回，
                                循环就成了<b>热自旋</b>。这一步只是在等各条发送翻成不 Running，10ms 一探足够。
                            */
                            if (bCancelled)
                            {
                                Thread.Sleep(10);
                            }
                            else if (token.WaitHandle.WaitOne(100))
                            {
                                bCancelled = true;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SendList_Body), ex);
                    }
                }

                #endregion

                #region//初始化发送列表的计数

                public static void InitSendList_Count()
                {
                    try
                    {
                        foreach (SendInfo si in lstSendInfo)
                        {
                            si.ExecutionCount = 0;
                            si.ExecutionSuccess = 0;
                            si.ExecutionFail = 0;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(InitSendList_Count), ex);
                    }
                }

                #endregion

                #region//发送列表的列表操作

                public static async Task UpdateSendList_ByListAction(SystemConfig.ListAction listAction, List<SendInfo> siList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (SendInfo si in siList)
                                {
                                    SendConfig.List.lstSendInfo.Remove(si);
                                    SendConfig.List.lstSendInfo.Insert(0, si);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (SendInfo si in siList)
                                {
                                    int iIndex = SendConfig.List.lstSendInfo.IndexOf(si);
                                    if (iIndex > 0)
                                    {
                                        SendConfig.List.lstSendInfo.Remove(si);
                                        SendConfig.List.lstSendInfo.Insert(iIndex - 1, si);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (SendInfo si in siList)
                                {
                                    int iIndex = SendConfig.List.lstSendInfo.IndexOf(si);
                                    if (iIndex > -1 && iIndex < SendConfig.List.lstSendInfo.Count - 1)
                                    {
                                        SendConfig.List.lstSendInfo.Remove(si);
                                        SendConfig.List.lstSendInfo.Insert(iIndex + 1, si);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (SendInfo si in siList)
                                {
                                    SendConfig.List.lstSendInfo.Remove(si);
                                    SendConfig.List.lstSendInfo.Add(si);
                                }

                                break;

                            case SystemConfig.ListAction.Copy:

                                foreach (SendInfo si in siList)
                                {
                                    SendConfig.Send.CopySend(si);
                                }

                                break;

                            case SystemConfig.ListAction.Export:

                                string SName = siList[0].SName;
                                await SendConfig.List.SaveSendList_Dialog(SName, siList);

                                break;

                            case SystemConfig.ListAction.Delete:

                                await SendConfig.Send.DeleteSend_Dialog(siList);

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateSendList_ByListAction), ex);
                    }
                }

                #endregion

                #region//清空发送列表（对话框）

                public static async Task CleanUpSendList_Dialog()
                {
                    if (await UI.Confirm(UI.T("InjectModeForm.miSendList", "发送列表"), UI.T("SureToDelete", "确定删除数据吗?")))
                    {
                        SendConfig.List.SendListClear();
                    }
                }

                public static void SendListClear()
                {
                    lstSendInfo.Clear();
                }

                #endregion

                #region//发送列表 - 外壳入口（只出基础类型，按 Id 收发）

                /*
                    SendInfo （当年）继承 AntdUI.NotifyProperty，一出现在外壳能看到的签名上就是 CS0012。
                    所以这一组全部按 <b>Id 字符串</b>收发、只出基础类型与 SendRow DTO ——
                    与账号、滤镜那两组同一个姿势，不给外壳加 AntdUI 引用，也不用反射。
                */

                /// <summary>按 Id 找一条。找不到返回 null。</summary>
                public static SendInfo FindSend_ById(string SID)
                {
                    try
                    {
                        if (string.IsNullOrEmpty(SID)) { return null; }

                        foreach (SendInfo si in SendConfig.List.lstSendInfo)
                        {
                            if (si.SID.ToString().Equals(SID, StringComparison.OrdinalIgnoreCase))
                            {
                                return si;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FindSend_ById), ex);
                    }

                    return null;
                }

                /// <summary>
                /// Id 数组 → 模型列表，<b>按列表里的先后顺序</b>返回。
                ///
                /// 顺序要紧：上移 / 下移是逐个做的，若按前端传来的顺序处理，
                /// 多选时会互相插队，动完的结果和用户看到的对不上。
                /// </summary>
                private static List<SendInfo> PickSends(IList<string> Ids)
                {
                    var picked = new List<SendInfo>();

                    if (Ids == null || Ids.Count == 0)
                    {
                        return picked;
                    }

                    var want = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                    foreach (string id in Ids)
                    {
                        if (!string.IsNullOrEmpty(id)) { want.Add(id); }
                    }

                    foreach (SendInfo si in SendConfig.List.lstSendInfo)
                    {
                        if (want.Contains(si.SID.ToString()))
                        {
                            picked.Add(si);
                        }
                    }

                    return picked;
                }

                /// <summary>新建一条空发送（名字自动编号），返回它的 Id。</summary>
                public static string AddSend_New_ById()
                {
                    int before = SendConfig.List.lstSendInfo.Count;

                    SendConfig.Send.AddSend_New();

                    if (SendConfig.List.lstSendInfo.Count <= before)
                    {
                        return string.Empty;
                    }

                    SendConfig.List.SaveSendList_ToDB();

                    //AddSend 是往后追加的，新的那条就在表尾
                    return SendConfig.List.lstSendInfo[SendConfig.List.lstSendInfo.Count - 1]
                        .SID.ToString().ToUpper();
                }

                /// <summary>只改启用状态。走这里才会落库。</summary>
                public static bool SetSendEnable_ById(string SID, bool IsEnable)
                {
                    SendInfo si = SendConfig.List.FindSend_ById(SID);

                    if (si == null)
                    {
                        return false;
                    }

                    si.IsEnable = IsEnable;
                    SendConfig.List.SaveSendList_ToDB();

                    //就地改属性不触发 ListChanged，得自己让下一拍推出去
                    FeedPump.MarkDirty(FeedList.Send);
                    return true;
                }

                /// <summary>全部启用 / 全部禁用（对应工具条上那两个按钮）。返回改了几条。</summary>
                public static int SetAllSendEnable(bool IsEnable)
                {
                    int n = 0;

                    foreach (SendInfo si in SendConfig.List.lstSendInfo)
                    {
                        if (si.IsEnable != IsEnable)
                        {
                            si.IsEnable = IsEnable;
                            n++;
                        }
                    }

                    if (n > 0)
                    {
                        SendConfig.List.SaveSendList_ToDB();
                        FeedPump.MarkDirty(FeedList.Send);
                    }

                    return n;
                }

                /// <summary>
                /// 重置执行 / 成功 / 失败三个计数（对应工具条的「重置计数」）。
                /// <b>不落库</b>：这三个是运行期计数，与 WinForms 一致，本来也不该进库。
                /// </summary>
                public static void ResetSendCount()
                {
                    SendConfig.List.InitSendList_Count();
                    FeedPump.MarkDirty(FeedList.Send);
                }

                /// <summary>
                /// 右键菜单的七个动作，按 Id 数组收。
                /// 动作编号照搬 <see cref="SystemConfig.ListAction"/>，与滤镜那份共用同一套语义。
                /// </summary>
                public static async Task<int> SendListAction_ByIds(int Action, IList<string> Ids)
                {
                    List<SendInfo> picked = SendConfig.List.PickSends(Ids);

                    if (picked.Count == 0)
                    {
                        return 0;
                    }

                    int before = SendConfig.List.lstSendInfo.Count;

                    await SendConfig.List.UpdateSendList_ByListAction(
                        (SystemConfig.ListAction)Action, picked);

                    /*
                        导出只是写文件，不动列表，不必落库；其余六个都动了顺序或内容。
                        删除可能被确认框取消 —— 那时条数没变，但重存一遍也无害，
                        比在这里猜「用户点没点确定」可靠。
                    */
                    if ((SystemConfig.ListAction)Action != SystemConfig.ListAction.Export)
                    {
                        SendConfig.List.SaveSendList_ToDB();
                    }

                    return SendConfig.List.lstSendInfo.Count - before;
                }

                /// <summary>清空全部（带确认框）。</summary>
                public static async Task CleanUpSendList_Dialog_Shell()
                {
                    int before = SendConfig.List.lstSendInfo.Count;

                    await SendConfig.List.CleanUpSendList_Dialog();

                    if (SendConfig.List.lstSendInfo.Count != before)
                    {
                        SendConfig.List.SaveSendList_ToDB();
                    }
                }

                /// <summary>导入发送列表（带文件框）。导进来之后要落库。</summary>
                public static async Task LoadSendList_Dialog_Shell()
                {
                    int before = SendConfig.List.lstSendInfo.Count;

                    await SendConfig.List.LoadSendList_Dialog();

                    if (SendConfig.List.lstSendInfo.Count != before)
                    {
                        SendConfig.List.SaveSendList_ToDB();
                    }
                }

                /// <summary>导出全部发送（带文件框）。不改列表，不落库。</summary>
                public static async Task SaveAllSends_Dialog()
                {
                    if (SendConfig.List.lstSendInfo.Count > 0)
                    {
                        await SendConfig.List.SaveSendList_Dialog(string.Empty, null);
                    }
                }

                /// <summary>
                /// 发送列表正在跑没有。
                ///
                /// 出 bool 而不是把内部的 Task 给出去：
                /// 但把执行器暴露出去等于让界面直接操纵它，启停的前置条件（列表非空、没在跑）
                /// 就会散成两份。启停一律走 StartSendList / StopSendList。
                /// </summary>
                public static bool IsSendListRunning
                {
                    get
                    {
                        try { return SendConfig.List.sendListTask != null && !SendConfig.List.sendListTask.IsCompleted; }
                        catch (Exception ex) { Operate.DoLog(nameof(IsSendListRunning), ex); return false; }
                    }
                }

                #endregion

                #region//保存发送列表到数据库

                public static void SaveSendList_ToDB()
                {
                    try
                    {
                        int want = SendConfig.List.lstSendInfo.Count;
                        int saved = DataBase.SaveTable_Send(SendConfig.List.lstSendInfo);

                        //内存有、库里没有 = 重启就丢，不能静默
                        if (saved != want)
                        {
                            Operate.DoLog(nameof(SaveSendList_ToDB), string.Format("发送列表落库不完整：内存 {0} 条，写入 {1} 条", want, saved));
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendList_ToDB), ex);
                    }
                }

                #endregion

                #region//从数据库加载发送列表

                public static void LoadSendList_FromDB()
                {
                    try
                    {
                        DataTable dtSend = DataBase.SelectTable_Send();

                        /*
                            发送集整表读一次，按发送分桶 —— 原来是每条发送一次查询、每次一个新连接。
                            ⚠️ 发送集的<b>顺序就是数据</b>（Send_DoWork 按下标走），
                            分桶保持原始行序，见 DataBase.GroupRowsBy。
                        */
                        var packetsBySend = DataBase.GroupRowsBy(DataBase.SelectTable_SendCollection(), "GUID");

                        foreach (DataRow dataRow in dtSend.Rows)
                        {
                            Guid SID = Guid.Parse(dataRow["GUID"].ToString());
                            bool IsEnable = Convert.ToBoolean(dataRow["IsEnable"]);
                            string SName = dataRow["Name"].ToString();
                            /*
                                ⚠️ 「使用系统套接字」<b>不从库里恢复，一律 false</b>。

                                它依赖的 SystemConfig.SystemSocket 是<b>纯运行期字段</b>（Operate.cs 顶上那个
                                static int，任何建表 / 读写配置里都没有它），每次启动必为 0。
                                所以「上次勾过」这件事跨重启没有任何意义 —— 恢复出来只会得到
                                「勾着 + 未设置」这种必然被 BlockedBySystemSocket 拦下的状态。

                                列还留着（DEFAULT 0），只为不动表结构。写出去的也一律是 false。
                            */
                            bool SSystemSocket = false;
                            int SLoopCNT = Convert.ToInt32(dataRow["LoopCNT"]);
                            int SLoopINT = Convert.ToInt32(dataRow["LoopINT"]);
                            string SNotes = dataRow["Notes"].ToString();
                            BindingList<PacketInfo> SCollection = new BindingList<PacketInfo>();

                            List<DataRow> myPackets;
                            if (packetsBySend.TryGetValue(SID.ToString().ToUpper(), out myPackets))
                            {
                                foreach (DataRow row in myPackets)
                                {
                                    int Socket = Convert.ToInt32(row["Socket"]);
                                    PacketConfig.Packet.PacketType ptType = PacketConfig.Packet.GetPacketType_ByString(row["Type"].ToString());
                                    string IPFrom = row["IPFrom"].ToString();
                                    string IPTo = row["IPTo"].ToString();
                                    byte[] Buffer = (byte[])row["Buffer"];

                                    Send.AddSendCollection(SCollection, Socket, ptType, IPFrom, IPTo, Buffer);
                                }
                            }

                            Send.AddSend(IsEnable, SID, SName, SSystemSocket, SLoopCNT, SLoopINT, SCollection, SNotes);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendList_FromDB), ex);
                    }
                }

                #endregion

                #region//保存发送列表到文件（对话框）

                public static async Task SaveSendList_Dialog(string FileName, List<SendInfo> siList)
                {
                    try
                    {
                        if (SendConfig.List.lstSendInfo.Count > 0)
                        {
                            FilePick sfdSaveFile = new FilePick();
                            sfdSaveFile.Filter = UI.T("SendListFile", "发送列表文件") + "（*.sp）|*.sp";

                            if (!string.IsNullOrEmpty(FileName))
                            {
                                sfdSaveFile.FileName = FileName;
                            }
                            
                            string sPickedPath = await UI.PickSave(sfdSaveFile);
                            if (!string.IsNullOrEmpty(sPickedPath))
                            {
                                string FilePath = sPickedPath;
                                if (!string.IsNullOrEmpty(FilePath))
                                {
                                    var EncryptPassword = await SystemConfig.GetEncryptExportAsync(UI.T("ExportSendList", "导出发送列表"));

                                    if (SaveSendList(FilePath, siList, EncryptPassword.DoEncrypt, EncryptPassword.Password))
                                    {
                                        string Title = UI.T("InjectModeForm.ExportSendList.Success", "导出发送列表成功");
                                        UI.Notify(UiIcon.Success, Title, FilePath);
                                        Operate.DoLog(nameof(SaveSendList_Dialog), Title + ": " + FilePath);
                                    }
                                    else
                                    {
                                        string Title = UI.T("InjectModeForm.ExportSendList.Error", "导出发送列表失败");
                                        string Content = UI.T("InjectModeForm.CheckSystemLog", "请检查系统日志");
                                        UI.Notify(UiIcon.Error, Title, Content);
                                    }
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendList_Dialog), ex);
                    }
                }

                private static bool SaveSendList(string FilePath, List<SendInfo> siList, bool DoEncrypt, string Password)
                {
                    try
                    {
                        XDocument xdoc = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };

                        XElement xeRoot = SendConfig.List.GetSendList_XML(siList);
                        if (xeRoot == null)
                        {
                            return false;
                        }

                        xdoc.Add(xeRoot);
                        xdoc.Save(FilePath);

                        if (DoEncrypt)
                        {
                            if (!string.IsNullOrEmpty(Password))
                            {
                                SystemConfig.EncryptXMLFile(FilePath, Password);
                            }
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveSendList), ex);
                    }

                    return false;
                }

                public static XElement GetSendList_XML(List<SendInfo> siList)
                {
                    try
                    {
                        XElement xeRoot = new XElement("SendList");

                        if (siList == null)
                        {
                            siList = Operate.SendConfig.List.lstSendInfo.ToList();
                        }

                        foreach (SendInfo si in siList)
                        {
                            XElement xeSend =
                                new XElement("Send",
                                new XElement("IsEnable", si.IsEnable.ToString()),
                                new XElement("ID", si.SID.ToString().ToUpper()),
                                new XElement("Name", si.SName),
                                new XElement("SystemSocket", false.ToString()),   //不过库，见 LoadSendList_FromDB
                                new XElement("LoopCNT", si.SLoopCNT),
                                new XElement("LoopINT", si.SLoopINT),
                                new XElement("Notes", si.SNotes)
                                );

                            if (si.SCollection.Count > 0)
                            {
                                XElement xeCollection = new XElement("SendCollection");

                                foreach (PacketInfo pi in si.SCollection)
                                {
                                    string sBuffer = SystemConfig.BytesToString(PacketConfig.Packet.EncodingFormat.Hex, pi.PacketBuffer);

                                    XElement xeColl =
                                        new XElement("Collection",
                                        new XElement("Socket", pi.PacketSocket),
                                        new XElement("Type", pi.PacketType),
                                        new XElement("IPTo", pi.PacketTo),
                                        new XElement("Buffer", sBuffer)
                                        );

                                    xeCollection.Add(xeColl);
                                }

                                xeSend.Add(xeCollection);
                            }

                            xeRoot.Add(xeSend);
                        }

                        return xeRoot;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetSendList_XML), ex);
                    }

                    return null;
                }

                #endregion

                #region//从文件加载发送列表（对话框）

                public static async Task LoadSendList_Dialog()
                {
                    try
                    {
                        FilePick ofdLoadFile = new FilePick();
                        ofdLoadFile.Filter = UI.T("SendListFile", "发送列表文件") + "（*.sp）|*.sp";

                        string sPickedPath = await UI.PickOpen(ofdLoadFile);
                        if (!string.IsNullOrEmpty(sPickedPath))
                        {
                            string FilePath = sPickedPath;
                            if (!string.IsNullOrEmpty(FilePath))
                            {
                                if (await LoadSendList(FilePath, true))
                                {
                                    string Title = UI.T("InjectModeForm.ImportSendList.Success", "导入发送列表成功");
                                    UI.Notify(UiIcon.Success, Title, FilePath);
                                    Operate.DoLog(nameof(LoadSendList_Dialog), Title + ": " + FilePath);
                                }                    
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendList_Dialog), ex);
                    }
                }

                private static async Task<bool> LoadSendList(string FilePath, bool LoadFromUser)
                {
                    try
                    {
                        if (File.Exists(FilePath))
                        {
                            XDocument xdoc = null;

                            bool bEncrypt = SystemConfig.IsEncryptXMLFile(FilePath);
                            if (bEncrypt)
                            {
                                if (LoadFromUser)
                                {
                                    xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("ImportSendList", "导入发送列表"), FilePath);
                                }
                            }
                            else
                            {
                                xdoc = XDocument.Load(FilePath);
                            }

                            if (xdoc == null)
                            {
                                string sError = UI.T("Password.Incorrect", "导入失败: 密码错误");
                                if (LoadFromUser)
                                {
                                    UI.Toast(UiIcon.Error, sError);
                                }
                                else
                                {
                                    Operate.DoLog(nameof(LoadSendList), sError);
                                }

                                return false;
                            }

                            LoadSendList_FromXDocument(xdoc);
                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendList), ex);
                    }

                    return false;
                }

                public static void LoadSendList_FromXDocument(XDocument xdoc)
                {
                    try
                    {
                        foreach (XElement xeSend in xdoc.Root.Elements())
                        {
                            bool IsEnable = false;
                            if (xeSend.Element("IsEnable") != null)
                            {
                                IsEnable = bool.Parse(xeSend.Element("IsEnable").Value);
                            }

                            Guid SID = Guid.Empty;
                            if (xeSend.Element("ID") == null || !Guid.TryParse(xeSend.Element("ID").Value, out SID) || SendConfig.Send.GetSend_ByGuid(SID) != null)
                            {
                                SID = Guid.NewGuid();
                            }

                            string SName = string.Empty;
                            if (xeSend.Element("Name") != null)
                            {
                                SName = xeSend.Element("Name").Value;
                            }

                            //不从备份里恢复，理由同 LoadSendList_FromDB 里那段
                            bool SSystemSocket = false;

                            int SLoopCNT = 1;
                            if (xeSend.Element("LoopCNT") != null)
                            {
                                SLoopCNT = int.Parse(xeSend.Element("LoopCNT").Value);
                            }

                            int SLoopINT = 1000;
                            if (xeSend.Element("LoopINT") != null)
                            {
                                SLoopINT = int.Parse(xeSend.Element("LoopINT").Value);
                            }

                            string SNotes = string.Empty;
                            if (xeSend.Element("Notes") != null)
                            {
                                SNotes = xeSend.Element("Notes").Value;
                            }

                            BindingList<PacketInfo> SCollection = new BindingList<PacketInfo>();

                            if (xeSend.Element("SendCollection") != null)
                            {
                                foreach (XElement xeCollection in xeSend.Element("SendCollection").Elements())
                                {
                                    int iSocket = 0;
                                    if (xeCollection.Element("Socket") != null)
                                    {
                                        iSocket = int.Parse(xeCollection.Element("Socket").Value);
                                    }

                                    PacketConfig.Packet.PacketType ptType = new PacketConfig.Packet.PacketType();
                                    if (xeCollection.Element("Type") != null)
                                    {
                                        ptType = PacketConfig.Packet.GetPacketType_ByString(xeCollection.Element("Type").Value);
                                    }

                                    string sIPFrom = string.Empty;
                                    if (xeCollection.Element("IPFrom") != null)
                                    {
                                        sIPFrom = xeCollection.Element("IPFrom").Value;
                                    }

                                    string sIPTo = string.Empty;
                                    if (xeCollection.Element("IPTo") != null)
                                    {
                                        sIPTo = xeCollection.Element("IPTo").Value;
                                    }

                                    byte[] bBuffer = null;
                                    if (xeCollection.Element("Buffer") != null)
                                    {
                                        bBuffer = SystemConfig.StringToBytes(PacketConfig.Packet.EncodingFormat.Hex, xeCollection.Element("Buffer").Value);
                                    }

                                    Send.AddSendCollection(SCollection, iSocket, ptType, sIPFrom, sIPTo, bBuffer);
                                }
                            }

                            Send.AddSend(IsEnable, SID, SName, SSystemSocket, SLoopCNT, SLoopINT, SCollection, SNotes);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadSendList_FromXDocument), ex);
                    }
                }

                #endregion
            }

            #endregion
        }

