                public static bool SaveRobotList(string FilePath, List<RobotInfo> riList, bool DoEncrypt, string Password)
                {
                    try
                    {
                        XDocument xdoc = new XDocument
                        {
                            Declaration = new XDeclaration("1.0", "utf-8", "yes")
                        };

                        XElement xeRoot = RobotConfig.List.GetRobotList_XML(riList);
                        if (xeRoot == null)
                        {
                            return false;
                        }

                        xdoc.Add(xeRoot);
                        xdoc.Save(FilePath);

                        if (DoEncrypt)
                        {
                            if (!string.IsNullOrEmpty(Password))
                            {
                                SystemConfig.EncryptXMLFile(FilePath, Password);
                            }
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveRobotList), ex);
                    }

                    return false;
                }

                public static XElement GetRobotList_XML(List<RobotInfo> riList)
                {
                    try
                    {
                        XElement xeRoot = new XElement("RobotList");

                        if (riList == null)
                        {
                            riList = Operate.RobotConfig.List.lstRobotInfo.ToList();
                        }

                        foreach (RobotInfo ri in riList)
                        {
                            XElement xeRobot =
                                new XElement("Robot",
                                new XElement("IsEnable", ri.IsEnable.ToString()),
                                new XElement("ID", ri.RID.ToString().ToUpper()),
                                new XElement("Name", ri.RName)
                                );

                            if (ri.RInstruction.Count > 0)
                            {
                                XElement xeInstruction = new XElement("Instructions");

                                foreach (InstructionInfo ii in ri.RInstruction)
                                {
                                    XElement xeInst = 
                                        new XElement("Inst", 
                                        new XAttribute("Type", ii.InstType), ii.InstContent);

                                    xeInstruction.Add(xeInst);
                                }

                                xeRobot.Add(xeInstruction);
                            }

                            xeRoot.Add(xeRobot);
                        }

                        return xeRoot;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetRobotList_XML), ex);
                    }

                    return null;
                }

                #endregion

                #region//从文件加载机器人列表（对话框）

                public static async Task LoadRobotList_Dialog()
                {
                    try
                    {
                        FilePick ofdLoadFile = new FilePick();

                        ofdLoadFile.Filter = UI.T("RobotListFile", "机器人列表文件") + "（*.rp）|*.rp";

                        string sPickedPath = await UI.PickOpen(ofdLoadFile);
                        if (!string.IsNullOrEmpty(sPickedPath))
                        {
                            string FilePath = sPickedPath;

                            if (!string.IsNullOrEmpty(FilePath))
                            {
                                if (await LoadRobotList(FilePath, true))
                                {
                                    string Title = UI.T("InjectModeForm.ImportRobotList.Success", "导入机器人列表成功");
                                    UI.Notify(UiIcon.Success, Title, FilePath);
                                    Operate.DoLog(nameof(LoadRobotList_Dialog), Title + ": " + FilePath);
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadRobotList_Dialog), ex);
                    }
                }

                private static async Task<bool> LoadRobotList(string FilePath, bool LoadFromUser)
                {
                    try
                    {
                        if (File.Exists(FilePath))
                        {
                            XDocument xdoc = null;

                            bool bEncrypt = SystemConfig.IsEncryptXMLFile(FilePath);
                            if (bEncrypt)
                            {
                                if (LoadFromUser)
                                {
                                    xdoc = await SystemConfig.GetEncryptImportAsync(UI.T("ImportRobotList", "导入机器人列表"), FilePath);
                                }
                            }
                            else
                            {
                                xdoc = XDocument.Load(FilePath);
                            }

                            if (xdoc == null)
                            {
                                string sError = UI.T("Password.Incorrect", "导入失败: 密码错误");
                                if (LoadFromUser)
                                {
                                    UI.Toast(UiIcon.Error, sError);
                                }
                                else
                                {
                                    Operate.DoLog(nameof(LoadRobotList), sError);
                                }

                                return false;
                            }

                            LoadRobotList_FromXDocument(xdoc);
                            return true;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadRobotList), ex);
                    }

                    return false;
                }

                public static void LoadRobotList_FromXDocument(XDocument xdoc)
                {
                    try
                    {
                        foreach (XElement xeRobot in xdoc.Root.Elements())
                        {
                            bool IsEnable = false;
                            if (xeRobot.Element("IsEnable") != null)
                            {
                                IsEnable = bool.Parse(xeRobot.Element("IsEnable").Value);
                            }

                            Guid RID = Guid.Empty;
                            if (xeRobot.Element("ID") == null || !Guid.TryParse(xeRobot.Element("ID").Value, out RID) || RobotConfig.Robot.GetRobot_ByGuid(RID) != null)
                            {
                                RID = Guid.NewGuid();
                            }

                            string RName = string.Empty;
                            if (xeRobot.Element("Name") != null)
                            {
                                RName = xeRobot.Element("Name").Value;
                            }
                            
                            BindingList<InstructionInfo> RInstruction = new BindingList<InstructionInfo>();

                            if (xeRobot.Element("Instructions") != null)
                            {
                                foreach (XElement xeInstruction in xeRobot.Element("Instructions").Elements())
                                {
                                    RobotConfig.Robot.InstructionType instructionType = RobotConfig.Robot.GetInstructionType_ByString(xeInstruction.Attribute("Type").Value);                                    
                                    RobotConfig.Robot.AddRobotInstruction(RInstruction, instructionType, xeInstruction.Value);                                    
                                }
                            }

                            Robot.AddRobot(IsEnable, RID, RName, RInstruction);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadRobotList_FromXDocument), ex);
                    }
                }

                #endregion
            }

            #endregion
        }

        #endregion

        #region//仓库配置

        public static class WareHouseConfig
        {
            #region//仓库

            public static class WareHouse
            {
                public static bool Enable_AutoStores = false;

                /*
                    ── 仓库上限 ───────────────────────────────────────────

                    仓库原来<b>没有上限也没有清理</b>：自动入库开着、命中率高，就只涨不消。
                    两个后果叠在一起：内存无界（存的还是与封包列表<b>同一个 byte[] 引用</b>，
                    列表整表清空也放不掉），以及落库越来越慢（那是整表删 + 全量插）。

                    满了<b>丢最旧的</b>，保留最近 N 条 —— 环形缓冲的语义，
                    与封包列表的自动清理同一个方向（那边是整表清空，这边不能那么干：
                    仓库是拿来「留东西」的，隔一阵全没了不像话）。

                    ⚠️ <b>加载时不裁</b>（AddStores 的 Trim 参数）。老库里可能已经攒了几万条，
                    读进来就砍等于在升级那一刻替用户做主删数据；等他<b>真的又往里加</b>时才收到上限。
                */
                public static bool StoresLimit = true;

                public static int StoresLimit_Value = 5000;

                #region//新增仓库

                public static void AddWareHouse_New()
                {
                    try
                    {
