                #region//仓库列表的列表操作

                public static async Task UpdateWareHouseList_ByListAction(SystemConfig.ListAction listAction, List<WareHouseInfo> whiList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (WareHouseInfo whi in whiList)
                                {
                                    WareHouseConfig.List.lstWareHouseInfo.Remove(whi);
                                    WareHouseConfig.List.lstWareHouseInfo.Insert(0, whi);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (WareHouseInfo whi in whiList)
                                {
                                    int iIndex = WareHouseConfig.List.lstWareHouseInfo.IndexOf(whi);
                                    if (iIndex > 0)
                                    {
                                        WareHouseConfig.List.lstWareHouseInfo.Remove(whi);
                                        WareHouseConfig.List.lstWareHouseInfo.Insert(iIndex - 1, whi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (WareHouseInfo whi in whiList)
                                {
                                    int iIndex = WareHouseConfig.List.lstWareHouseInfo.IndexOf(whi);
                                    if (iIndex > -1 && iIndex < WareHouseConfig.List.lstWareHouseInfo.Count - 1)
                                    {
                                        WareHouseConfig.List.lstWareHouseInfo.Remove(whi);
                                        WareHouseConfig.List.lstWareHouseInfo.Insert(iIndex + 1, whi);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (WareHouseInfo whi in whiList)
                                {
                                    WareHouseConfig.List.lstWareHouseInfo.Remove(whi);
                                    WareHouseConfig.List.lstWareHouseInfo.Add(whi);
                                }

                                break;

                            case SystemConfig.ListAction.Copy:

                                foreach (WareHouseInfo whi in whiList)
                                {
                                    WareHouseConfig.WareHouse.CopyWareHouse(whi);
                                }

                                break;

                            case SystemConfig.ListAction.Export:

                                string WName = whiList[0].WName;
                                await WareHouseConfig.List.SaveWareHouseList_Dialog(WName, whiList);

                                break;

                            case SystemConfig.ListAction.Delete:

                                await WareHouseConfig.WareHouse.DeleteWareHouse_Dialog(whiList);

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateWareHouseList_ByListAction), ex);
                    }
                }

                #endregion

                #region//仓储数据的列表操作

                public static async Task UpdateStores_ByListAction(BindingList<DataInfo> Stores, SystemConfig.ListAction listAction, List<DataInfo> diList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (DataInfo di in diList)
                                {
                                    Stores.Remove(di);
                                    Stores.Insert(0, di);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (DataInfo di in diList)
                                {
                                    int iIndex = Stores.IndexOf(di);
                                    if (iIndex > 0)
                                    {
                                        Stores.Remove(di);
                                        Stores.Insert(iIndex - 1, di);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (DataInfo di in diList)
                                {
                                    int iIndex = Stores.IndexOf(di);
                                    if (iIndex > -1 && iIndex < Stores.Count - 1)
                                    {
                                        Stores.Remove(di);
                                        Stores.Insert(iIndex + 1, di);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (DataInfo di in diList)
                                {
                                    Stores.Remove(di);
                                    Stores.Add(di);
                                }

                                break;

                            case SystemConfig.ListAction.Copy:

                                foreach (DataInfo di in diList)
                                {
                                    WareHouseConfig.WareHouse.AddStores(Stores, di.PacketBuffer);
                                }

                                break;

                            case SystemConfig.ListAction.Delete:

                                foreach (DataInfo di in diList)
                                {
                                    Stores.Remove(di);
                                }

                                break;

                            case SystemConfig.ListAction.Export:

                                if (diList != null)
                                {
                                    await WareHouseConfig.List.SaveStores_Dialog(string.Empty, diList);
                                }
                                else
                                {
                                    await WareHouseConfig.List.SaveStores_Dialog(string.Empty, Stores.ToList());
                                }

                                break;

                            case SystemConfig.ListAction.Import:

                                await WareHouseConfig.List.LoadStores_Dialog(Stores);

                                break;

                            case SystemConfig.ListAction.CleanUp:

                                if (Stores.Count > 0)
                                {
                                    if (await UI.Confirm(UI.T("Stores", "仓储数据"), UI.T("SureToDelete", "确定删除数据吗?")))
                                    {
                                        Stores.Clear();
                                    }
                                }

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateStores_ByListAction), ex);
                    }
                }

                #endregion

                #region//自动入库的列表操作

                public static async Task UpdateAutoStores_ByListAction(SystemConfig.ListAction listAction, AutoStoresInfo asi)
                {
                    try
                    {
                        int iIndex = 0;

                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                WareHouseConfig.List.lstAutoStoresInfo.Remove(asi);
                                WareHouseConfig.List.lstAutoStoresInfo.Insert(0, asi);

                                break;

                            case SystemConfig.ListAction.Up:

                                iIndex = WareHouseConfig.List.lstAutoStoresInfo.IndexOf(asi);
                                if (iIndex > 0)
                                {
                                    WareHouseConfig.List.lstAutoStoresInfo.Remove(asi);
                                    WareHouseConfig.List.lstAutoStoresInfo.Insert(iIndex - 1, asi);
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                iIndex = WareHouseConfig.List.lstAutoStoresInfo.IndexOf(asi);
                                if (iIndex > -1 && iIndex < WareHouseConfig.List.lstAutoStoresInfo.Count - 1)
                                {
                                    WareHouseConfig.List.lstAutoStoresInfo.Remove(asi);
                                    WareHouseConfig.List.lstAutoStoresInfo.Insert(iIndex + 1, asi);
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                WareHouseConfig.List.lstAutoStoresInfo.Remove(asi);
                                WareHouseConfig.List.lstAutoStoresInfo.Add(asi);

                                break;

                            case SystemConfig.ListAction.Import:

                                await WareHouseConfig.List.LoadAutoStores_Dialog();

                                break;

                            case SystemConfig.ListAction.Export:

                                await WareHouseConfig.List.SaveAutoStores_Dialog(string.Empty, WareHouseConfig.List.lstAutoStoresInfo);

                                break;

                            case SystemConfig.ListAction.CleanUp:

                                await WareHouseConfig.List.CleanUpAutoStores_Dialog();

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateAutoStores_ByListAction), ex);
                    }
                }

