                            Guid WID = Guid.Empty;
                            if (xeAutoStores.Element("WID") != null)
                            {
                                Guid.TryParse(xeAutoStores.Element("WID").Value, out WID);
                            }

                            WareHouseConfig.WareHouse.AddAutoStores(IsEnable, PacketHead, WID);
                        }
