                #region//从数据库加载服务器列表

                public static void LoadServerList_FromDB()
                {
                    try
                    {
                        DataTable dtServer = DataBase.SelectTable_ServerInfo();

                        //规则整表读一次，按服务器分桶。⚠️ 这张子表的外键列是 SID 不是 GUID
                        var rulesByServer = DataBase.GroupRowsBy(DataBase.SelectTable_ServerRuleInfo(), "SID");

                        foreach (DataRow drServer in dtServer.Rows)
                        {
                            Guid SID = Guid.Parse(drServer["SID"].ToString());
                            bool IsEnable = Convert.ToBoolean(drServer["IsEnable"]);
                            string ServerName = drServer["ServerName"].ToString();
                            string ServerIP = drServer["ServerIP"].ToString();
                            int ServerPort = Convert.ToInt32(drServer["ServerPort"]);
                            string ForgotURL = drServer["ForgotURL"].ToString();
                            string RegisterURL = drServer["RegisterURL"].ToString();
                            string VerifyURL = drServer["VerifyURL"].ToString();

                            BindingList<RuleInfo> Rules = new BindingList<RuleInfo>();

                            List<DataRow> myRules;
                            if (rulesByServer.TryGetValue(SID.ToString().ToUpper(), out myRules))
                            {
                                foreach (DataRow drRule in myRules)
                                {
                                    Guid RID = Guid.Parse(drRule["RID"].ToString());
                                    bool RuleIsEnable = Convert.ToBoolean(drRule["IsEnable"]);
                                    RuleType RType = (RuleType)Convert.ToInt32(drRule["RuleType"]);
                                    string RuleArgument = drRule["RuleArgument"].ToString();
                                    RuleAction RAction = (RuleAction)Convert.ToInt32(drRule["RuleAction"]);

                                    Rules.Add(new RuleInfo(RuleIsEnable, RID, RType, RuleArgument, RAction));
                                }
                            }

                            WPCConfig.ServerList.AddServer(
                                IsEnable,
                                SID,
                                ServerName,
                                ServerIP,
                                ServerPort,
                                ForgotURL,
                                RegisterURL,
                                VerifyURL,
                                Rules);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadServerList_FromDB), ex);
                    }
                }

                #endregion
            }

            #endregion

            #region//公告列表

            public static class NoticeList
            {
                public static BindingList<NoticeInfo> lstNoticeInfo = new BindingList<NoticeInfo>();

                #region//新增公告

                #region//公告列表的 XML 往返（备份用）

                public static XElement GetNoticeList_XML(BindingList<NoticeInfo> niList)
                {
                    try
                    {
                        XElement xeNoticeList = new XElement("NoticeList");

                        foreach (NoticeInfo ni in niList)
                        {
                            xeNoticeList.Add(
                                new XElement("Notice",
                                new XElement("NoticeType", ni.NoticeType),
                                new XElement("NoticeTitle", ni.NoticeTitle),
                                new XElement("NoticeContent", ni.NoticeContent),
                                new XElement("NoticeMore", ni.NoticeMore),
                                //⚠️ 时间写成往返格式（"o"），别用当前区域的短格式 —— 换台机器就解析不回来了
                                new XElement("NoticeTime", ni.NoticeTime.ToString("o"))
                                ));
                        }

                        return xeNoticeList;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(GetNoticeList_XML), ex);
                    }

                    return null;
                }

                public static void LoadNoticeList_FromXDocument(XDocument xdoc)
                {
                    try
                    {
                        foreach (XElement xeNotice in xdoc.Root.Elements())
                        {
                            int NoticeType = 0;
                            if (xeNotice.Element("NoticeType") != null)
                            {
                                int.TryParse(xeNotice.Element("NoticeType").Value, out NoticeType);
                            }

                            string Title = xeNotice.Element("NoticeTitle") == null ? string.Empty : xeNotice.Element("NoticeTitle").Value;
                            string Content = xeNotice.Element("NoticeContent") == null ? string.Empty : xeNotice.Element("NoticeContent").Value;
                            string More = xeNotice.Element("NoticeMore") == null ? string.Empty : xeNotice.Element("NoticeMore").Value;

                            //解不出来就用当下的时间，别整条丢掉
                            DateTime Time = DateTime.Now;
                            if (xeNotice.Element("NoticeTime") != null)
                            {
                                DateTime parsed;
                                if (DateTime.TryParse(xeNotice.Element("NoticeTime").Value, null,
                                        System.Globalization.DateTimeStyles.RoundtripKind, out parsed))
                                {
                                    Time = parsed;
                                }
                            }

                            //NID 与节点那边同一个理由：主键重新发，别沿用备份里的
                            WPCConfig.NoticeList.AddNotice(Guid.NewGuid(), NoticeType, Title, Content, More, Time);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadNoticeList_FromXDocument), ex);
                    }
                }

                #endregion

                public static void AddNotice(Guid NID, int NoticeType, string NoticeTitle, string NoticeContent, string NoticeMore, DateTime NoticeTime)
                {
                    try
                    {
                        if (NID != Guid.Empty && !string.IsNullOrEmpty(NoticeTitle))
                        {
                            Operate.WPCConfig.NoticeList.NoticeToList(new NoticeInfo(NID, NoticeType, NoticeTitle, NoticeContent, NoticeMore, NoticeTime));
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(AddNotice), ex);
                    }
                }

                private static void NoticeToList(NoticeInfo ni)
                {
                    try
                    {
                        if (Operate.SystemConfig.InvokeAction != null)
                        {
                            Operate.SystemConfig.InvokeAction(() =>
                            {
                                WPCConfig.NoticeList.lstNoticeInfo.Add(ni);
                            });
                        }
                        else
                        {
                            WPCConfig.NoticeList.lstNoticeInfo.Add(ni);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(NoticeToList), ex);
                    }
                }

                #endregion

                #region//编辑公告

                public static bool UpdateNotice_ByNoticeID(
                    Guid NID,
                    int NoticeType,
                    string NoticeTitle,
                    string NoticeContent,
                    string NoticeMore,
                    DateTime NoticeTime)
                {
                    try
                    {
                        if (NID != null || NID != Guid.Empty)
                        {
                            NoticeInfo ni = WPCConfig.NoticeList.lstNoticeInfo.FirstOrDefault(notice => notice.NID == NID);

                            if (ni != null)
                            {
                                ni.NoticeType = NoticeType;
                                ni.NoticeTitle = NoticeTitle;
                                ni.NoticeContent = NoticeContent;
                                ni.NoticeMore = NoticeMore;
                                ni.NoticeTime = NoticeTime;

                                return true;
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateNotice_ByNoticeID), ex);
                    }

                    return false;
                }

                #endregion

                #region//删除公告（对话框）

                public static async Task DeleteNotice_Dialog(List<NoticeInfo> niList)
                {
                    try
                    {
                        if (niList.Count > 0)
                        {
                            if (await UI.Confirm(UI.T("WPCConfig.NoticeList", "公告列表"), UI.T("SureToDelete", "确定删除数据吗?")))
                            {
                                foreach (NoticeInfo ni in niList)
                                {
                                    WPCConfig.NoticeList.lstNoticeInfo.Remove(ni);
                                }
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(DeleteNotice_Dialog), ex);
                    }
                }

                #endregion                                                

                #region//公告列表的列表操作

                public static async Task UpdateNoticeList_ByListAction(SystemConfig.ListAction listAction, List<NoticeInfo> niList)
                {
                    try
                    {
                        switch (listAction)
                        {
                            case SystemConfig.ListAction.Top:

                                foreach (NoticeInfo ni in niList)
                                {
                                    WPCConfig.NoticeList.lstNoticeInfo.Remove(ni);
                                    WPCConfig.NoticeList.lstNoticeInfo.Insert(0, ni);
                                }

                                break;

                            case SystemConfig.ListAction.Up:

                                foreach (NoticeInfo ni in niList)
                                {
                                    int iIndex = WPCConfig.NoticeList.lstNoticeInfo.IndexOf(ni);
                                    if (iIndex > 0)
                                    {
                                        WPCConfig.NoticeList.lstNoticeInfo.Remove(ni);
                                        WPCConfig.NoticeList.lstNoticeInfo.Insert(iIndex - 1, ni);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Down:

                                foreach (NoticeInfo ni in niList)
                                {
                                    int iIndex = WPCConfig.NoticeList.lstNoticeInfo.IndexOf(ni);
                                    if (iIndex > -1 && iIndex < WPCConfig.NoticeList.lstNoticeInfo.Count - 1)
                                    {
                                        WPCConfig.NoticeList.lstNoticeInfo.Remove(ni);
                                        WPCConfig.NoticeList.lstNoticeInfo.Insert(iIndex + 1, ni);
                                    }
                                }

                                break;

                            case SystemConfig.ListAction.Bottom:

                                foreach (NoticeInfo ni in niList)
                                {
                                    WPCConfig.NoticeList.lstNoticeInfo.Remove(ni);
                                    WPCConfig.NoticeList.lstNoticeInfo.Add(ni);
                                }

                                break;

                            case SystemConfig.ListAction.Delete:

                                await WPCConfig.NoticeList.DeleteNotice_Dialog(niList);

                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(UpdateNoticeList_ByListAction), ex);
                    }
                }

                #endregion

                #region//清空公告列表（对话框）

                public static async Task CleanUpNoticeList_Dialog()
                {
                    if (await UI.Confirm(UI.T("WPCConfig.NoticeList", "公告列表"), UI.T("SureToDelete", "确定删除数据吗?")))
                    {
                        WPCConfig.NoticeList.NoticeListClear();
                    }
                }

                public static void NoticeListClear()
                {
                    lstNoticeInfo.Clear();
                }

                #endregion

                #region//外壳入口：按 Id 字符串收发（WPEHybrid 用）

                public static NoticeInfo FindNotice_ById(string NID)
                {
                    Guid gid;
                    if (!Guid.TryParse(NID ?? string.Empty, out gid)) { return null; }

                    foreach (NoticeInfo ni in WPCConfig.NoticeList.lstNoticeInfo)
                    {
                        if (ni.NID == gid) { return ni; }
                    }
                    return null;
                }

                private static void PersistNotices()
                {
                    WPCConfig.NoticeList.SaveNoticeList_ToDB();
                    FeedPump.MarkDirty(FeedList.Notice);
                }

                /// <summary>新增（NID 留空）或修改一条公告。发布时间一律取现在（WinForms 也是 DateTime.Now）。</summary>
                public static string SaveNotice_Shell(string NID, int Type, string Title, string Content, string More)
                {
                    try
                    {
                        Title = (Title ?? string.Empty).Trim();
                        Content = (Content ?? string.Empty).Trim();
                        More = (More ?? string.Empty).Trim();

                        if (Type < 1 || Type > 5) { Type = 1; }
                        if (string.IsNullOrEmpty(Title)) { return UI.T("WPCConfig.NoticeList.Title.Empty", "公告标题为空"); }
                        if (string.IsNullOrEmpty(Content)) { return UI.T("WPCConfig.NoticeList.Content.Empty", "公告内容为空"); }

                        if (string.IsNullOrEmpty(NID))
                        {
                            AddNotice(Guid.NewGuid(), Type, Title, Content, More, DateTime.Now);
                        }
                        else
                        {
                            NoticeInfo ni = FindNotice_ById(NID);
                            if (ni == null) { return UI.T("WPCConfig.NoticeList.Gone", "这条公告已经不在列表里了"); }

                            UpdateNotice_ByNoticeID(ni.NID, Type, Title, Content, More, DateTime.Now);
                        }

                        PersistNotices();
                        return string.Empty;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveNotice_Shell), ex);
                        return ex.Message;
                    }
                }

                public static async Task<int> NoticeListAction_ByIds(int Action, IList<string> Ids)
                {
                    var want = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (string id in Ids ?? new List<string>()) { if (!string.IsNullOrEmpty(id)) { want.Add(id); } }

                    var picked = new List<NoticeInfo>();
                    foreach (NoticeInfo ni in WPCConfig.NoticeList.lstNoticeInfo) { if (want.Contains(ni.NID.ToString())) { picked.Add(ni); } }
                    if (picked.Count == 0) { return 0; }

                    int before = WPCConfig.NoticeList.lstNoticeInfo.Count;
                    await UpdateNoticeList_ByListAction((SystemConfig.ListAction)Action, picked);
                    PersistNotices();
                    return WPCConfig.NoticeList.lstNoticeInfo.Count - before;
                }

                public static async Task CleanUpNoticeList_Dialog_Shell()
                {
                    if (WPCConfig.NoticeList.lstNoticeInfo.Count == 0) { return; }

                    await CleanUpNoticeList_Dialog();
                    PersistNotices();
                }

                #endregion

                #region//保存公告列表到数据库

                public static void SaveNoticeList_ToDB()
                {
                    try
                    {
                        int want = WPCConfig.NoticeList.lstNoticeInfo.Count;
                        int saved = DataBase.SaveTable_NoticeInfo(WPCConfig.NoticeList.lstNoticeInfo);

                        //内存有、库里没有 = 重启就丢，不能静默
                        if (saved != want)
                        {
                            Operate.DoLog(nameof(SaveNoticeList_ToDB), string.Format("公告列表落库不完整：内存 {0} 条，写入 {1} 条", want, saved));
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(SaveNoticeList_ToDB), ex);
                    }
                }

                #endregion

                #region//从数据库加载公告列表

                public static void LoadNoticeList_FromDB()
                {
                    try
                    {
                        DataTable dtNotice = DataBase.SelectTable_NoticeInfo();

                        foreach (DataRow dataRow in dtNotice.Rows)
                        {
                            Guid NID = Guid.Parse(dataRow["NID"].ToString());
                            int NoticeType = Convert.ToInt32(dataRow["NoticeType"]);
                            string NoticeTitle = dataRow["NoticeTitle"].ToString();
                            string NoticeContent = dataRow["NoticeContent"].ToString();
                            string NoticeMore = dataRow["NoticeMore"].ToString();
                            DateTime NoticeTime = Convert.ToDateTime(dataRow["NoticeTime"]);

                            Operate.WPCConfig.NoticeList.AddNotice(NID, NoticeType, NoticeTitle, NoticeContent, NoticeMore, NoticeTime);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(LoadNoticeList_FromDB), ex);
                    }
                }

                #endregion                
            }

            #endregion
        }

        #endregion

        #region//日志配置

        public static class LogConfig
        {
            public const string ProxyLogString = "CONNECT {0} outgoing via {1} SOCKS5";

            #region//日志队列

            public static class Queue
            {
                public static ConcurrentQueue<LogInfo> cqLogInfo = new ConcurrentQueue<LogInfo>();
                public static ConcurrentQueue<FilterLogInfo> cqFilterLogInfo = new ConcurrentQueue<FilterLogInfo>();
                public static ConcurrentQueue<ProxyLogInfo> cqProxyLogInfo = new ConcurrentQueue<ProxyLogInfo>();

                #region//日志入队列

                public static async ValueTask LogToQueueAsync(string FuncName, string LogContent)
                {
                    LogInfo li = new LogInfo(FuncName, LogContent);
                    await Task.Run(() => cqLogInfo.Enqueue(li));
                }

                public static async ValueTask FilterLogToQueueAsync(
                    string FName, 
                    Operate.FilterConfig.Filter.FilterAction FAction,
                    int MatchNum,
                    Operate.PacketConfig.Packet.PacketType pType, 
                    int PacketLen)
                {
                    FilterLogInfo fli = new FilterLogInfo(FName, FAction, MatchNum, pType, PacketLen);
                    await Task.Run(() => cqFilterLogInfo.Enqueue(fli));
                }

                public static async ValueTask ProxyLogToQueueAsync(string UserName, string LoginIP, string LogContent)
                {
                    ProxyLogInfo pli = new ProxyLogInfo(UserName, LoginIP, LogContent);
                    await Task.Run(() => cqProxyLogInfo.Enqueue(pli));
                }

                #endregion

                #region//清除日志队列

                public static void ClearLogQueue()
                {
                    while (!cqLogInfo.IsEmpty)
                    {
                        cqLogInfo.TryDequeue(out LogInfo li);
                    }
                }

                public static void ClearFilterLogQueue()
                {
                    while (!cqFilterLogInfo.IsEmpty)
                    {
                        cqFilterLogInfo.TryDequeue(out FilterLogInfo fli);
                    }
                }

                public static void ClearProxyLogQueue()
                {
                    while (!cqProxyLogInfo.IsEmpty)
                    {
                        cqProxyLogInfo.TryDequeue(out ProxyLogInfo pli);
                    }
                }

                #endregion                
            }

            #endregion

            #region//日志列表

            public static class List
            {
                public static bool AutoRoll = false, AutoClear = true;
                public static decimal AutoClear_Value = 5000;
                public static BindingList<LogInfo> lstLogInfo = new BindingList<LogInfo>();
                public static BindingList<FilterLogInfo> lstFilterLogInfo = new BindingList<FilterLogInfo>();
                public static BindingList<ProxyLogInfo> lstProxyLogInfo = new BindingList<ProxyLogInfo>();

                #region//日志入列表

                /// <summary>
                /// 三个日志列表一起批量搬运（B9c 引入，取代原来每拍各 1 条的
                /// LogToList / FilterLogToList / ProxyLogToList）。
                ///
                /// 三者总是被同一个定时器一起调用，合成一个方法省掉两次调用与三处判空。
                /// 自动清理沿用日志自己的 LogConfig.List.AutoClear / AutoClear_Value。
                ///
                /// ⚠️ <b>2026-09-07 起是环形（只保留最近 N 条），不再整表清空。</b>
                /// 与封包 / 代理列表那次改动同一条口径 ——「自动清理 5000 条」读起来
                /// 就该是「留最近 5000 条」。日志尤其如此：<b>它是拿来往回翻的</b>，
                /// 整表清空会在你正查问题时把整屏一次抹掉。
                /// </summary>
                public static void FlushToFeed()
                {
                    try
                    {
                        FlushOne(Queue.cqLogInfo, lstLogInfo, FeedList.SystemLog,
                            x => LogRow.From_(x));

                        FlushOne(Queue.cqFilterLogInfo, lstFilterLogInfo, FeedList.FilterLog,
                            x => FilterLogRow.From_(x));

                        FlushOne(Queue.cqProxyLogInfo, lstProxyLogInfo, FeedList.ProxyLog,
                            x => ProxyLogRow.From_(x));

                        if (AutoClear)
                        {
                            //AutoClear_Value 是 decimal，比较与传参都要显式转
                            int keep = (int)AutoClear_Value;

                            TrimOne(lstLogInfo, FeedList.SystemLog, Queue.cqLogInfo, "SystemLogQueue", keep);
                            TrimOne(lstFilterLogInfo, FeedList.FilterLog, Queue.cqFilterLogInfo, "FilterLogQueue", keep);
                            TrimOne(lstProxyLogInfo, FeedList.ProxyLog, Queue.cqProxyLogInfo, "ProxyLogQueue", keep);
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(FlushToFeed), ex);
                    }
                }

                /// <summary>
                /// 三份日志的裁剪逻辑完全一样，抽出来避免抄三遍。
                ///
                /// <b>队列也要自己有界。</b>改成环形之前，「整表清空」是连待入列队列一起清的 ——
                /// 那是队列唯一的上限。搬运拍每次只搬 <see cref="SystemConfig.FeedBatchMax"/> 条，
                /// 日志暴涨（导入失败刷屏、SuperSocket 每条连接都打点）时队列会一直长，
                /// 于是列表有界而队列无界，内存从队列那头漏出去。
                ///
                /// ⚠️ 丢弃走 <see cref="SystemConfig.LogDropped"/>（同名 key 最多每 5 秒一条）——
                /// <b>这条日志本身就写进这三份列表</b>，不节流会自己喂自己。
                /// </summary>
                private static void TrimOne<T>(
                    BindingList<T> List,
                    FeedList Feed,
                    ConcurrentQueue<T> Queue,
                    string Where,
                    int Keep)
                {
                    if (List.Count > Keep)
                    {
                        SystemConfig.TrimOldest(List, Keep);
                        UI.Feed.Trim(Feed, Keep);
                    }

                    SystemConfig.LogDropped(Where, SystemConfig.TrimQueue(Queue, Keep));
                }

                /// <summary>三个日志列表的搬运逻辑完全一样，抽出来避免抄三遍。</summary>
                private static void FlushOne<T>(
                    ConcurrentQueue<T> Source,
                    BindingList<T> Target,
                    FeedList List,
                    Func<T, object> ToRow)
                {
                    List<T> added = null;
                    int drained = 0;

                    while (drained < SystemConfig.FeedBatchMax && Source.TryDequeue(out T item))
                    {
                        drained++;

                        if (added == null) { added = new List<T>(SystemConfig.FeedBatchMax); }
                        added.Add(item);
                    }

                    if (added == null) { return; }

                    //整批只切一次线程
                    if (Operate.SystemConfig.InvokeAction != null)
                    {
                        Operate.SystemConfig.InvokeAction(() =>
                        {
                            foreach (T item in added) { Target.Add(item); }
                        });
                    }
                    else
                    {
                        foreach (T item in added) { Target.Add(item); }
                    }

                    if (UI.Feed.NeedsRows)
                    {
                        object[] rows = new object[added.Count];
                        for (int i = 0; i < added.Count; i++) { rows[i] = ToRow(added[i]); }
                        UI.Feed.Append(List, rows);
                    }
                }

                #endregion

                #region//清除日志列表

                public static void ClearLogList()
                {
                    lstLogInfo.Clear();
                }

                public static void ClearFilterLogList()
                {
                    lstFilterLogInfo.Clear();
                }

                public static void ClearProxyLogList()
                {
                    lstProxyLogInfo.Clear();
                }

                #endregion

                #region//日志列表 - 外壳入口（三路日志按 Kind 区分，只出基础类型）

                /*
                    对应 WinForms 的 GetCMS_LogList 那三项动作（复制 / 导出到 Excel / 清空日志列表），
                    动作本身散在 Controls/LogList.cs 的三段 switch 里 —— 三路日志各抄了一遍。
                    这里按 Kind 收成一份，两套 UI 都能调。

                    Kind：0 = 系统日志、1 = 滤镜日志、2 = 代理日志。
                    与前端 SystemLog.vue 的三个页签同序，也与 FeedList.SystemLog / FilterLog / ProxyLog 同序。
                */

                /// <summary>三路日志的 Kind。前端传的是这个。</summary>
                public enum LogKind
                {
                    System = 0,
                    Filter = 1,
                    Proxy = 2,
                }

                /// <summary>
                /// 「清空日志列表」，<b>先弹确认框</b>。
                ///
                /// 队列与列表一起清（只清列表的话，下一拍搬运又会把队列里积压的搬上来），
                /// 再 UI.Feed.Clear 让前端副本跟着空 —— 与自动清理走的是同一组动作。
                /// </summary>
                public static async Task<bool> ClearLog_Dialog(int Kind)
                {
                    try
                    {
                        if (!await UI.Confirm(
                            UI.T("LogList.LogList", "日志列表"),
                            UI.T("SureToDelete", "确定删除所有数据吗")))
                        {
                            return false;
                        }

                        switch ((LogKind)Kind)
                        {
                            case LogKind.Filter:
                                Queue.ClearFilterLogQueue();
                                ClearFilterLogList();
                                UI.Feed.Clear(FeedList.FilterLog);
                                break;

                            case LogKind.Proxy:
                                Queue.ClearProxyLogQueue();
                                ClearProxyLogList();
                                UI.Feed.Clear(FeedList.ProxyLog);
                                break;

                            default:
                                Queue.ClearLogQueue();
                                ClearLogList();
                                UI.Feed.Clear(FeedList.SystemLog);
                                break;
                        }

                        return true;
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ClearLog_Dialog), ex);
                        return false;
                    }
                }

                /// <summary>
                /// 「导出到 Excel」。<b>整张表</b>，不分选中 ——
                /// WinForms 那边三个 Save*LogList_Dialog 收的就是整个 lst*，右键菜单也没往里传选中行。
                /// </summary>
                public static async Task ExportLog_Dialog(int Kind)
                {
                    try
                    {
                        string name = PacketConfig.Packet.InjectProcess;

                        switch ((LogKind)Kind)
                        {
                            case LogKind.Filter:
                                await SaveFilterLogList_Dialog(name, lstFilterLogInfo.ToList());
                                break;

                            case LogKind.Proxy:
                                await SaveProxyLogList_Dialog(name, lstProxyLogInfo.ToList());
                                break;

                            default:
                                await SaveLogList_Dialog(name, lstLogInfo.ToList());
                                break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Operate.DoLog(nameof(ExportLog_Dialog), ex);
                    }
                }

                #endregion

                #region//保存系统日志列表为Excel（对话框）

                public static async Task SaveLogList_Dialog(string FileName, List<LogInfo> liList)
                {
                    try
                    {
