                        sql += "HotKey1 TEXT,";//快捷键1
                        sql += "HotKey2 TEXT,";//快捷键2
                        sql += "HotKey3 TEXT,";//快捷键3
                        sql += "HotKey4 TEXT,";//快捷键4
                        sql += "HotKey5 TEXT,";//快捷键5
                        sql += "HotKey6 TEXT,";//快捷键6
                        sql += "HotKey7 TEXT,";//快捷键7
                        sql += "HotKey8 TEXT,";//快捷键8
                        sql += "HotKey9 TEXT,";//快捷键9
                        sql += "HotKey10 TEXT,";//快捷键10
                        sql += "HotKey11 TEXT,";//快捷键11
                        sql += "HotKey12 TEXT,";//快捷键12
                        sql += "SystemColor INTEGER,";//系统主题颜色
                        sql += "SpeedMode BOOLEAN DEFAULT 0,";//极速模式
                        sql += "FilterReplace_BackColor INTEGER,";//替换背景颜色
                        sql += "FilterReplace_ForeColor INTEGER,";//替换字体颜色
                        sql += "FilterIntercept_BackColor INTEGER,";//拦截背景颜色
                        sql += "FilterIntercept_ForeColor INTEGER,";//拦截字体颜色
                        sql += "FilterChange_BackColor INTEGER,";//换包背景颜色
                        sql += "FilterChange_ForeColor INTEGER,";//换包字体颜色
                        sql += "FilterDisplay_BackColor INTEGER,";//只显示背景颜色
                        sql += "FilterDisplay_ForeColor INTEGER,";//只显示字体颜色
                        sql += "ThemeFollowSystem BOOLEAN DEFAULT 0";//系统设置 - 主题跟随系统
                        sql += ");";

                        using (SQLiteCommand cmd = new SQLiteCommand(sql, conn))
                        {
                            conn.Open();
                            cmd.ExecuteNonQuery();

                            /*
                                ⚠️ 上面那句是 CREATE TABLE <b>IF NOT EXISTS</b> ——
                                对已经存在的库<b>一列都不会加</b>。而读配置那边是
                                Rows[0]["列名"] 直接索引，缺列当场抛。
                                所以每加一列都要在这里补一句 EnsureColumn。
                            */
                            EnsureColumn(conn, "SystemConfig", "ThemeFollowSystem", "BOOLEAN DEFAULT 0");
                            EnsureColumn(conn, "SystemConfig", "ScanLine", "BOOLEAN DEFAULT 1");
                            EnsureColumn(conn, "SystemConfig", "StoresLimit", "BOOLEAN DEFAULT 1");
                            EnsureColumn(conn, "SystemConfig", "StoresLimit_Value", "INTEGER DEFAULT 5000");
                            EnsureColumn(conn, "SystemConfig", "LastInjectMethod", "INTEGER DEFAULT 0");
                            EnsureColumn(conn, "SystemConfig", "LastInjectPath", "TEXT");
                            EnsureColumn(conn, "SystemConfig", "LastInjectArgs", "TEXT");
                            EnsureColumn(conn, "SystemConfig", "LastInjectTime", "TEXT");
                        }
                    }

                    bReturn = true;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(CreateTable_SystemConfig), ex);
                }

                return bReturn;
            }

            /// <summary>
            /// 给已存在的表补一列（没有就加，有就什么都不做）。
            ///
            /// 【为什么需要它】所有 CreateTable_* 用的都是 CREATE TABLE <b>IF NOT EXISTS</b>：
            /// 新库会照新结构建，<b>老库一列都不会加</b>。而各处读配置是
            /// <c>Rows[0]["列名"]</c> 直接索引，缺列不是返回 null 而是直接抛 ——
            /// 表现成「升级之后一启动就报错」。
            ///
            /// SQLite 的 ALTER TABLE 只支持 ADD COLUMN，且不支持 IF NOT EXISTS，
            /// 所以先用 PRAGMA table_info 查一遍。整个过程幂等，每次启动跑一遍不要钱。
            ///
            /// <b>以后往任何一张表加列，都在对应的 CreateTable_* 末尾补一句这个。</b>
            /// </summary>
            private static void EnsureColumn(SQLiteConnection Conn, string Table, string Column, string Declare)
            {
                try
                {
                    bool exists = false;

                    using (SQLiteCommand cmd = new SQLiteCommand("PRAGMA table_info(" + Table + ");", Conn))
                    using (SQLiteDataReader r = cmd.ExecuteReader())
                    {
                        while (r.Read())
                        {
                            //第 2 列（name）是列名，比较不分大小写 —— SQLite 的列名本来就不区分
                            if (string.Equals(Convert.ToString(r["name"]), Column, StringComparison.OrdinalIgnoreCase))
                            {
                                exists = true;
                                break;
                            }
                        }
                    }

                    if (exists) { return; }

                    string sql = "ALTER TABLE " + Table + " ADD COLUMN " + Column + " " + Declare + ";";

                    using (SQLiteCommand cmd = new SQLiteCommand(sql, Conn))
                    {
                        cmd.ExecuteNonQuery();
                    }

                    Operate.DoLog(nameof(EnsureColumn), "已为老库补列：" + Table + "." + Column);
                }
                catch (Exception ex)
                {
                    //补不上就记一条，别把启动整个拦下来 —— 缺列的后果由读取那边的兜底兜住
                    Operate.DoLog(nameof(EnsureColumn), ex);
                }
            }

