            #region//代理模式配置表

            private static bool CreateTable_ProxyMode()
            {
                bool bReturn = false;

                try
                {
                    using (SQLiteConnection conn = new SQLiteConnection(conStr))
                    {
                        string sql = "CREATE TABLE IF NOT EXISTS ProxyMode (";
                        sql += "ProxyIP_Auto BOOLEAN DEFAULT 1,";//代理模式 - 自动检测IP                        
                        sql += "Enable_SOCKS5 BOOLEAN DEFAULT 1,";//代理模式 - 启用SOCKS5代理
                        sql += "Enable_HTTP BOOLEAN DEFAULT 1,";//代理模式 - 启用HTTP代理
                        sql += "ProxyIP TEXT,";//代理模式 - 代理IP
                        sql += "SOCKS5_Port INTEGER DEFAULT 1080,";//代理模式 - SOCKS5代理端口                        
                        sql += "HTTP_Port INTEGER DEFAULT 1080,";//代理模式 - HTTP代理端口
                        sql += "EnableAuth BOOLEAN DEFAULT 1,";//代理模式 - 启用代理认证
                        sql += "MaxConnectionNumber INTEGER DEFAULT 5000,";//代理模式 - 最大连接数
                        sql += "Enable_UnPack BOOLEAN DEFAULT 0,";//代理模式 - 启用拆包
                        sql += "UnPack_Head TEXT,";//代理模式 - 拆包指定包头
                        sql += "UnPack_Length TEXT,";//代理模式 - 拆包长度位置
                        sql += "Enable_MapLocal BOOLEAN DEFAULT 0,";//代理模式 - 启用本地代理映射
                        sql += "Enable_MapRemote BOOLEAN DEFAULT 0,";//代理模式 - 启用远程代理映射
                        sql += "Enable_ExternalProxy BOOLEAN DEFAULT 0,";//代理模式 - 启用外部代理
                        sql += "ExternalProxy_IP TEXT,";//代理模式 - 外部代理IP
                        sql += "ExternalProxy_Port INTEGER DEFAULT 8889,";//代理模式 - 外部代理端口               
                        sql += "Enable_ExternalProxy_AppointPort BOOLEAN DEFAULT 0,";//代理模式 - 启用指定代理端口
                        sql += "ExternalProxy_AppointPort TEXT,";//代理模式 - 指定代理端口
                        sql += "Enable_ExternalProxy_Auth BOOLEAN DEFAULT 0,";//代理模式 - 启用外部代理认证
                        sql += "ExternalProxy_UserName TEXT,";//代理模式 - 外部代理用户名
                        sql += "ExternalProxy_PassWord TEXT,";//代理模式 - 外部代理密码
                        sql += "MustTCP BOOLEAN DEFAULT 1,";//代理模式 - 启用进程转代理
                        sql += "MustTCP_IP TEXT,";//代理模式 - 进程转代理IP
                        sql += "MustTCP_Port INTEGER DEFAULT 1080,";//代理模式 - 进程转代理端口（原来写的 1081 是 HTTP 代理自己的端口，真用上就成环；INSERT 一直带显式值，这个默认只在补列时才起作用）
                        sql += "MustTCP_Auth BOOLEAN DEFAULT 0,";//代理模式 - 进程转代理认证
                        sql += "MustTCP_UserName TEXT,";//代理模式 - 进程转代理用户名
                        sql += "MustTCP_PassWord TEXT,";//代理模式 - 进程转代理密码
                        sql += "MustTCP_AppointPort BOOLEAN DEFAULT 0,";//代理模式 - 进程转代理指定端口
                        sql += "MustTCP_AppointPortContent TEXT,";//代理模式 - 进程转代理指定端口
                        sql += "EnableFireWall BOOLEAN DEFAULT 0,";//代理模式 - 启用防火墙
                        sql += "WhiteListMode BOOLEAN DEFAULT 0,";//代理模式 - 是否白名单模式
                        sql += "FireWall_AutoWhiteList_AuthSuccess BOOLEAN DEFAULT 0,";//代理模式 - 自动添加认证成功的IP到白名单
                        sql += "FireWall_AutoBlackList_UnSupport BOOLEAN DEFAULT 0,";//代理模式 - 自动添加不支持的协议到黑名单
                        sql += "FireWall_AutoBlackList_AuthFail BOOLEAN DEFAULT 0,";//代理模式 - 自动添加认证失败的IP到黑名单
                        sql += "FireWall_AutoBlackList_Minutes INTEGER DEFAULT 30,";//代理模式 - 自动添加到黑名单的时间
                        sql += "FireWall_AutoClear_Expiry BOOLEAN DEFAULT 0,";//代理模式 - 自动清理过期的规则
                        sql += "DriverType INTEGER DEFAULT 1,";//代理模式 - 进程拦截的驱动类型（0 Proxifier · 1 NFAPI · 2 WinDivert）
                        sql += "SelectProcessNames TEXT";//代理模式 - 按名称拦截的进程表（一行一条 "模块名|路径"，见 SerializeSelectProcessNames）
                        sql += ");";

                        using (SQLiteCommand cmd = new SQLiteCommand(sql, conn))
                        {
                            conn.Open();
                            cmd.ExecuteNonQuery();

                            //CREATE TABLE IF NOT EXISTS 对老库一列都不会加，这两列是 2026-09-10 加的
                            EnsureColumn(conn, "ProxyMode", "DriverType", "INTEGER DEFAULT 1");
                            EnsureColumn(conn, "ProxyMode", "SelectProcessNames", "TEXT");
                        }
                    }

                    bReturn = true;
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(CreateTable_ProxyMode), ex);
                }

                return bReturn;
            }

