                        sql += "IsEnable BOOLEAN DEFAULT 0,";
                        sql += "UserName TEXT NOT NULL UNIQUE,";
                        sql += "PassWord TEXT NOT NULL,";                        
                        sql += "IsLimitLinks BOOLEAN DEFAULT 0,";
