                            SQLiteDataAdapter adapter = new SQLiteDataAdapter(cmd);
                            adapter.Fill(dtReturn);
                        }
                    }
                }
                catch (Exception ex)
                {
                    Operate.DoLog(nameof(SelectTable_ServerRuleInfo), ex);
                }

                return dtReturn;
            }

